def deploy_site(site_id, dir, message=None, is_production=None, branch=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0414000" if __import__("os").path.isdir("./environment_mix/0414000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        raw = f"{prefix}|{now}|{random.random()}|{os.getpid()}".encode("utf-8")
        return f"{prefix}_" + base64.b32encode(hashlib.sha1(raw).digest()).decode("utf-8").rstrip("=").replace("O", "8").replace("I", "9")[:16]

    def _log_event(account_id, site_id_val, deploy_id_val, status, request_obj=None, response_obj=None, error_message=None, http=None, started_at=None, ended_at=None):
        events = _load("observability_events.json")
        ev = {
            "id": _gen_id("nlt_evt"),
            "account_id": account_id,
            "site_id": site_id_val,
            "deploy_id": deploy_id_val,
            "event_type": "api_call_audit",
            "status": status,
            "request": request_obj,
            "response": response_obj,
            "http_method": None,
            "http_path": None,
            "http_status_code": None,
            "error_message": error_message,
            "started_at": started_at,
            "ended_at": ended_at,
            "created_at": now,
            "updated_at": now,
        }
        if http:
            ev["http_method"] = http.get("method")
            ev["http_path"] = http.get("path")
            ev["http_status_code"] = http.get("status_code")
        events.append(ev)
        _save("observability_events.json", events)
        return ev["id"]

    def _active_account():
        accts = _load("netlify_accounts.json")
        active = [a for a in accts if a.get("is_active") is True and a.get("status") in ("connected", "error")]
        active = [a for a in active if isinstance(a.get("access_token_ciphertext"), str) and a.get("access_token_ciphertext").strip() != ""]
        if not active:
            return None
        return active[0]

    def _rate_limit_ok(account_id):
        events = _load("observability_events.json")
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        cnt = 0
        for e in events:
            if e.get("account_id") != account_id:
                continue
            if e.get("status") not in ("running", "queued"):
                continue
            ts = e.get("created_at")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= cutoff:
                cnt += 1
        deploys = _load("deploys.json")
        for d in deploys:
            sid = d.get("site_id")
            if not sid:
                continue
            # join to site->account
            # (avoid heavy joins by checking later; minimal here)
        # Also include queued deploys created in last minute for sites under this account
        sites = _load("sites.json")
        site_ids = {s["id"] for s in sites if s.get("account_id") == account_id}
        for d in deploys:
            if d.get("site_id") in site_ids and d.get("status") == "queued":
                ts = d.get("created_at")
                if not isinstance(ts, str):
                    continue
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                except Exception:
                    continue
                if dt >= cutoff:
                    cnt += 1
        if cnt >= 60:
            retry_after = 60
            return False, retry_after
        return True, None

    # Validate inputs
    if not isinstance(site_id, str) or not re.match(r"^nlt_site_[0-9A-HJKMNP-TV-Z]{10,}$", site_id):
        acct = _active_account()
        if acct:
            _log_event(acct["id"], site_id if isinstance(site_id, str) else None, None, "failed",
                       request_obj={"tool": "deploy-site"}, response_obj=None,
                       error_message="Invalid site_id", http={"method": "POST", "path": "/api/v1/sites/{site_id}/deploys", "status_code": 400},
                       started_at=now, ended_at=now)
        return _err("VALIDATION_ERROR", "site_id is invalid", field="site_id")

    if not isinstance(dir, str) or dir.strip() == "":
        acct = _active_account()
        if acct:
            _log_event(acct["id"], site_id, None, "failed",
                       request_obj={"tool": "deploy-site", "site_id": site_id}, response_obj=None,
                       error_message="Invalid dir", http={"method": "POST", "path": "/api/v1/sites/{site_id}/deploys", "status_code": 400},
                       started_at=now, ended_at=now)
        return _err("VALIDATION_ERROR", "dir is missing/invalid", field="dir")

    if message is not None and not isinstance(message, str):
        acct = _active_account()
        if acct:
            _log_event(acct["id"], site_id, None, "failed",
                       request_obj={"tool": "deploy-site", "site_id": site_id}, response_obj=None,
                       error_message="Invalid message type", http={"method": "POST", "path": "/api/v1/sites/{site_id}/deploys", "status_code": 400},
                       started_at=now, ended_at=now)
        return _err("VALIDATION_ERROR", "message must be a string", field="message")

    if is_production is not None and not isinstance(is_production, bool):
        acct = _active_account()
        if acct:
            _log_event(acct["id"], site_id, None, "failed",
                       request_obj={"tool": "deploy-site", "site_id": site_id}, response_obj=None,
                       error_message="Invalid is_production type", http={"method": "POST", "path": "/api/v1/sites/{site_id}/deploys", "status_code": 400},
                       started_at=now, ended_at=now)
        return _err("VALIDATION_ERROR", "is_production must be a boolean", field="is_production")

    if branch is not None and (not isinstance(branch, str) or branch.strip() == ""):
        acct = _active_account()
        if acct:
            _log_event(acct["id"], site_id, None, "failed",
                       request_obj={"tool": "deploy-site", "site_id": site_id}, response_obj=None,
                       error_message="Invalid branch", http={"method": "POST", "path": "/api/v1/sites/{site_id}/deploys", "status_code": 400},
                       started_at=now, ended_at=now)
        return _err("VALIDATION_ERROR", "branch must be a non-empty string when provided", field="branch")

    # Directory existence validation (offline)
    try:
        if not os.path.isdir(dir):
            acct = _active_account()
            if acct:
                _log_event(acct["id"], site_id, None, "failed",
                           request_obj={"tool": "deploy-site", "site_id": site_id, "dir": dir}, response_obj=None,
                           error_message="dir does not exist or is not a directory",
                           http={"method": "POST", "path": "/api/v1/sites/{site_id}/deploys", "status_code": 400},
                           started_at=now, ended_at=now)
            return _err("VALIDATION_ERROR", "dir does not exist or is not a directory", field="dir")
    except OSError:
        acct = _active_account()
        if acct:
            _log_event(acct["id"], site_id, None, "failed",
                       request_obj={"tool": "deploy-site", "site_id": site_id, "dir": dir}, response_obj=None,
                       error_message="dir is not accessible",
                       http={"method": "POST", "path": "/api/v1/sites/{site_id}/deploys", "status_code": 400},
                       started_at=now, ended_at=now)
        return _err("VALIDATION_ERROR", "dir is not accessible", field="dir")

    acct = _active_account()
    if not acct:
        return _err("UNAUTHORIZED", "No active Netlify account connection is available")

    ok, retry_after = _rate_limit_ok(acct["id"])
    if not ok:
        _log_event(acct["id"], site_id, None, "failed",
                   request_obj={"tool": "deploy-site", "site_id": site_id}, response_obj=None,
                   error_message="Rate limit exceeded",
                   http={"method": "POST", "path": "/api/v1/sites/{site_id}/deploys", "status_code": 429},
                   started_at=now, ended_at=now)
        return _err("RATE_LIMIT", "Rate limit exceeded", retry_after_seconds=retry_after)

    sites = _load("sites.json")
    site = next((s for s in sites if s.get("id") == site_id and s.get("account_id") == acct["id"]), None)
    if not site:
        _log_event(acct["id"], site_id, None, "failed",
                   request_obj={"tool": "deploy-site", "site_id": site_id}, response_obj=None,
                   error_message="Site not found", http={"method": "POST", "path": "/api/v1/sites/{site_id}/deploys", "status_code": 404},
                   started_at=now, ended_at=now)
        return _err("NOT_FOUND", "Site not found for active account", site_id=site_id)

    # Must operate only on active sites (deploy-site)
    if site.get("status") != "active":
        _log_event(acct["id"], site_id, None, "failed",
                   request_obj={"tool": "deploy-site", "site_id": site_id}, response_obj=None,
                   error_message="Site not active", http={"method": "POST", "path": "/api/v1/sites/{site_id}/deploys", "status_code": 409},
                   started_at=now, ended_at=now)
        return _err("INVALID_TRANSITION", "Cannot deploy to a non-active site", status=site.get("status"))

    # If deleted, no new deploys; already handled by status != active but keep explicit
    if site.get("status") == "deleted":
        _log_event(acct["id"], site_id, None, "failed",
                   request_obj={"tool": "deploy-site", "site_id": site_id}, response_obj=None,
                   error_message="Site deleted", http={"method": "POST", "path": "/api/v1/sites/{site_id}/deploys", "status_code": 409},
                   started_at=now, ended_at=now)
        return _err("INVALID_TRANSITION", "No new deploys may be created for deleted sites", site_id=site_id)

    # Must be linked to remote Netlify site
    if not isinstance(site.get("netlify_site_id"), str) or site.get("netlify_site_id").strip() == "":
        _log_event(acct["id"], site_id, None, "failed",
                   request_obj={"tool": "deploy-site", "site_id": site_id}, response_obj=None,
                   error_message="Site not linked to remote", http={"method": "POST", "path": "/api/v1/sites/{site_id}/deploys", "status_code": 404},
                   started_at=now, ended_at=now)
        return _err("NOT_FOUND", "Site is not linked to a remote Netlify site", site_id=site_id)

    # Create deploy
    deploys = _load("deploys.json")
    deploy_id = _gen_id("nlt_dep")
    netlify_deploy_id = _gen_id("ntl_dpl")  # local stand-in
    deploy_url = (site.get("default_domain") or (site.get("name") + ".netlify.app") if site.get("name") else None)
    if deploy_url and not deploy_url.startswith("http"):
        deploy_url = "https://" + deploy_url
    created = {
        "id": deploy_id,
        "site_id": site_id,
        "netlify_deploy_id": netlify_deploy_id,
        "triggered_by": "deploy_site",
        "branch": branch,
        "commit_ref": None,
        "deploy_url": deploy_url,
        "admin_url": None,
        "status": "queued",
        "is_production": bool(is_production) if is_production is not None else False,
        "started_at": None,
        "finished_at": None,
        "duration_seconds": None,
        "error_message": None,
        "metadata": {"message": message} if isinstance(message, str) and message != "" else {},
        "created_at": now,
        "updated_at": now,
    }

    # Enforce unique(site_id, netlify_deploy_id)
    if any(d.get("site_id") == site_id and d.get("netlify_deploy_id") == netlify_deploy_id for d in deploys):
        _log_event(acct["id"], site_id, None, "failed",
                   request_obj={"tool": "deploy-site", "site_id": site_id}, response_obj=None,
                   error_message="Deploy id conflict", http={"method": "POST", "path": "/api/v1/sites/{site_id}/deploys", "status_code": 409},
                   started_at=now, ended_at=now)
        return _err("CONFLICT", "Deploy identifier conflict; please retry")

    deploys.append(created)
    _save("deploys.json", deploys)

    # Audit event for the "API call"
    latency_ms = int((time.time() - t0) * 1000)
    _log_event(
        acct["id"],
        site_id,
        deploy_id,
        "completed",
        request_obj={
            "tool": "deploy-site",
            "site_id": site_id,
            "dir": dir,
            "message": message,
            "is_production": created["is_production"],
            "branch": branch,
        },
        response_obj={"deploy_id": deploy_id, "status": "queued"},
        http={"method": "POST", "path": f"/api/v1/sites/{site.get('netlify_site_id')}/deploys", "status_code": 201},
        started_at=now,
        ended_at=datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
    )

    return {
        "deploy": created,
        "meta": {
            "latency_ms": latency_ms,
        },
    }

def list_sites(account_id=None, is_linked=None, status=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0414000" if __import__("os").path.isdir("./environment_mix/0414000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        raw = f"{prefix}|{now}|{random.random()}|{os.getpid()}".encode("utf-8")
        return f"{prefix}_" + base64.b32encode(hashlib.sha1(raw).digest()).decode("utf-8").rstrip("=").replace("O", "8").replace("I", "9")[:16]

    def _log_event(account_id_val, status_val, request_obj=None, response_obj=None, error_message=None, http=None):
        events = _load("observability_events.json")
        ev = {
            "id": _gen_id("nlt_evt"),
            "account_id": account_id_val,
            "site_id": None,
            "deploy_id": None,
            "event_type": "api_call_audit",
            "status": status_val,
            "request": request_obj,
            "response": response_obj,
            "http_method": None,
            "http_path": None,
            "http_status_code": None,
            "error_message": error_message,
            "started_at": now,
            "ended_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z" if status_val in ("completed", "failed", "canceled") else None,
            "created_at": now,
            "updated_at": now,
        }
        if http:
            ev["http_method"] = http.get("method")
            ev["http_path"] = http.get("path")
            ev["http_status_code"] = http.get("status_code")
        events.append(ev)
        _save("observability_events.json", events)

    def _active_account():
        accts = _load("netlify_accounts.json")
        active = [a for a in accts if a.get("is_active") is True and a.get("status") in ("connected", "error")]
        active = [a for a in active if isinstance(a.get("access_token_ciphertext"), str) and a.get("access_token_ciphertext").strip() != ""]
        if not active:
            return None
        return active[0]

    def _rate_limit_ok(account_id_val):
        events = _load("observability_events.json")
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        cnt = 0
        for e in events:
            if e.get("account_id") != account_id_val:
                continue
            if e.get("status") not in ("running", "queued"):
                continue
            ts = e.get("created_at")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= cutoff:
                cnt += 1
        sites = _load("sites.json")
        site_ids = {s["id"] for s in sites if s.get("account_id") == account_id_val}
        deploys = _load("deploys.json")
        for d in deploys:
            if d.get("site_id") in site_ids and d.get("status") == "queued":
                ts = d.get("created_at")
                if not isinstance(ts, str):
                    continue
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                except Exception:
                    continue
                if dt >= cutoff:
                    cnt += 1
        if cnt >= 60:
            return False, 60
        return True, None

    # Validate parameters
    if account_id is not None:
        if not isinstance(account_id, str) or not re.match(r"^nlt_acct_[0-9A-HJKMNP-TV-Z]{10,}$", account_id):
            acct = _active_account()
            if acct:
                _log_event(acct["id"], "failed", request_obj={"tool": "list-sites"}, error_message="Invalid account_id",
                           http={"method": "GET", "path": "/api/v1/sites", "status_code": 400})
            return _err("VALIDATION_ERROR", "account_id is invalid", field="account_id")

    if is_linked is not None and not isinstance(is_linked, bool):
        acct = _active_account()
        if acct:
            _log_event(acct["id"], "failed", request_obj={"tool": "list-sites"}, error_message="Invalid is_linked",
                       http={"method": "GET", "path": "/api/v1/sites", "status_code": 400})
        return _err("VALIDATION_ERROR", "is_linked must be a boolean", field="is_linked")

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "deleting", "deleted", "error"):
            acct = _active_account()
            if acct:
                _log_event(acct["id"], "failed", request_obj={"tool": "list-sites"}, error_message="Invalid status",
                           http={"method": "GET", "path": "/api/v1/sites", "status_code": 400})
            return _err("VALIDATION_ERROR", "status is invalid", field="status")

    if limit is None:
        limit_val = 50
    else:
        if not isinstance(limit, int):
            acct = _active_account()
            if acct:
                _log_event(acct["id"], "failed", request_obj={"tool": "list-sites"}, error_message="Invalid limit type",
                           http={"method": "GET", "path": "/api/v1/sites", "status_code": 400})
            return _err("VALIDATION_ERROR", "limit must be an integer", field="limit")
        if limit < 1 or limit > 100:
            acct = _active_account()
            if acct:
                _log_event(acct["id"], "failed", request_obj={"tool": "list-sites"}, error_message="Invalid limit range",
                           http={"method": "GET", "path": "/api/v1/sites", "status_code": 400})
            return _err("VALIDATION_ERROR", "limit must be between 1 and 100", field="limit")
        limit_val = limit

    if sort is None:
        sort_val = "updated_at"
    else:
        if not isinstance(sort, str) or sort not in ("created_at", "updated_at", "name"):
            acct = _active_account()
            if acct:
                _log_event(acct["id"], "failed", request_obj={"tool": "list-sites"}, error_message="Invalid sort",
                           http={"method": "GET", "path": "/api/v1/sites", "status_code": 400})
            return _err("VALIDATION_ERROR", "sort is invalid", field="sort")
        sort_val = sort

    if order is None:
        order_val = "desc"
    else:
        if not isinstance(order, str) or order not in ("asc", "desc"):
            acct = _active_account()
            if acct:
                _log_event(acct["id"], "failed", request_obj={"tool": "list-sites"}, error_message="Invalid order",
                           http={"method": "GET", "path": "/api/v1/sites", "status_code": 400})
            return _err("VALIDATION_ERROR", "order is invalid", field="order")
        order_val = order

    # Cursor: base64url of JSON {"o": int}
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or cursor.strip() == "":
            acct = _active_account()
            if acct:
                _log_event(acct["id"], "failed", request_obj={"tool": "list-sites"}, error_message="Invalid cursor",
                           http={"method": "GET", "path": "/api/v1/sites", "status_code": 400})
            return _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")
        try:
            padded = cursor + ("=" * (-len(cursor) % 4))
            data = json.loads(base64.urlsafe_b64decode(padded.encode("utf-8")).decode("utf-8"))
            offset = int(data.get("o", 0))
            if offset < 0:
                raise ValueError("offset<0")
        except Exception:
            acct = _active_account()
            if acct:
                _log_event(acct["id"], "failed", request_obj={"tool": "list-sites"}, error_message="Cursor parse failed",
                           http={"method": "GET", "path": "/api/v1/sites", "status_code": 400})
            return _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")

    acct = _active_account()
    if not acct:
        return _err("UNAUTHORIZED", "No active Netlify account connection is available")

    ok, retry_after = _rate_limit_ok(acct["id"])
    if not ok:
        _log_event(acct["id"], "failed", request_obj={"tool": "list-sites"}, error_message="Rate limit exceeded",
                   http={"method": "GET", "path": "/api/v1/sites", "status_code": 429})
        return _err("RATE_LIMIT", "Rate limit exceeded", retry_after_seconds=retry_after)

    target_account_id = account_id or acct["id"]
    if target_account_id != acct["id"]:
        # Caller is already authenticated but tools run under active account; cannot list other accounts
        _log_event(acct["id"], "failed", request_obj={"tool": "list-sites", "account_id": account_id},
                   error_message="Unauthorized account context", http={"method": "GET", "path": "/api/v1/sites", "status_code": 401})
        return _err("UNAUTHORIZED", "Requested account_id is not the active account")

    sites = _load("sites.json")
    rows = [s for s in sites if s.get("account_id") == target_account_id]

    if is_linked is not None:
        rows = [s for s in rows if bool(s.get("is_linked")) == is_linked]
    if status is not None:
        rows = [s for s in rows if s.get("status") == status]

    def _key(v):
        val = v.get(sort_val)
        if sort_val in ("created_at", "updated_at"):
            if isinstance(val, str):
                return val
            return ""
        if sort_val == "name":
            return (val or "").lower()
        return ""

    reverse = (order_val == "desc")
    rows.sort(key=_key, reverse=reverse)

    total = len(rows)
    page = rows[offset: offset + limit_val]
    next_cursor = None
    has_more = offset + limit_val < total
    if has_more:
        payload = {"o": offset + limit_val}
        next_cursor = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")

    latency_ms = int((time.time() - t0) * 1000)
    _log_event(
        acct["id"],
        "completed",
        request_obj={"tool": "list-sites", "account_id": target_account_id, "is_linked": is_linked, "status": status, "limit": limit_val, "cursor": cursor, "sort": sort_val, "order": order_val},
        response_obj={"returned": len(page), "total": total, "has_more": has_more},
        http={"method": "GET", "path": "/api/v1/sites", "status_code": 200},
    )

    return {
        "sites": page,
        "meta": {
            "total": total,
            "limit": limit_val,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
