def set_env_vars(site_id, env, override=None, is_secret=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0414000" if __import__("os").path.isdir("./environment_mix/0414000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        raw = f"{prefix}|{now}|{random.random()}|{os.getpid()}".encode("utf-8")
        return f"{prefix}_" + base64.b32encode(hashlib.sha1(raw).digest()).decode("utf-8").rstrip("=").replace("O", "8").replace("I", "9")[:16]

    def _log_event(account_id, site_id_val, status, request_obj=None, response_obj=None, error_message=None, http=None):
        events = _load("observability_events.json")
        ev = {
            "id": _gen_id("nlt_evt"),
            "account_id": account_id,
            "site_id": site_id_val,
            "deploy_id": None,
            "event_type": "api_call_audit",
            "status": status,
            "request": request_obj,
            "response": response_obj,
            "http_method": None,
            "http_path": None,
            "http_status_code": None,
            "error_message": error_message,
            "started_at": now,
            "ended_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z" if status in ("completed", "failed", "canceled") else None,
            "created_at": now,
            "updated_at": now,
        }
        if http:
            ev["http_method"] = http.get("method")
            ev["http_path"] = http.get("path")
            ev["http_status_code"] = http.get("status_code")
        events.append(ev)
        _save("observability_events.json", events)

    def _active_account():
        accts = _load("netlify_accounts.json")
        active = [a for a in accts if a.get("is_active") is True and a.get("status") in ("connected", "error")]
        active = [a for a in active if isinstance(a.get("access_token_ciphertext"), str) and a.get("access_token_ciphertext").strip() != ""]
        if not active:
            return None
        return active[0]

    def _rate_limit_ok(account_id_val):
        events = _load("observability_events.json")
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        cnt = 0
        for e in events:
            if e.get("account_id") != account_id_val:
                continue
            if e.get("status") not in ("running", "queued"):
                continue
            ts = e.get("created_at")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= cutoff:
                cnt += 1
        sites = _load("sites.json")
        site_ids = {s["id"] for s in sites if s.get("account_id") == account_id_val}
        deploys = _load("deploys.json")
        for d in deploys:
            if d.get("site_id") in site_ids and d.get("status") == "queued":
                ts = d.get("created_at")
                if not isinstance(ts, str):
                    continue
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                except Exception:
                    continue
                if dt >= cutoff:
                    cnt += 1
        if cnt >= 60:
            return False, 60
        return True, None

    # Validate inputs
    if not isinstance(site_id, str) or not re.match(r"^nlt_site_[0-9A-HJKMNP-TV-Z]{10,}$", site_id):
        acct = _active_account()
        if acct:
            _log_event(acct["id"], site_id if isinstance(site_id, str) else None, "failed",
                       request_obj={"tool": "set-env-vars"}, error_message="Invalid site_id",
                       http={"method": "PUT", "path": "/api/v1/sites/{site_id}/env", "status_code": 400})
        return _err("VALIDATION_ERROR", "site_id is invalid", field="site_id")

    if not isinstance(env, dict) or len(env) == 0:
        acct = _active_account()
        if acct:
            _log_event(acct["id"], site_id, "failed",
                       request_obj={"tool": "set-env-vars", "site_id": site_id}, error_message="env is empty/invalid",
                       http={"method": "PUT", "path": "/api/v1/sites/{site_id}/env", "status_code": 400})
        return _err("VALIDATION_ERROR", "env must be a non-empty object", field="env")

    if override is not None and not isinstance(override, bool):
        acct = _active_account()
        if acct:
            _log_event(acct["id"], site_id, "failed",
                       request_obj={"tool": "set-env-vars", "site_id": site_id}, error_message="override invalid",
                       http={"method": "PUT", "path": "/api/v1/sites/{site_id}/env", "status_code": 400})
        return _err("VALIDATION_ERROR", "override must be a boolean", field="override")

    if is_secret is not None and not isinstance(is_secret, bool):
        acct = _active_account()
        if acct:
            _log_event(acct["id"], site_id, "failed",
                       request_obj={"tool": "set-env-vars", "site_id": site_id}, error_message="is_secret invalid",
                       http={"method": "PUT", "path": "/api/v1/sites/{site_id}/env", "status_code": 400})
        return _err("VALIDATION_ERROR", "is_secret must be a boolean", field="is_secret")

    # Validate keys/values
    bad = []
    for k, v in env.items():
        if not isinstance(k, str) or not re.match(r"^[A-Z_][A-Z0-9_]*$", k):
            bad.append({"key": k, "reason": "Invalid env var name"})
            continue
        if len(k) < 1 or len(k) > 512:
            bad.append({"key": k, "reason": "Key length out of bounds"})
            continue
        if not isinstance(v, str):
            bad.append({"key": k, "reason": "Value must be a string"})
            continue
        if len(v) > 65535:
            bad.append({"key": k, "reason": "Value too long"})
            continue
    if bad:
        acct = _active_account()
        if acct:
            _log_event(acct["id"], site_id, "failed",
                       request_obj={"tool": "set-env-vars", "site_id": site_id}, error_message="Invalid env entries",
                       http={"method": "PUT", "path": "/api/v1/sites/{site_id}/env", "status_code": 400})
        return _err("VALIDATION_ERROR", "One or more env vars are invalid", details=bad)

    acct = _active_account()
    if not acct:
        return _err("UNAUTHORIZED", "No active Netlify account connection is available")

    ok, retry_after = _rate_limit_ok(acct["id"])
    if not ok:
        _log_event(acct["id"], site_id, "failed", request_obj={"tool": "set-env-vars", "site_id": site_id},
                   error_message="Rate limit exceeded", http={"method": "PUT", "path": "/api/v1/sites/{site_id}/env", "status_code": 429})
        return _err("RATE_LIMIT", "Rate limit exceeded", retry_after_seconds=retry_after)

    sites = _load("sites.json")
    site = next((s for s in sites if s.get("id") == site_id and s.get("account_id") == acct["id"]), None)
    if not site:
        _log_event(acct["id"], site_id, "failed",
                   request_obj={"tool": "set-env-vars", "site_id": site_id}, error_message="Site not found",
                   http={"method": "PUT", "path": "/api/v1/sites/{site_id}/env", "status_code": 404})
        return _err("NOT_FOUND", "Site not found for active account", site_id=site_id)

    # Must operate only on active sites
    if site.get("status") != "active":
        _log_event(acct["id"], site_id, "failed",
                   request_obj={"tool": "set-env-vars", "site_id": site_id}, error_message="Site not active",
                   http={"method": "PUT", "path": "/api/v1/sites/{site_id}/env", "status_code": 409})
        return _err("INVALID_TRANSITION", "Cannot set env vars for a non-active site", status=site.get("status"))

    # Must be linked to remote Netlify site
    if not isinstance(site.get("netlify_site_id"), str) or site.get("netlify_site_id").strip() == "":
        _log_event(acct["id"], site_id, "failed",
                   request_obj={"tool": "set-env-vars", "site_id": site_id}, error_message="Site not linked to remote",
                   http={"method": "PUT", "path": "/api/v1/sites/{site_id}/env", "status_code": 404})
        return _err("NOT_FOUND", "Site is not linked to a remote Netlify site", site_id=site_id)

    kv = _load("site_kv.json")
    override_val = bool(override) if override is not None else False
    secret_val = bool(is_secret) if is_secret is not None else False

    # Index existing active env vars
    existing = {}
    for row in kv:
        if row.get("site_id") == site_id and row.get("namespace") == "env" and row.get("status") == "active":
            existing[row.get("key")] = row

    # If override, mark missing keys as deleted
    if override_val:
        for k, row in list(existing.items()):
            if k not in env:
                row["status"] = "deleted"
                row["deleted_at"] = now
                row["updated_at"] = now

    # Upsert provided keys
    for k, v in env.items():
        row = existing.get(k)
        if row:
            row["value_text"] = v
            row["value_bytes"] = None
            row["content_type"] = None
            row["is_secret"] = secret_val
            row["etag"] = None
            row["status"] = "active"
            row["deleted_at"] = None
            row["updated_at"] = now
        else:
            kv.append({
                "id": _gen_id("nlt_kv"),
                "site_id": site_id,
                "namespace": "env",
                "key": k,
                "value_text": v,
                "value_bytes": None,
                "content_type": None,
                "is_secret": secret_val,
                "etag": None,
                "status": "active",
                "deleted_at": None,
                "created_at": now,
                "updated_at": now,
            })

    # Enforce uniqueness of active (site_id, namespace, key)
    seen = set()
    for row in kv:
        if row.get("site_id") == site_id and row.get("namespace") == "env" and row.get("status") == "active":
            t = (row.get("site_id"), row.get("namespace"), row.get("key"))
            if t in seen:
                _log_event(acct["id"], site_id, "failed",
                           request_obj={"tool": "set-env-vars", "site_id": site_id}, error_message="Active env var uniqueness conflict",
                           http={"method": "PUT", "path": "/api/v1/sites/{site_id}/env", "status_code": 409})
                return _err("CONFLICT", "Conflicting active env var keys exist; please repair local store", key=row.get("key"))
            seen.add(t)
        # Validate namespace='env' implies value_bytes null and exactly one set
        if row.get("site_id") == site_id and row.get("namespace") == "env" and row.get("status") == "active":
            if row.get("value_bytes") is not None:
                _log_event(acct["id"], site_id, "failed",
                           request_obj={"tool": "set-env-vars", "site_id": site_id}, error_message="value_bytes not allowed for env",
                           http={"method": "PUT", "path": "/api/v1/sites/{site_id}/env", "status_code": 400})
                return _err("VALIDATION_ERROR", "Env vars cannot use value_bytes", key=row.get("key"))
            if (row.get("value_text") is None) or (not isinstance(row.get("value_text"), str)):
                _log_event(acct["id"], site_id, "failed",
                           request_obj={"tool": "set-env-vars", "site_id": site_id}, error_message="value_text missing for env",
                           http={"method": "PUT", "path": "/api/v1/sites/{site_id}/env", "status_code": 400})
                return _err("VALIDATION_ERROR", "Env vars must have value_text", key=row.get("key"))

    _save("site_kv.json", kv)

    # Return env var set (redacted for secrets)
    result = {}
    for row in kv:
        if row.get("site_id") == site_id and row.get("namespace") == "env" and row.get("status") == "active":
            k = row.get("key")
            if not isinstance(k, str):
                continue
            if row.get("is_secret") is True:
                result[k] = "***REDACTED***"
            else:
                result[k] = row.get("value_text")

    latency_ms = int((time.time() - t0) * 1000)
    _log_event(
        acct["id"],
        site_id,
        "completed",
        request_obj={"tool": "set-env-vars", "site_id": site_id, "override": override_val, "is_secret": secret_val, "keys": sorted(list(env.keys()))},
        response_obj={"count": len(result)},
        http={"method": "PUT", "path": f"/api/v1/sites/{site.get('netlify_site_id')}/env", "status_code": 200},
    )

    return {
        "site_id": site_id,
        "env": result,
        "meta": {"latency_ms": latency_ms, "override": override_val},
    }

