            "http_status_code": None,
            "error_message": error_message,
            "started_at": now,
            "ended_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z" if status in ("completed", "failed", "canceled") else None,
            "created_at": now,
            "updated_at": now,
        }
        if http:
            ev["http_method"] = http.get("method")
            ev["http_path"] = http.get("path")
            ev["http_status_code"] = http.get("status_code")
        events.append(ev)
        _save("observability_events.json", events)

    def _active_account():
        accts = _load("netlify_accounts.json")
        active = [a for a in accts if a.get("is_active") is True and a.get("status") in ("connected", "error")]
        active = [a for a in active if isinstance(a.get("access_token_ciphertext"), str) and a.get("access_token_ciphertext").strip() != ""]
        if not active:
            return None
        return active[0]

    def _rate_limit_ok(account_id_val):
        events = _load("observability_events.json")
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        cnt = 0
        for e in events:
            if e.get("account_id") != account_id_val:
                continue
            if e.get("status") not in ("running", "queued"):
                continue
            ts = e.get("created_at")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= cutoff:
                cnt += 1
        sites = _load("sites.json")
        site_ids = {s["id"] for s in sites if s.get("account_id") == account_id_val}
        deploys = _load("deploys.json")
        for d in deploys:
            if d.get("site_id") in site_ids and d.get("status") == "queued":
                ts = d.get("created_at")
                if not isinstance(ts, str):
                    continue
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                except Exception:
                    continue
                if dt >= cutoff:
                    cnt += 1
        if cnt >= 60:
            return False, 60
        return True, None

    # Validate inputs
    if not isinstance(site_id, str) or not re.match(r"^nlt_site_[0-9A-HJKMNP-TV-Z]{10,}$", site_id):
        acct = _active_account()
        if acct:
            _log_event(acct["id"], site_id if isinstance(site_id, str) else None, "failed",
                       request_obj={"tool": "delete-site"}, error_message="Invalid site_id",
                       http={"method": "DELETE", "path": "/api/v1/sites/{site_id}", "status_code": 400})
        return _err("VALIDATION_ERROR", "site_id is invalid", field="site_id")

    if confirm is not True:
        acct = _active_account()
        if acct:
            _log_event(acct["id"], site_id, "failed",
                       request_obj={"tool": "delete-site", "site_id": site_id}, error_message="confirm must be true",
                       http={"method": "DELETE", "path": "/api/v1/sites/{site_id}", "status_code": 400})
        return _err("VALIDATION_ERROR", "confirm must be true to delete a site", field="confirm")

    acct = _active_account()
    if not acct:
        return _err("UNAUTHORIZED", "No active Netlify account connection is available")

    ok, retry_after = _rate_limit_ok(acct["id"])
    if not ok:
        _log_event(acct["id"], site_id, "failed",
                   request_obj={"tool": "delete-site", "site_id": site_id}, error_message="Rate limit exceeded",
                   http={"method": "DELETE", "path": "/api/v1/sites/{site_id}", "status_code": 429})
        return _err("RATE_LIMIT", "Rate limit exceeded", retry_after_seconds=retry_after)

    sites = _load("sites.json")
    site = next((s for s in sites if s.get("id") == site_id and s.get("account_id") == acct["id"]), None)
    if not site:
        _log_event(acct["id"], site_id, "failed",
                   request_obj={"tool": "delete-site", "site_id": site_id}, error_message="Site not found",
                   http={"method": "DELETE", "path": "/api/v1/sites/{site_id}", "status_code": 404})
        return _err("NOT_FOUND", "Site not found for active account", site_id=site_id)

    # Must be linked to remote Netlify site
    if not isinstance(site.get("netlify_site_id"), str) or site.get("netlify_site_id").strip() == "":
        _log_event(acct["id"], site_id, "failed",
                   request_obj={"tool": "delete-site", "site_id": site_id}, error_message="Site not linked to remote",
                   http={"method": "DELETE", "path": "/api/v1/sites/{site_id}", "status_code": 404})
        return _err("NOT_FOUND", "Site is not linked to a remote Netlify site", site_id=site_id)

    # Idempotency: if already deleted, return confirmation (but must have effect? Real APIs are often idempotent.
    # Here we treat a repeat delete as success only if already deleted.)
    if site.get("status") == "deleted":
        latency_ms = int((time.time() - t0) * 1000)
        _log_event(acct["id"], site_id, "completed",
                   request_obj={"tool": "delete-site", "site_id": site_id, "confirm": True},
                   response_obj={"deleted": True, "already_deleted": True},
                   http={"method": "DELETE", "path": f"/api/v1/sites/{site.get('netlify_site_id')}", "status_code": 200})
        return {
            "site_id": site_id,
            "deleted": True,
            "already_deleted": True,
            "deleted_at": site.get("deleted_at"),
            "meta": {"latency_ms": latency_ms},
        }

    # Transition: active/error -> deleting -> deleted; deleting -> deleted
    allowed = {
        "active": ["deleting", "error"],
        "error": ["active", "deleting"],
        "deleting": ["deleted", "error"],
        "deleted": [],
    }
    cur = site.get("status")
    if cur not in allowed:
        _log_event(acct["id"], site_id, "failed",
                   request_obj={"tool": "delete-site", "site_id": site_id, "confirm": True},
                   error_message="Unknown status",
                   http={"method": "DELETE", "path": "/api/v1/sites/{site_id}", "status_code": 409})
        return _err("INVALID_TRANSITION", "Site is in an unknown state", status=cur)

    if cur not in ("active", "error", "deleting"):
        _log_event(acct["id"], site_id, "failed",
                   request_obj={"tool": "delete-site", "site_id": site_id, "confirm": True},
                   error_message="Cannot delete from current state",
                   http={"method": "DELETE", "path": "/api/v1/sites/{site_id}", "status_code": 409})
        return _err("INVALID_TRANSITION", "Cannot delete site from current state", status=cur)

    # Step 1: set deleting if not already
    if cur != "deleting":
        if "deleting" not in allowed.get(cur, []):
            _log_event(acct["id"], site_id, "failed",
                       request_obj={"tool": "delete-site", "site_id": site_id, "confirm": True},
                       error_message="Invalid transition to deleting",
                       http={"method": "DELETE", "path": "/api/v1/sites/{site_id}", "status_code": 409})
            return _err("INVALID_TRANSITION", "Invalid transition to deleting", from_status=cur, to_status="deleting")
        site["status"] = "deleting"
        site["updated_at"] = now

    # Step 2: set deleted
    if "deleted" not in allowed.get(site.get("status"), []):
        _log_event(acct["id"], site_id, "failed",
                   request_obj={"tool": "delete-site", "site_id": site_id, "confirm": True},
                   error_message="Invalid transition to deleted",
                   http={"method": "DELETE", "path": "/api/v1/sites/{site_id}", "status_code": 409})
        return _err("INVALID_TRANSITION", "Invalid transition to deleted", from_status=site.get("status"), to_status="deleted")

    site["status"] = "deleted"
    site["deleted_at"] = now
    site["updated_at"] = now

    # Enforce constraint: deleted_at not null iff status='deleted'
    if site.get("status") == "deleted" and not site.get("deleted_at"):
        _log_event(acct["id"], site_id, "failed",
                   request_obj={"tool": "delete-site", "site_id": site_id, "confirm": True},
                   error_message="deleted_at missing",
                   http={"method": "DELETE", "path": "/api/v1/sites/{site_id}", "status_code": 500})
        return _err("CONFLICT", "Site deletion invariant failed (deleted_at missing)")

    _save("sites.json", sites)

    latency_ms = int((time.time() - t0) * 1000)
    _log_event(
        acct["id"],
        site_id,
        "completed",
        request_obj={"tool": "delete-site", "site_id": site_id, "confirm": True},
        response_obj={"deleted": True},
        http={"method": "DELETE", "path": f"/api/v1/sites/{site.get('netlify_site_id')}", "status_code": 200},
    )

    return {
        "site_id": site_id,
        "deleted": True,
        "deleted_at": site.get("deleted_at"),
        "meta": {"latency_ms": latency_ms},
    }

def get_logs(site_id, function_name=None, deploy_id=None, since=None, until=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0414000" if __import__("os").path.isdir("./environment_mix/0414000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_rfc3339(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            # Accept Z suffix
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                # Require timezone for RFC3339 in this server
                return None
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    def _gen_event_id(prefix="nlt_evt_"):
        # ULID-ish sortable id: prefix + base32(ts ms) + random suffix
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(time.time() * 1000)
        out = []
        for _ in range(10):
            out.append(alphabet[ts % 32])
            ts //= 32
        # random-ish from sha256(now+pid)
        seed = (str(time.time()) + ":" + str(os.getpid())).encode("utf-8")
        h = hashlib.sha256(seed).digest()
        for i in range(16):
            out.append(alphabet[h[i] % 32])
        return prefix + "".join(reversed(out[:10])) + "".join(out[10:])

    def _record_event(account_id, status, request_obj=None, response_obj=None, error_message=None, site_id_val=None, deploy_id_val=None, http_method=None, http_path=None, http_status_code=None):
        events = _load("observability_events.json")
        ts = _now_iso()
        ev = {
            "id": _gen_event_id(),
            "account_id": account_id,
            "site_id": site_id_val,
            "deploy_id": deploy_id_val,
            "event_type": "log_line",
            "status": status,
            "request": request_obj,
            "response": response_obj,
            "http_method": http_method,
            "http_path": http_path,
            "http_status_code": http_status_code,
            "error_message": error_message,
            "started_at": None,
            "ended_at": None,
            "created_at": ts,
            "updated_at": ts,
        }
        events.append(ev)
        _save("observability_events.json", events)
        return ev

    def _sanitize(obj):
        # Ensure no ciphertext/token-like fields are persisted
        if obj is None:
            return None
        if isinstance(obj, (str, int, float, bool)):
            return obj
        if isinstance(obj, list):
            return [_sanitize(x) for x in obj[:2000]]
        if isinstance(obj, dict):
            redacted_keys = {"access_token", "access_token_ciphertext", "token", "authorization", "auth", "password", "secret"}
            out = {}
            for k, v in obj.items():
                if isinstance(k, str) and k.lower() in redacted_keys:
                    out[k] = "[REDACTED]"
                else:
                    out[k] = _sanitize(v)
            return out
        # fallback to string
        return str(obj)

    # Validate inputs
    if not isinstance(site_id, str) or not re.match(r"^nlt_site_[0-9A-HJKMNP-TV-Z]{10,}$", site_id):
        return _err("VALIDATION_ERROR", "site_id is invalid.", field="site_id")

    if function_name is not None and not isinstance(function_name, str):
        return _err("VALIDATION_ERROR", "function_name must be a string.", field="function_name")

    if deploy_id is not None:
        if not isinstance(deploy_id, str) or not re.match(r"^nlt_dpl_[0-9A-HJKMNP-TV-Z]{10,}$", deploy_id):
            return _err("VALIDATION_ERROR", "deploy_id is invalid.", field="deploy_id")

    since_dt = None
    until_dt = None
    if since is not None:
        since_dt = _parse_rfc3339(since)
        if since_dt is None:
            return _err("VALIDATION_ERROR", "since must be a valid RFC3339 date-time with timezone.", field="since")
    if until is not None:
        until_dt = _parse_rfc3339(until)
        if until_dt is None:
            return _err("VALIDATION_ERROR", "until must be a valid RFC3339 date-time with timezone.", field="until")
    if since_dt and until_dt and since_dt > until_dt:
        return _err("VALIDATION_ERROR", "since must be <= until.", field="since")

    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 1000:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 1000.", field="limit")

    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string.", field="cursor")

    t0 = time.time()

    # Resolve active account satisfying prerequisites
    accounts = _load("netlify_accounts.json")
    active_accounts = [a for a in accounts if a.get("is_active") is True and a.get("status") in ("connected", "error") and isinstance(a.get("access_token_ciphertext"), str) and a.get("access_token_ciphertext")]
    if not active_accounts:
        # record audit without account context is impossible; still return error
        return _err("UNAUTHORIZED", "No active Netlify account connection is available.")
    account = active_accounts[0]
    account_id = account.get("id")

    # Rate limiting: per account, at most 60 executions per minute in status running/queued across observability_events
    events = _load("observability_events.json")
    now = datetime.datetime.now(datetime.timezone.utc)
    window_start = now - datetime.timedelta(minutes=1)
    active_count = 0
    for e in events:
        if e.get("account_id") != account_id:
            continue
        if e.get("status") not in ("running", "queued"):
            continue
        ca = e.get("created_at")
        if isinstance(ca, str):
            dt = _parse_rfc3339(ca) or _parse_rfc3339(ca.replace(" ", "T"))  # best-effort
            if dt and dt >= window_start:
                active_count += 1
    if active_count >= 60:
        retry_after = 60
        # Record rejected call
        _record_event(
            account_id=account_id,
            status="failed",
            request_obj=_sanitize({"tool": "get-logs", "site_id": site_id, "function_name": function_name, "deploy_id": deploy_id, "since": since, "until": until, "limit": limit, "cursor": cursor}),
            response_obj=_sanitize({"error": "RATE_LIMIT"}),
            error_message="Rate limit exceeded.",
            site_id_val=site_id,
            deploy_id_val=deploy_id,
        )
        return _err("RATE_LIMIT", "Too many requests. Please retry later.", retry_after_seconds=retry_after)

    # Validate site exists, belongs to active account, and is linked and active
    sites = _load("sites.json")
    site = next((s for s in sites if s.get("id") == site_id), None)
    if not site:
        _record_event(
            account_id=account_id,
            status="failed",
            request_obj=_sanitize({"tool": "get-logs", "site_id": site_id, "function_name": function_name, "deploy_id": deploy_id, "since": since, "until": until, "limit": limit, "cursor": cursor}),
            response_obj=_sanitize({"error": "NOT_FOUND"}),
            error_message="Site not found.",
            site_id_val=site_id,
            deploy_id_val=deploy_id,
        )
        return _err("NOT_FOUND", "Site not found.", resource="site", id=site_id)

    if site.get("account_id") != account_id:
        # Treat as not found (no cross-account access)
        _record_event(
            account_id=account_id,
            status="failed",
            request_obj=_sanitize({"tool": "get-logs", "site_id": site_id, "function_name": function_name, "deploy_id": deploy_id, "since": since, "until": until, "limit": limit, "cursor": cursor}),
            response_obj=_sanitize({"error": "NOT_FOUND"}),
            error_message="Site not found for active account.",
            site_id_val=site_id,
            deploy_id_val=deploy_id,
        )
        return _err("NOT_FOUND", "Site not found.", resource="site", id=site_id)

    if site.get("status") != "active":
        _record_event(
            account_id=account_id,
            status="failed",
            request_obj=_sanitize({"tool": "get-logs", "site_id": site_id, "function_name": function_name, "deploy_id": deploy_id, "since": since, "until": until, "limit": limit, "cursor": cursor}),
            response_obj=_sanitize({"error": "NOT_FOUND"}),
            error_message="Site is not active.",
            site_id_val=site_id,
            deploy_id_val=deploy_id,
        )
        return _err("NOT_FOUND", "Site is not active.", resource="site", id=site_id, status=site.get("status"))

    if site.get("is_linked") is not True or not site.get("local_repo_root"):
        _record_event(
            account_id=account_id,
            status="failed",
            request_obj=_sanitize({"tool": "get-logs", "site_id": site_id, "function_name": function_name, "deploy_id": deploy_id, "since": since, "until": until, "limit": limit, "cursor": cursor}),
            response_obj=_sanitize({"error": "NOT_FOUND"}),
            error_message="Site is not linked.",
            site_id_val=site_id,
            deploy_id_val=deploy_id,
        )
        return _err("NOT_FOUND", "Site is not linked.", resource="site", id=site_id)

    # Validate deploy if provided (must exist and belong to site); historical deploy reads allowed, but site must be active per tool rules
    deploys = _load("deploys.json")
    deploy_row = None
    if deploy_id is not None:
        deploy_row = next((d for d in deploys if d.get("id") == deploy_id), None)
        if not deploy_row:
            _record_event(
                account_id=account_id,
                status="failed",
                request_obj=_sanitize({"tool": "get-logs", "site_id": site_id, "function_name": function_name, "deploy_id": deploy_id, "since": since, "until": until, "limit": limit, "cursor": cursor}),
                response_obj=_sanitize({"error": "VALIDATION_ERROR"}),
                error_message="deploy_id does not exist.",
                site_id_val=site_id,
                deploy_id_val=deploy_id,
            )
            return _err("VALIDATION_ERROR", "deploy_id does not reference an existing deploy.", field="deploy_id")
        if deploy_row.get("site_id") != site_id:
            _record_event(
                account_id=account_id,
                status="failed",
                request_obj=_sanitize({"tool": "get-logs", "site_id": site_id, "function_name": function_name, "deploy_id": deploy_id, "since": since, "until": until, "limit": limit, "cursor": cursor}),
                response_obj=_sanitize({"error": "VALIDATION_ERROR"}),
                error_message="deploy_id does not belong to site.",
                site_id_val=site_id,
                deploy_id_val=deploy_id,
            )
            return _err("VALIDATION_ERROR", "deploy_id does not belong to the specified site.", field="deploy_id")

    # Cursor handling
    # Cursor format: "ts=<iso>;off=<int>" (opaque to caller but validated here)
    offset = 0
    cursor_since_floor = None
    if cursor:
        if not cursor.startswith("ts=") or ";off=" not in cursor:
            return _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")
        ts_part, off_part = cursor.split(";off=", 1)
        ts_val = ts_part[3:]
        cursor_since_floor = _parse_rfc3339(ts_val)
        if cursor_since_floor is None:
            return _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")
        try:
            offset = int(off_part)
        except ValueError:
            return _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")
        if offset < 0:
            return _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")

    # Gather logs from observability_events log_line events for this site
    # Each event may represent one line; expect response like {"line": "...", "timestamp": "...", "function_name": "...", "deploy_id": "..."} best-effort.
    def _extract_line(ev):
        resp = ev.get("response") if isinstance(ev.get("response"), dict) else {}
        req = ev.get("request") if isinstance(ev.get("request"), dict) else {}
        line = resp.get("line") if isinstance(resp.get("line"), str) else resp.get("message") if isinstance(resp.get("message"), str) else None
        ts = resp.get("timestamp") if isinstance(resp.get("timestamp"), str) else ev.get("created_at")
        fn = resp.get("function_name") if isinstance(resp.get("function_name"), str) else req.get("function_name") if isinstance(req.get("function_name"), str) else None
        dpl = resp.get("deploy_id") if isinstance(resp.get("deploy_id"), str) else req.get("deploy_id") if isinstance(req.get("deploy_id"), str) else ev.get("deploy_id")
        return line, ts, fn, dpl

    candidates = []
    for ev in events:
        if ev.get("event_type") != "log_line":
            continue
        if ev.get("account_id") != account_id:
            continue
        if ev.get("site_id") != site_id:
            continue
        line, ts_s, fn, dpl = _extract_line(ev)
        if line is None:
            continue
        if function_name is not None and fn != function_name:
            continue
        if deploy_id is not None and dpl != deploy_id:
            continue
        dt = _parse_rfc3339(ts_s) if isinstance(ts_s, str) else None
        if dt is None:
            continue
        if since_dt and dt < since_dt:
            continue
        if until_dt and dt > until_dt:
            continue
        if cursor_since_floor and dt < cursor_since_floor:
            continue
        candidates.append((dt, ev, line, fn, dpl, ts_s))

    # Sort ascending by timestamp then by id for stability
    candidates.sort(key=lambda x: (x[0], x[1].get("id") or ""))

    total = len(candidates)
    page = candidates[offset:offset + limit]
    next_cursor = None
    has_more = offset + limit < total
    if has_more:
        # cursor anchored to earliest timestamp in result window (or since/now) to keep consistent
        anchor_dt = cursor_since_floor or (since_dt if since_dt else (page[0][0] if page else now))
        next_cursor = f"ts={anchor_dt.isoformat()};off={offset + limit}"

    lines_out = []
    for dt, ev, line, fn, dpl, ts_s in page:
        lines_out.append({
            "timestamp": dt.isoformat(),
            "line": line,
            "function_name": fn,
            "deploy_id": dpl,
            "event_id": ev.get("id"),
        })

    latency_ms = int((time.time() - t0) * 1000)

    # Record audit event (as log_line event_type already used for individual lines; we also store a snapshot-style response here in a log_line record)
    _record_event(
        account_id=account_id,
        status="completed",
        request_obj=_sanitize({"tool": "get-logs", "site_id": site_id, "function_name": function_name, "deploy_id": deploy_id, "since": since, "until": until, "limit": limit, "cursor": cursor}),
        response_obj=_sanitize({"count": len(lines_out), "has_more": has_more}),
        error_message=None,
        site_id_val=site_id,
        deploy_id_val=deploy_id,
    )

    return {
        "site_id": site_id,
        "function_name": function_name,
        "deploy_id": deploy_id,
        "since": since_dt.isoformat() if since_dt else None,
        "until": until_dt.isoformat() if until_dt else None,
        "lines": lines_out,
        "pagination": {
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "total": total,
            "offset": offset,
        },
        "meta": {
            "account_id": account_id,
            "latency_ms": latency_ms,
        },
    }

def trigger_build(site_id, branch=None, clear_cache=None, message=None, **_extra):
    import json, os, datetime, time, re, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0414000" if __import__("os").path.isdir("./environment_mix/0414000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now = now_dt.isoformat()

    accounts = _load("netlify_accounts.json")
    sites = _load("sites.json")
    deploys = _load("deploys.json")
    events = _load("observability_events.json")

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _parse_rfc3339(s):
        if not isinstance(s, str):
            return None
        v = s.strip()
        if not v:
            return None
        try:
            if v.endswith("Z"):
                v = v[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(v)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _find_active_account():
        for a in accounts:
            if a.get("is_active") is True and a.get("status") in ("connected", "error") and isinstance(a.get("access_token_ciphertext"), str) and a.get("access_token_ciphertext"):
                return a
        for a in accounts:
            if a.get("status") in ("connected", "error") and isinstance(a.get("access_token_ciphertext"), str) and a.get("access_token_ciphertext"):
                return a
        return None

    def _rate_limited(account_id):
        one_min_ago = now_dt - datetime.timedelta(seconds=60)
        cnt = 0
        for e in events:
            if e.get("account_id") != account_id:
                continue
            if e.get("status") not in ("running", "queued"):
                continue
            ts = _parse_rfc3339(e.get("created_at"))
            if ts and ts >= one_min_ago:
                cnt += 1
        for d in deploys:
            srow = next((s for s in sites if s.get("id") == d.get("site_id")), None)
            if not srow or srow.get("account_id") != account_id:
                continue
            if d.get("status") in ("queued", "building", "uploading", "restoring"):
                ts = _parse_rfc3339(d.get("created_at"))
                if ts and ts >= one_min_ago:
                    cnt += 1
        if cnt >= 60:
            return True, 60
        return False, None

    def _append_event(account_id, status, site_row=None, deploy_row=None, request_obj=None, response_obj=None, error_message=None):
        ev = {
            "id": _new_id("nlt_evt"),
            "account_id": account_id,
            "site_id": site_row.get("id") if site_row else None,
            "deploy_id": deploy_row.get("id") if deploy_row else None,
            "event_type": "api_call_audit",
            "status": status,
            "request": request_obj,
            "response": response_obj,
            "http_method": "POST",
            "http_path": "/api/v1/sites/{site_id}/builds".format(site_id=(site_row.get("netlify_site_id") if site_row else "unknown")),
            "http_status_code": 202 if status == "completed" else 400,
            "error_message": error_message,
            "started_at": now,
            "ended_at": now if status in ("completed", "failed", "canceled") else None,
            "created_at": now,
            "updated_at": now,
        }
        events.append(ev)
        _save("observability_events.json", events)

    acct = _find_active_account()
    if not acct:
        return _err("UNAUTHORIZED", "No active Netlify account connection is available for this operation.")

    limited, retry_after = _rate_limited(acct["id"])
    if limited:
        _append_event(acct["id"], "failed", request_obj={"tool": "trigger-build"}, error_message="Rate limit exceeded")
        return _err("RATE_LIMIT", "Rate limit exceeded.", retry_after=retry_after)

    if not isinstance(site_id, str) or not re.match(r"^nlt_site_[0-9A-HJKMNP-TV-Z]{10,}$", site_id):
        _append_event(acct["id"], "failed", request_obj={"site_id": site_id}, error_message="Invalid site_id")
        return _err("VALIDATION_ERROR", "site_id is invalid.")
    if branch is not None and (not isinstance(branch, str) or not branch.strip() or len(branch) > 256):
        _append_event(acct["id"], "failed", request_obj={"site_id": site_id, "branch": branch}, error_message="Invalid branch")
        return _err("VALIDATION_ERROR", "branch must be a non-empty string up to 256 chars when provided.")
    if clear_cache is not None and not isinstance(clear_cache, bool):
        _append_event(acct["id"], "failed", request_obj={"site_id": site_id, "clear_cache": clear_cache}, error_message="Invalid clear_cache")
        return _err("VALIDATION_ERROR", "clear_cache must be a boolean when provided.")
    if message is not None and (not isinstance(message, str) or len(message) > 1024):
        _append_event(acct["id"], "failed", request_obj={"site_id": site_id, "message": message}, error_message="Invalid message")
        return _err("VALIDATION_ERROR", "message must be a string up to 1024 chars when provided.")

    site = next((s for s in sites if s.get("id") == site_id), None)
    if not site:
        _append_event(acct["id"], "failed", request_obj={"site_id": site_id}, error_message="Site not found")
        return _err("NOT_FOUND", "Site not found.")
    if site.get("account_id") != acct["id"]:
        _append_event(acct["id"], "failed", site_row=site, request_obj={"site_id": site_id}, error_message="Unauthorized site")
        return _err("UNAUTHORIZED", "Site does not belong to the active account.")
    if site.get("is_linked") is not True or not site.get("local_repo_root"):
        _append_event(acct["id"], "failed", site_row=site, request_obj={"site_id": site_id}, error_message="Site not linked")
        return _err("NOT_FOUND", "Site is not linked to a local directory.")
    if site.get("status") != "active":
        _append_event(acct["id"], "failed", site_row=site, request_obj={"site_id": site_id}, error_message="Site not active")
        return _err("NOT_FOUND", "Site is not active.")
    if not isinstance(site.get("netlify_site_id"), str) or not site.get("netlify_site_id"):
        _append_event(acct["id"], "failed", site_row=site, request_obj={"site_id": site_id}, error_message="Missing netlify_site_id")
        return _err("NOT_FOUND", "Site is not linked to a remote Netlify site.")

    # Business rule: once deleted, no new deploys.
    if site.get("status") == "deleted" or site.get("status") == "deleting":
        _append_event(acct["id"], "failed", site_row=site, request_obj={"site_id": site_id}, error_message="Site is deleting/deleted")
        return _err("INVALID_TRANSITION", "Cannot create deploys for a deleting/deleted site.")

    # Create deploy record (queued) and simulate minimal progression to building (legal transition).
    dpl_id = _new_id("nlt_dpl")
    netlify_deploy_id = _new_id("netlify_dpl")

    use_branch = branch.strip() if isinstance(branch, str) and branch.strip() else site.get("repo_branch") or None

    deploy_row = {
        "id": dpl_id,
        "site_id": site_id,
        "netlify_deploy_id": netlify_deploy_id,
        "triggered_by": "trigger_build",
        "branch": use_branch,
        "commit_ref": None,
        "deploy_url": None,
        "admin_url": None,
        "status": "queued",
        "is_production": True if (use_branch is None or use_branch == site.get("repo_branch")) else False,
        "started_at": None,
        "finished_at": None,
        "duration_seconds": None,
        "error_message": None,
        "metadata": {
            "clear_cache": bool(clear_cache) if clear_cache is not None else False,
            "message": message,
        },
        "created_at": now,
        "updated_at": now,
    }

    # Enforce uniqueness(site_id, netlify_deploy_id)
    if any(d.get("site_id") == site_id and d.get("netlify_deploy_id") == netlify_deploy_id for d in deploys):
        _append_event(acct["id"], "failed", site_row=site, request_obj={"site_id": site_id}, error_message="Deploy id conflict")
        return _err("CONFLICT", "A deploy with the same Netlify deploy id already exists for this site.")

    deploys.append(deploy_row)
    _save("deploys.json", deploys)

    # Progress to building (queued -> building) to reflect "queued/running state"
    deploy_row["status"] = "building"
    deploy_row["started_at"] = now
    deploy_row["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
    _save("deploys.json", deploys)

    _append_event(
        acct["id"],
        "completed",
        site_row=site,
        deploy_row=deploy_row,
        request_obj={"site_id": site_id, "branch": branch, "clear_cache": clear_cache, "message": message},
        response_obj={"deploy_id": deploy_row["id"], "status": deploy_row["status"]},
        error_message=None
    )

    return {
        "site_id": site_id,
        "deploy": deploy_row,
        "meta": {
            "account_id": acct["id"],
            "latency_ms": int((time.time() - t0) * 1000)
        }
    }

def link_site(site_id, dir, **_extra):
    import json, os, datetime, time, re, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0414000" if __import__("os").path.isdir("./environment_mix/0414000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()

    accounts = _load("netlify_accounts.json")
    sites = _load("sites.json")
    events = _load("observability_events.json")
    deploys = _load("deploys.json")

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _parse_rfc3339(s):
        if not isinstance(s, str):
            return None
        v = s.strip()
        if not v:
            return None
        try:
            if v.endswith("Z"):
                v = v[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(v)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _find_active_account():
        for a in accounts:
            if a.get("is_active") is True and a.get("status") in ("connected", "error") and isinstance(a.get("access_token_ciphertext"), str) and a.get("access_token_ciphertext"):
                return a
        for a in accounts:
            if a.get("status") in ("connected", "error") and isinstance(a.get("access_token_ciphertext"), str) and a.get("access_token_ciphertext"):
                return a
        return None

    def _rate_limited(account_id):
        one_min_ago = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(seconds=60)
        cnt = 0
        for e in events:
            if e.get("account_id") != account_id:
                continue
            if e.get("status") not in ("running", "queued"):
                continue
            ts = _parse_rfc3339(e.get("created_at"))
            if ts and ts >= one_min_ago:
                cnt += 1
        for d in deploys:
            srow = next((s for s in sites if s.get("id") == d.get("site_id")), None)
            if not srow or srow.get("account_id") != account_id:
                continue
            if d.get("status") in ("queued", "building", "uploading", "restoring"):
                ts = _parse_rfc3339(d.get("created_at"))
                if ts and ts >= one_min_ago:
                    cnt += 1
        if cnt >= 60:
            return True, 60
        return False, None

    def _append_event(account_id, status, site_row=None, request_obj=None, response_obj=None, error_message=None):
        ev = {
            "id": _new_id("nlt_evt"),
            "account_id": account_id,
            "site_id": site_row.get("id") if site_row else None,
            "deploy_id": None,
            "event_type": "open_site_action",
            "status": status,
            "request": request_obj,
            "response": response_obj,
            "http_method": None,
            "http_path": None,
            "http_status_code": None,
            "error_message": error_message,
            "started_at": None,
            "ended_at": now if status in ("completed", "failed", "canceled") else None,
            "created_at": now,
            "updated_at": now,
        }
        events.append(ev)
        _save("observability_events.json", events)

    acct = _find_active_account()
    if not acct:
        return _err("UNAUTHORIZED", "No active Netlify account connection is available for this operation.")

    limited, retry_after = _rate_limited(acct["id"])
    if limited:
        _append_event(acct["id"], "failed", request_obj={"tool": "link-site"}, error_message="Rate limit exceeded")
        return _err("RATE_LIMIT", "Rate limit exceeded.", retry_after=retry_after)

    if not isinstance(site_id, str) or not re.match(r"^nlt_site_[0-9A-HJKMNP-TV-Z]{10,}$", site_id):
        _append_event(acct["id"], "failed", request_obj={"site_id": site_id, "dir": dir}, error_message="Invalid site_id")
        return _err("VALIDATION_ERROR", "site_id is invalid.")
    if not isinstance(dir, str) or not dir.strip():
        _append_event(acct["id"], "failed", request_obj={"site_id": site_id, "dir": dir}, error_message="Invalid dir")
        return _err("VALIDATION_ERROR", "dir must be a non-empty string.")
    norm_dir = os.path.normpath(dir.strip())

    site = next((s for s in sites if s.get("id") == site_id), None)
    if not site:
        _append_event(acct["id"], "failed", request_obj={"site_id": site_id, "dir": norm_dir}, error_message="Site not found")
        return _err("NOT_FOUND", "Site not found.")
    if site.get("account_id") != acct["id"]:
        _append_event(acct["id"], "failed", site_row=site, request_obj={"site_id": site_id, "dir": norm_dir}, error_message="Unauthorized site")
        return _err("UNAUTHORIZED", "Site does not belong to the active account.")

    if site.get("status") != "active":
        _append_event(acct["id"], "failed", site_row=site, request_obj={"site_id": site_id, "dir": norm_dir}, error_message="Site not active")
        return _err("INVALID_TRANSITION", "Only active sites can be linked.")

    if site.get("is_linked") is True and site.get("local_repo_root"):
        _append_event(acct["id"], "failed", site_row=site, request_obj={"site_id": site_id, "dir": norm_dir}, error_message="Site already linked")
        return _err("CONFLICT", "Site is already linked.", local_repo_root=site.get("local_repo_root"))

    # Enforce unique(local_repo_root) when not null
    other = next((s for s in sites if s.get("local_repo_root") and os.path.normpath(str(s.get("local_repo_root"))) == norm_dir and s.get("id") != site_id), None)
    if other:
        _append_event(acct["id"], "failed", site_row=site, request_obj={"site_id": site_id, "dir": norm_dir}, error_message="Directory already linked")
        return _err("CONFLICT", "Directory is already linked to a different site.", linked_site_id=other.get("id"))

    site["local_repo_root"] = norm_dir
    site["is_linked"] = True
    site["updated_at"] = now

    _save("sites.json", sites)

    _append_event(
        acct["id"],
        "completed",
        site_row=site,
        request_obj={"site_id": site_id, "dir": norm_dir},
        response_obj={"site_id": site_id, "local_repo_root": norm_dir, "is_linked": True},
        error_message=None
    )

    return {
        "site": site,
        "link": {"site_id": site_id, "dir": norm_dir},
        "meta": {"account_id": acct["id"], "latency_ms": int((time.time() - t0) * 1000)}
    }

