        try:
            if v.endswith("Z"):
                v = v[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(v)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _find_active_account():
        for a in accounts:
            if a.get("is_active") is True and a.get("status") in ("connected", "error") and isinstance(a.get("access_token_ciphertext"), str) and a.get("access_token_ciphertext"):
                return a
        for a in accounts:
            if a.get("status") in ("connected", "error") and isinstance(a.get("access_token_ciphertext"), str) and a.get("access_token_ciphertext"):
                return a
        return None

    def _rate_limited(account_id):
        one_min_ago = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(seconds=60)
        cnt = 0
        for e in events:
            if e.get("account_id") != account_id:
                continue
            if e.get("status") not in ("running", "queued"):
                continue
            ts = _parse_rfc3339(e.get("created_at"))
            if ts and ts >= one_min_ago:
                cnt += 1
        for d in deploys:
            srow = next((s for s in sites if s.get("id") == d.get("site_id")), None)
            if not srow or srow.get("account_id") != account_id:
                continue
            if d.get("status") in ("queued", "building", "uploading", "restoring"):
                ts = _parse_rfc3339(d.get("created_at"))
                if ts and ts >= one_min_ago:
                    cnt += 1
        if cnt >= 60:
            return True, 60
        return False, None

    def _append_event(account_id, status, site_row=None, request_obj=None, response_obj=None, error_message=None):
        ev = {
            "id": _new_id("nlt_evt"),
            "account_id": account_id,
            "site_id": site_row.get("id") if site_row else None,
            "deploy_id": None,
            "event_type": "open_site_action",
            "status": status,
            "request": request_obj,
            "response": response_obj,
            "http_method": None,
            "http_path": None,
            "http_status_code": None,
            "error_message": error_message,
            "started_at": None,
            "ended_at": now if status in ("completed", "failed", "canceled") else None,
            "created_at": now,
            "updated_at": now,
        }
        events.append(ev)
        _save("observability_events.json", events)

    acct = _find_active_account()
    if not acct:
        return _err("UNAUTHORIZED", "No active Netlify account connection is available for this operation.")

    limited, retry_after = _rate_limited(acct["id"])
    if limited:
        _append_event(acct["id"], "failed", request_obj={"tool": "unlink-site"}, error_message="Rate limit exceeded")
        return _err("RATE_LIMIT", "Rate limit exceeded.", retry_after=retry_after)

    if not isinstance(dir, str) or not dir.strip():
        _append_event(acct["id"], "failed", request_obj={"dir": dir, "site_id": site_id}, error_message="Invalid dir")
        return _err("VALIDATION_ERROR", "dir must be a non-empty string.")
