        _append_event(acct["id"], "failed", request_obj={"dir": norm_dir, "site_id": site_id}, error_message="No link found for dir")
        return _err("NOT_FOUND", "No linked site exists for the given dir.")

    if linked.get("account_id") != acct["id"]:
