    if site_id is not None and linked.get("id") != site_id:
        _append_event(acct["id"], "failed", site_row=linked, request_obj={"dir": norm_dir, "site_id": site_id}, error_message="site_id does not match link")
        return _err("NOT_FOUND", "The given site_id does not match the site linked to this dir.", linked_site_id=linked.get("id"))

    removed_mapping = {"site_id": linked.get("id"), "dir": norm_dir}

    linked["local_repo_root"] = None
    linked["is_linked"] = False
    linked["updated_at"] = now

    _save("sites.json", sites)

    _append_event(
        acct["id"],
        "completed",
        site_row=linked,
        request_obj={"dir": norm_dir, "site_id": site_id},
        response_obj={"unlinked": removed_mapping},
        error_message=None
    )

    return {
        "unlinked": removed_mapping,
        "site": linked,
        "meta": {"account_id": acct["id"], "latency_ms": int((time.time() - t0) * 1000)}
    }

def import_env(site_id, file_path, format=None, scope=None, overwrite=None, dry_run=None, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0414000" if __import__("os").path.isdir("./environment_mix/0414000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validate required
    site_pat = re.compile(r"^nlt_site_[0-9A-HJKMNP-TV-Z]{10,}$")
    if not isinstance(site_id, str) or not site_pat.match(site_id):
        return _err("VALIDATION_ERROR", "site_id is malformed.", field="site_id")
    if not isinstance(file_path, str) or not file_path.strip():
        return _err("VALIDATION_ERROR", "file_path must be a non-empty string.", field="file_path")

    if format is None:
        format = "dotenv"
    if scope is None:
        scope = "all"
    if overwrite is None:
        overwrite = False
    if dry_run is None:
        dry_run = False

    if not isinstance(format, str) or format not in ("dotenv", "json"):
        return _err("VALIDATION_ERROR", "format must be one of: dotenv, json.", field="format")
    if not isinstance(scope, str) or scope not in ("all", "production", "deploy-preview", "branch-deploy"):
        return _err("VALIDATION_ERROR", "scope must be one of: all, production, deploy-preview, branch-deploy.", field="scope")
    if not isinstance(overwrite, bool):
        return _err("VALIDATION_ERROR", "overwrite must be a boolean.", field="overwrite")
    if not isinstance(dry_run, bool):
        return _err("VALIDATION_ERROR", "dry_run must be a boolean.", field="dry_run")

    accounts = _load("netlify_accounts.json")
    sites = _load("sites.json")
    kv = _load("site_kv.json")
    events = _load("observability_events.json")

    # Resolve active/usable account (must satisfy prerequisites)
    def _usable(a):
        return a.get("status") == "connected" and isinstance(a.get("access_token_ciphertext"), str) and len(a.get("access_token_ciphertext")) > 0

    active = next((a for a in accounts if a.get("is_active") is True and _usable(a)), None)
    if active is None:
        active = next((a for a in accounts if _usable(a)), None)
    if active is None:
        return _err("UNAUTHORIZED", "No active account/token is available.")

    # Rate limit (60/min) by queued/running events
    cutoff = (datetime.datetime.utcnow() - datetime.timedelta(seconds=60)).replace(microsecond=0).isoformat() + "Z"
    recent = 0
    for ev in events:
        if ev.get("account_id") != active.get("id"):
            continue
        if ev.get("status") not in ("queued", "running"):
            continue
        created_at = ev.get("created_at")
        if isinstance(created_at, str) and created_at >= cutoff:
            recent += 1
    if recent >= 60:
        ev_id = "nlt_evt_" + uuid.uuid4().hex
        events.append({
            "id": ev_id,
            "account_id": active.get("id"),
            "site_id": site_id,
            "deploy_id": None,
            "event_type": "api_call_audit",
            "status": "failed",
            "request": {"tool": "import-env", "site_id": site_id},
            "response": None,
            "http_method": "POST",
            "http_path": "/api/v1/sites/{site_id}/env/import",
            "http_status_code": 429,
            "error_message": "Rate limit exceeded.",
            "started_at": now,
            "ended_at": now,
            "created_at": now,
            "updated_at": now
        })
        _save("observability_events.json", events)
        return _err("RATE_LIMIT", "Rate limit exceeded.", retry_after_seconds=60)

    site = next((s for s in sites if s.get("id") == site_id and s.get("account_id") == active.get("id")), None)
    if site is None:
        # log
        ev_id = "nlt_evt_" + uuid.uuid4().hex
        events.append({
            "id": ev_id,
            "account_id": active.get("id"),
            "site_id": site_id,
            "deploy_id": None,
            "event_type": "api_call_audit",
            "status": "failed",
            "request": {"tool": "import-env", "site_id": site_id},
            "response": None,
            "http_method": "POST",
            "http_path": "/api/v1/sites/{site_id}/env/import",
            "http_status_code": 404,
            "error_message": "Site not found for active account.",
            "started_at": now,
            "ended_at": now,
            "created_at": now,
            "updated_at": now
        })
        _save("observability_events.json", events)
        return _err("NOT_FOUND", "Local site not found for the active account.", site_id=site_id)

    if site.get("status") != "active":
        ev_id = "nlt_evt_" + uuid.uuid4().hex
        events.append({
            "id": ev_id,
            "account_id": active.get("id"),
            "site_id": site_id,
            "deploy_id": None,
            "event_type": "api_call_audit",
            "status": "failed",
            "request": {"tool": "import-env", "site_id": site_id, "site_status": site.get("status")},
            "response": None,
            "http_method": "POST",
            "http_path": "/api/v1/sites/{site_id}/env/import",
            "http_status_code": 409,
            "error_message": "Site is not active.",
            "started_at": now,
            "ended_at": now,
            "created_at": now,
            "updated_at": now
        })
        _save("observability_events.json", events)
        return _err("CONFLICT", "Operation allowed only for active sites.", site_status=site.get("status"))

    # Read file content
    if not os.path.exists(file_path) or not os.path.isfile(file_path):
        return _err("VALIDATION_ERROR", "file_path does not exist or is not a file.", field="file_path")

    try:
        with open(file_path, "r", encoding="utf-8") as f:
            content = f.read()
    except OSError:
        return _err("VALIDATION_ERROR", "Unable to read file_path.", field="file_path")

    # Parse env vars
    env_key_re = re.compile(r"^[A-Z_][A-Z0-9_]*$")
    parsed = {}

    def _parse_dotenv(txt):
        out = {}
        lines = txt.splitlines()
        for ln in lines:
            s = ln.strip()
            if not s or s.startswith("#"):
                continue
            if s.lower().startswith("export "):
                s = s[7:].lstrip()
            if "=" not in s:
                raise ValueError("Invalid dotenv line (missing '=')")
            k, v = s.split("=", 1)
            k = k.strip()
            v = v.strip()
            if not k:
                raise ValueError("Empty key in dotenv")
            # strip optional quotes
            if (len(v) >= 2) and ((v[0] == v[-1] == '"') or (v[0] == v[-1] == "'")):
                v = v[1:-1]
            out[k] = v
        return out

    try:
        if format == "dotenv":
            parsed = _parse_dotenv(content)
        else:
            obj = json.loads(content)
            if not isinstance(obj, dict):
                return _err("VALIDATION_ERROR", "JSON env file must be an object of key/value pairs.", field="format")
            for k, v in obj.items():
                if not isinstance(k, str):
                    return _err("VALIDATION_ERROR", "JSON env keys must be strings.", field="file_path")
                if v is None:
                    # allow null -> empty string? treat as validation error to be strict
                    return _err("VALIDATION_ERROR", "JSON env values must be strings.", field=k)
                if not isinstance(v, str):
                    return _err("VALIDATION_ERROR", "JSON env values must be strings.", field=k)
                parsed[k] = v
    except json.JSONDecodeError:
        return _err("VALIDATION_ERROR", "File content cannot be parsed as JSON.", field="file_path")
    except ValueError as e:
        return _err("VALIDATION_ERROR", "File content cannot be parsed as dotenv.", detail=str(e))

    # Validate keys/values against constraints (namespace='env')
    planned = []
    for k, v in parsed.items():
        if not isinstance(k, str) or not env_key_re.match(k):
            return _err("VALIDATION_ERROR", "Invalid env var key format.", field="key", key=k)
        if not (1 <= len(k) <= 512):
            return _err("VALIDATION_ERROR", "key length must be between 1 and 512.", field="key", key=k)
        if not isinstance(v, str):
            return _err("VALIDATION_ERROR", "Env var values must be strings.", field="value", key=k)
        if len(v) > 65535:
            return _err("VALIDATION_ERROR", "value_text too long (max 65535).", field="value_text", key=k)
        planned.append((k, v))

    # Determine changes
    created = 0
    updated = 0
    skipped = 0
    changes = []

    def _find_active_env_row(keyname):
        for row in kv:
            if row.get("site_id") == site_id and row.get("namespace") == "env" and row.get("key") == keyname and row.get("status") == "active":
                return row
        return None

    def _next_kv_id():
        return "nlt_kv_" + uuid.uuid4().hex

    for k, v in planned:
        existing = _find_active_env_row(k)
        if existing is None:
            changes.append({"key": k, "action": "create"})
        else:
            # if overwrite false and value differs -> skip; if same -> skip
            if overwrite is False:
                changes.append({"key": k, "action": "skip_exists"})
            else:
                changes.append({"key": k, "action": "update"})

    if dry_run:
        ev_id = "nlt_evt_" + uuid.uuid4().hex
        events.append({
            "id": ev_id,
            "account_id": active.get("id"),
            "site_id": site_id,
            "deploy_id": None,
            "event_type": "api_call_audit",
            "status": "completed",
            "request": {"tool": "import-env", "site_id": site_id, "format": format, "scope": scope, "overwrite": overwrite, "dry_run": True},
            "response": {"planned_changes": changes, "parsed_count": len(planned)},
            "http_method": "POST",
            "http_path": "/api/v1/sites/{site_id}/env/import",
            "http_status_code": 200,
            "error_message": None,
            "started_at": now,
            "ended_at": now,
            "created_at": now,
            "updated_at": now
        })
        _save("observability_events.json", events)
        return {
            "site_id": site_id,
            "scope": scope,
            "dry_run": True,
            "summary": {"created": 0, "updated": 0, "skipped": len(planned), "parsed": len(planned)},
            "planned_changes": changes,
            "meta": {"latency_ms": int((time.time() - t0) * 1000)}
        }

    # Apply changes (upsert)
    for k, v in planned:
        existing = _find_active_env_row(k)
        if existing is None:
            kv.append({
                "id": _next_kv_id(),
                "site_id": site_id,
                "namespace": "env",
                "key": k,
                "value_text": v,
                "value_bytes": None,
                "content_type": None,
                "is_secret": False,
                "etag": None,
                "status": "active",
                "deleted_at": None,
                "created_at": now,
                "updated_at": now
            })
            created += 1
        else:
            if overwrite is False:
                skipped += 1
            else:
                existing["value_text"] = v
                existing["value_bytes"] = None
                existing["updated_at"] = now
                existing["deleted_at"] = None
                existing["status"] = "active"
                updated += 1

    # Persist KV updates
    _save("site_kv.json", kv)

    # Log event
    ev_id = "nlt_evt_" + uuid.uuid4().hex
    events.append({
        "id": ev_id,
        "account_id": active.get("id"),
        "site_id": site_id,
        "deploy_id": None,
        "event_type": "api_call_audit",
        "status": "completed",
        "request": {"tool": "import-env", "site_id": site_id, "format": format, "scope": scope, "overwrite": overwrite, "dry_run": False, "keys_count": len(planned)},
        "response": {"created": created, "updated": updated, "skipped": skipped},
        "http_method": "POST",
        "http_path": "/api/v1/sites/{site_id}/env/import",
        "http_status_code": 200,
        "error_message": None,
        "started_at": now,
        "ended_at": now,
        "created_at": now,
        "updated_at": now
    })
    _save("observability_events.json", events)

    return {
        "site_id": site_id,
        "scope": scope,
        "dry_run": False,
        "summary": {"created": created, "updated": updated, "skipped": skipped, "parsed": len(planned)},
        "meta": {"latency_ms": int((time.time() - t0) * 1000)}
    }

def unset_env_var(site_id, key, scope=None, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0414000" if __import__("os").path.isdir("./environment_mix/0414000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
           	    return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat().replace("+00:00", "Z")

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        time_chars = []
        v = ms
        for _ in range(10):
            time_chars.append(alphabet[v % 32])
            v //= 32
        time_part = "".join(reversed(time_chars))
        rand = hashlib.sha256(f"{time.time_ns()}:{os.getpid()}:{os.urandom(8)}".encode("utf-8")).digest()
        rand_part = "".join(alphabet[b % 32] for b in rand[:16])
        return f"{prefix}{time_part}{rand_part}"

    def _record_event(account_id, status, request_obj, response_obj=None, error_message=None):
        events = _load("observability_events.json")
        ev_id = _new_id("nlt_evt_")
        ended = datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        ev = {
            "id": ev_id,
            "account_id": account_id,
            "site_id": site_id,
            "deploy_id": None,
            "event_type": "api_call_audit",
            "status": status,
            "request": request_obj,
            "response": response_obj,
            "http_method": "DELETE",
            "http_path": "/env",
            "http_status_code": 200 if status == "completed" else 400,
            "error_message": error_message,
            "started_at": now_iso,
            "ended_at": ended,
            "created_at": now_iso,
            "updated_at": ended,
        }
        # ensure serializable
        try:
            json.dumps(ev["request"])
            if ev["response"] is not None:
                json.dumps(ev["response"])
        except Exception:
            ev["request"] = {"note": "request/response not serializable; redacted"}
            ev["response"] = None
        events.append(ev)
        _save("observability_events.json", events)
        return ev_id

    def _active_account_and_rate_limit():
        accounts = _load("netlify_accounts.json")
        active = [a for a in accounts if isinstance(a, dict) and a.get("is_active") is True]
        candidates = []
        for a in active:
            if a.get("status") in ("connected", "error") and isinstance(a.get("access_token_ciphertext"), str) and a.get("access_token_ciphertext"):
                candidates.append(a)
        if not candidates:
            for a in accounts:
                if a.get("status") in ("connected", "error") and isinstance(a.get("access_token_ciphertext"), str) and a.get("access_token_ciphertext"):
                    candidates.append(a)
                    break
        if not candidates:
            return None, _err("UNAUTHORIZED", "No active, usable Netlify account connection found.")
        acct = candidates[0]

        # Rate limit: 60/min for queued/running
        events = _load("observability_events.json")
        cutoff = now - datetime.timedelta(seconds=60)

        def _parse(s):
            if not s or not isinstance(s, str):
                return None
            try:
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except Exception:
                return None

        cnt = 0
        for e in events:
            if not isinstance(e, dict):
                continue
            if e.get("account_id") != acct.get("id"):
                continue
            if e.get("status") not in ("running", "queued"):
                continue
            ts = _parse(e.get("created_at")) or _parse(e.get("started_at"))
            if ts and ts >= cutoff:
                cnt += 1

        if cnt >= 60:
            return acct, _err("RATE_LIMIT", "Rate limit exceeded: at most 60 executions per minute.", retry_after=60)

        return acct, None

    # Validate
    if not isinstance(site_id, str) or not re.match(r"^nlt_site_[0-9A-HJKMNP-TV-Z]{10,}$", site_id):
        acct, _ = _active_account_and_rate_limit()
        if acct:
            _record_event(acct["id"], "failed", {"tool": "unset-env-var", "site_id": site_id, "key": key, "scope": scope}, error_message="Invalid site_id")
        return _err("VALIDATION_ERROR", "site_id is invalid.")
    if not isinstance(key, str) or not key:
        acct, _ = _active_account_and_rate_limit()
        if acct:
            _record_event(acct["id"], "failed", {"tool": "unset-env-var", "site_id": site_id, "key": key, "scope": scope}, error_message="Invalid key")
        return _err("VALIDATION_ERROR", "key must be a non-empty string.")
    if not re.match(r"^[A-Z_][A-Z0-9_]*$", key):
        acct, _ = _active_account_and_rate_limit()
        if acct:
            _record_event(acct["id"], "failed", {"tool": "unset-env-var", "site_id": site_id, "key": key, "scope": scope}, error_message="Key pattern invalid")
        return _err("VALIDATION_ERROR", "key is invalid for env vars (must match ^[A-Z_][A-Z0-9_]*$).")
    if scope is not None:
        if not isinstance(scope, str) or scope not in ("all", "production", "deploy-preview", "branch-deploy"):
            acct, _ = _active_account_and_rate_limit()
            if acct:
                _record_event(acct["id"], "failed", {"tool": "unset-env-var", "site_id": site_id, "key": key, "scope": scope}, error_message="Invalid scope")
            return _err("VALIDATION_ERROR", "scope is invalid.")
    # Server-side mapping to namespace only; scope stored in key suffix convention.
    # We'll treat scopes by encoding as: key or key@scope (except 'all' matches any)
    acct, rl_err = _active_account_and_rate_limit()
    if rl_err:
        _record_event(acct["id"], "failed", {"tool": "unset-env-var", "site_id": site_id, "key": key, "scope": scope}, error_message=rl_err["error"]["message"])
        return rl_err
    if not acct:
        return _err("UNAUTHORIZED", "No active Netlify account connection found.")

    sites = _load("sites.json")
    site = None
    for s in sites:
        if isinstance(s, dict) and s.get("id") == site_id:
            site = s
            break
    if not site:
        _record_event(acct["id"], "failed", {"tool": "unset-env-var", "site_id": site_id, "key": key, "scope": scope}, error_message="Site not found")
        return _err("NOT_FOUND", "Site not found.")
    if site.get("account_id") != acct.get("id"):
        _record_event(acct["id"], "failed", {"tool": "unset-env-var", "site_id": site_id, "key": key, "scope": scope}, error_message="Site not owned by active account")
        return _err("UNAUTHORIZED", "Site is not accessible under the active account.")
    if site.get("status") != "active":
        _record_event(acct["id"], "failed", {"tool": "unset-env-var", "site_id": site_id, "key": key, "scope": scope}, error_message="Site not active")
        return _err("NOT_FOUND", "Site is not active.")
    if site.get("is_linked") is not True:
        _record_event(acct["id"], "failed", {"tool": "unset-env-var", "site_id": site_id, "key": key, "scope": scope}, error_message="Site not linked")
        return _err("NOT_FOUND", "Site is not linked.")

    # Deletion rule: KV writes rejected when site is deleted; site is active already.
    kv = _load("site_kv.json")

    # Determine matching rows by scope encoding
    def _scope_key(k, sc):
        return f"{k}@{sc}" if sc and sc != "all" else k

    targets = []
    if scope is None or scope == "all":
        # match any active env var rows with key=key or key@<scope>
        for row in kv:
            if not isinstance(row, dict):
                continue
            if row.get("site_id") != site_id or row.get("namespace") != "env":
                continue
            if row.get("status") != "active":
                continue
            rk = row.get("key")
            if rk == key or (isinstance(rk, str) and rk.startswith(key + "@")):
                targets.append(row)
    else:
        k2 = _scope_key(key, scope)
        for row in kv:
            if not isinstance(row, dict):
                continue
            if row.get("site_id") != site_id or row.get("namespace") != "env":
                continue
            if row.get("status") != "active":
                continue
            if row.get("key") == k2:
                targets.append(row)

    if not targets:
        _record_event(acct["id"], "failed", {"tool": "unset-env-var", "site_id": site_id, "key": key, "scope": scope}, error_message="Env var not found")
        return _err("NOT_FOUND", "Environment variable not found in the requested scope.")

    # Transition active -> deleted
    updated = 0
    for row in kv:
        if row in targets:
            # lifecycle transitions: active -> deleted only
            if row.get("status") != "active":
                continue
            row["status"] = "deleted"
            row["deleted_at"] = now_iso
            row["updated_at"] = now_iso
            updated += 1

    if updated == 0:
        _record_event(acct["id"], "failed", {"tool": "unset-env-var", "site_id": site_id, "key": key, "scope": scope}, error_message="No rows updated")
        return _err("NOT_FOUND", "Environment variable not found or already deleted.")

    _save("site_kv.json", kv)

    latency_ms = int((time.time() - t0) * 1000)
    _record_event(
        acct["id"],
        "completed",
        {"tool": "unset-env-var", "site_id": site_id, "key": key, "scope": scope, "latency_ms": latency_ms},
        response_obj={"deleted": updated},
    )

    # Return updated variable state/confirmation; do not reveal values
    deleted_keys = [t.get("key") for t in targets if isinstance(t, dict)]
    return {
        "site_id": site_id,
        "namespace": "env",
        "key": key,
        "scope": scope or "all",
        "deleted": True,
        "deleted_count": updated,
        "deleted_keys": deleted_keys,
        "deleted_at": now_iso,
    }

def clone_env_vars(from_site_id, to_site_id, scope=None, overwrite=None, include_secrets=None, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0414000" if __import__("os").path.isdir("./environment_mix/0414000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_rfc3339(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                return None
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(time.time() * 1000)
        out = []
        for _ in range(10):
            out.append(alphabet[ts % 32])
            ts //= 32
        seed = (str(time.time()) + ":" + str(os.getpid())).encode("utf-8")
        h = hashlib.sha256(seed).digest()
        for i in range(16):
            out.append(alphabet[h[i] % 32])
        return prefix + "".join(reversed(out[:10])) + "".join(out[10:])

    def _sanitize(obj):
        if obj is None:
            return None
        if isinstance(obj, (str, int, float, bool)):
            return obj
        if isinstance(obj, list):
            return [_sanitize(x) for x in obj[:2000]]
        if isinstance(obj, dict):
            redacted_keys = {"access_token", "access_token_ciphertext", "token", "authorization", "auth", "password", "secret"}
            out = {}
            for k, v in obj.items():
                if isinstance(k, str) and k.lower() in redacted_keys:
                    out[k] = "[REDACTED]"
                else:
                    out[k] = _sanitize(v)
            return out
        return str(obj)

    def _record_event(account_id, status, request_obj=None, response_obj=None, error_message=None, site_id_val=None):
        events = _load("observability_events.json")
        ts = _now_iso()
        ev = {
            "id": _gen_id("nlt_evt_"),
            "account_id": account_id,
            "site_id": site_id_val,
            "deploy_id": None,
            "event_type": "api_call_audit",
            "status": status,
            "request": request_obj,
            "response": response_obj,
            "http_method": "POST",
            "http_path": "/internal/clone-env-vars",
            "http_status_code": 200 if status == "completed" else 400,
            "error_message": error_message,
            "started_at": None,
            "ended_at": _now_iso() if status in ("completed", "failed", "canceled") else None,
            "created_at": ts,
            "updated_at": ts,
        }
        events.append(ev)
        _save("observability_events.json", events)
        return ev

    # Validate inputs
    if not isinstance(from_site_id, str) or not re.match(r"^nlt_site_[0-9A-HJKMNP-TV-Z]{10,}$", from_site_id):
        return _err("VALIDATION_ERROR", "from_site_id is invalid.", field="from_site_id")
    if not isinstance(to_site_id, str) or not re.match(r"^nlt_site_[0-9A-HJKMNP-TV-Z]{10,}$", to_site_id):
        return _err("VALIDATION_ERROR", "to_site_id is invalid.", field="to_site_id")
    if scope is None:
        scope = "all"
    if not isinstance(scope, str) or scope not in ("all", "production", "deploy-preview", "branch-deploy"):
        return _err("VALIDATION_ERROR", "scope is invalid.", field="scope")
    if overwrite is None:
        overwrite = False
    if include_secrets is None:
        include_secrets = False
    if not isinstance(overwrite, bool):
        return _err("VALIDATION_ERROR", "overwrite must be boolean.", field="overwrite")
    if not isinstance(include_secrets, bool):
        return _err("VALIDATION_ERROR", "include_secrets must be boolean.", field="include_secrets")

    t0 = time.time()

    # Resolve active account
    accounts = _load("netlify_accounts.json")
    active_accounts = [a for a in accounts if a.get("is_active") is True and a.get("status") in ("connected", "error") and isinstance(a.get("access_token_ciphertext"), str) and a.get("access_token_ciphertext")]
    if not active_accounts:
        return _err("UNAUTHORIZED", "No active Netlify account connection is available.")
    account = active_accounts[0]
    account_id = account.get("id")

    # Rate limiting: per account max 60 queued/running per minute
    events = _load("observability_events.json")
    now = datetime.datetime.now(datetime.timezone.utc)
    window_start = now - datetime.timedelta(minutes=1)
    active_count = 0
    for e in events:
        if e.get("account_id") != account_id:
            continue
        if e.get("status") not in ("running", "queued"):
            continue
        ca = e.get("created_at")
        if isinstance(ca, str):
            dt = _parse_rfc3339(ca) or _parse_rfc3339(ca.replace(" ", "T"))
            if dt and dt >= window_start:
                active_count += 1
    if active_count >= 60:
        _record_event(
            account_id=account_id,
            status="failed",
            request_obj=_sanitize({"tool": "clone-env-vars", "from_site_id": from_site_id, "to_site_id": to_site_id, "scope": scope, "overwrite": overwrite, "include_secrets": include_secrets}),
            response_obj=_sanitize({"error": "RATE_LIMIT"}),
            error_message="Rate limit exceeded.",
            site_id_val=to_site_id,
        )
        return _err("RATE_LIMIT", "Too many requests. Please retry later.", retry_after_seconds=60)

    sites = _load("sites.json")
    from_site = next((s for s in sites if s.get("id") == from_site_id), None)
    to_site = next((s for s in sites if s.get("id") == to_site_id), None)

    # NOT_FOUND when either local site does not exist, is not linked, or doesn't belong to active account, or not active
    def _site_ok(s):
        return (
            s
            and s.get("account_id") == account_id
            and s.get("status") == "active"
            and s.get("is_linked") is True
            and bool(s.get("local_repo_root"))
        )

    if not _site_ok(from_site):
        _record_event(
            account_id=account_id,
            status="failed",
            request_obj=_sanitize({"tool": "clone-env-vars", "from_site_id": from_site_id, "to_site_id": to_site_id, "scope": scope, "overwrite": overwrite, "include_secrets": include_secrets}),
            response_obj=_sanitize({"error": "NOT_FOUND", "which": "from_site"}),
            error_message="Source site not found/linked/active for active account.",
            site_id_val=from_site_id,
        )
        return _err("NOT_FOUND", "Source site not found, not linked, not active, or not accessible.", resource="site", id=from_site_id)

    if not _site_ok(to_site):
        _record_event(
            account_id=account_id,
            status="failed",
            request_obj=_sanitize({"tool": "clone-env-vars", "from_site_id": from_site_id, "to_site_id": to_site_id, "scope": scope, "overwrite": overwrite, "include_secrets": include_secrets}),
            response_obj=_sanitize({"error": "NOT_FOUND", "which": "to_site"}),
            error_message="Destination site not found/linked/active for active account.",
            site_id_val=to_site_id,
        )
        return _err("NOT_FOUND", "Destination site not found, not linked, not active, or not accessible.", resource="site", id=to_site_id)

    # KV rules: once site deleted, no KV writes. already ensured active. proceed.
    kv = _load("site_kv.json")

    # Scope mapping: store as metadata tag inside value? Not present in schema.
    # Implementation choice: encode scope into key prefix "NETLIFY_SCOPE:<scope>:<KEY>"
    # But schema says key should match env var regex; so we cannot change key.
    # Therefore, scope is treated as a filter on metadata in value (best-effort). If not present, scope=all includes all.
    # We will look for metadata in "etag" field like "scope=<scope>" when present; otherwise consider "production" default.
    def _kv_scope(row):
        et = row.get("etag")
        if isinstance(et, str) and et.startswith("scope="):
            return et.split("=", 1)[1]
        return "production"

    from_vars = [r for r in kv if r.get("site_id") == from_site_id and r.get("namespace") == "env" and r.get("status") == "active"]
    if scope != "all":
        from_vars = [r for r in from_vars if _kv_scope(r) == scope]

    # Apply include_secrets filter
    if not include_secrets:
        from_vars = [r for r in from_vars if r.get("is_secret") is not True]

    # Index destination active env vars by key
    dest_active = {r.get("key"): r for r in kv if r.get("site_id") == to_site_id and r.get("namespace") == "env" and r.get("status") == "active" and isinstance(r.get("key"), str)}

    ts = _now_iso()
    summary = {"created": 0, "updated": 0, "skipped": 0}
    per_key = {}

    # Helper validations for env constraints
    env_key_re = re.compile(r"^[A-Z_][A-Z0-9_]*$")

    mutated = False

    for src in from_vars:
        key = src.get("key")
        if not isinstance(key, str) or not (1 <= len(key) <= 512) or not env_key_re.match(key):
            # Shouldn't happen if store is consistent, skip safely
            continue

        # Env implies value_bytes is null and exactly one set
        val_text = src.get("value_text")
        val_bytes = src.get("value_bytes")
        if val_bytes is not None:
            continue
        if (val_text is None) or (not isinstance(val_text, str)):
            continue
        if len(val_text) > 65535:
            continue

        is_secret = True if src.get("is_secret") is True else False

        existing = dest_active.get(key)
        if existing:
            if not overwrite:
                summary["skipped"] += 1
                per_key[key] = {"action": "skipped", "reason": "exists", "is_secret": is_secret}
                continue
            # Update existing
            existing["value_text"] = val_text
            existing["value_bytes"] = None
            existing["is_secret"] = is_secret
            # Keep scope tagging (etag) aligned to source
            existing["etag"] = src.get("etag")
            existing["updated_at"] = ts
            mutated = True
            summary["updated"] += 1
            per_key[key] = {"action": "updated", "is_secret": is_secret}
        else:
            # If there is a deleted row for same key, reactivate it instead of creating new
            deleted_row = next((r for r in kv if r.get("site_id") == to_site_id and r.get("namespace") == "env" and r.get("key") == key and r.get("status") == "deleted"), None)
            if deleted_row:
                deleted_row["status"] = "active"
                deleted_row["deleted_at"] = None
                deleted_row["value_text"] = val_text
                deleted_row["value_bytes"] = None
                deleted_row["is_secret"] = is_secret
                deleted_row["etag"] = src.get("etag")
                deleted_row["updated_at"] = ts
                mutated = True
                summary["updated"] += 1
                per_key[key] = {"action": "updated", "is_secret": is_secret, "reason": "reactivated"}
            else:
                new_row = {
                    "id": _gen_id("nlt_kv_"),
                    "site_id": to_site_id,
                    "namespace": "env",
                    "key": key,
                    "value_text": val_text,
                    "value_bytes": None,
                    "content_type": None,
                    "is_secret": is_secret,
                    "etag": src.get("etag"),
                    "status": "active",
                    "deleted_at": None,
                    "created_at": ts,
                    "updated_at": ts,
                }
                kv.append(new_row)
                mutated = True
                summary["created"] += 1
                per_key[key] = {"action": "created", "is_secret": is_secret}

    if mutated:
        _save("site_kv.json", kv)

    latency_ms = int((time.time() - t0) * 1000)

    _record_event(
        account_id=account_id,
        status="completed",
        request_obj=_sanitize({"tool": "clone-env-vars", "from_site_id": from_site_id, "to_site_id": to_site_id, "scope": scope, "overwrite": overwrite, "include_secrets": include_secrets}),
        response_obj=_sanitize({"summary": summary, "keys": list(per_key.keys())[:2000]}),
        error_message=None,
        site_id_val=to_site_id,
    )

    return {
        "from_site_id": from_site_id,
        "to_site_id": to_site_id,
        "scope": scope,
        "overwrite": overwrite,
        "include_secrets": include_secrets,
        "summary": summary,
        "results": per_key,
        "meta": {
            "account_id": account_id,
            "latency_ms": latency_ms,
        },
    }

def list_deploys(site_id=None, netlify_site_id=None, limit=None, cursor=None, sort=None, status=None, branch=None, is_production=None, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0414000" if __import__("os").path.isdir("./environment_mix/0414000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat()

    accounts = _load("netlify_accounts.json")
    sites = _load("sites.json")
    deploys = _load("deploys.json")
    events = _load("observability_events.json")

    def _new_id(prefix):
        seed = f"{prefix}:{now_iso}:{len(events)+1}:{os.getpid()}".encode("utf-8")
        h = hashlib.sha256(seed).hexdigest().upper()
        return f"{prefix}_{h[:12]}"

    def _dt(v):
        if v is None:
            return None
        if not isinstance(v, str):
            return None
        try:
            return datetime.datetime.fromisoformat(v.replace("Z", "+00:00"))
        except Exception:
            return None

    def _rate_limited(account_id):
        window_start = now - datetime.timedelta(seconds=60)
        cnt = 0
        for e in events:
            if e.get("account_id") != account_id:
                continue
            if e.get("status") not in ("queued", "running"):
                continue
            ts = _dt(e.get("created_at"))
            if ts and ts >= window_start:
                cnt += 1
        # "across observability_events and deploy creation": deploy creation is also logged into events by other tools;
        # here we enforce from events as the shared counter.
        if cnt >= 60:
            oldest = None
            for e in events:
                if e.get("account_id") != account_id:
                    continue
                if e.get("status") not in ("queued", "running"):
                    continue
                ts = _dt(e.get("created_at"))
                if ts and ts >= window_start:
                    if oldest is None or ts < oldest:
                        oldest = ts
            retry_after = 1
            if oldest is not None:
                retry_after = max(1, int(60 - (now - oldest).total_seconds()))
            return retry_after
        return None

    def _log_event(account_id, site_id_for_event, status_value, request_obj, response_obj=None, error_message=None):
        ev = {
            "id": _new_id("nlt_evt"),
            "account_id": account_id,
            "site_id": site_id_for_event,
            "deploy_id": None,
            "event_type": "api_call_audit",  # closest available for tool calls; record tool-like call here
            "status": status_value,
            "request": request_obj,
            "response": response_obj,
            "http_method": None,
            "http_path": None,
            "http_status_code": None,
            "error_message": error_message,
            "started_at": None,
            "ended_at": now_iso if status_value in ("completed", "failed", "canceled") else None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        events.append(ev)
        _save("observability_events.json", events)
        return ev

    # Resolve active account (ambient auth)
    active_accounts = [a for a in accounts if a.get("is_active") is True and a.get("status") in ("connected", "error") and isinstance(a.get("access_token_ciphertext"), str) and a.get("access_token_ciphertext")]
    if not active_accounts:
        # log best-effort without account_id? Schema requires account_id, so cannot log.
        return _err("UNAUTHORIZED", "No active Netlify account connection available.")
    account = active_accounts[0]
    account_id = account.get("id")

    retry_after = _rate_limited(account_id)
    if retry_after is not None:
        _log_event(account_id, None, "failed", {"tool": "list-deploys", "params": {"site_id": site_id, "netlify_site_id": netlify_site_id, "limit": limit, "cursor": cursor, "sort": sort, "status": status, "branch": branch, "is_production": is_production}}, error_message="Rate limit exceeded")
        return _err("RATE_LIMIT", "Rate limit exceeded. Try again later.", retry_after=retry_after)

    # Validate inputs
    if site_id is None and netlify_site_id is None:
        _log_event(account_id, None, "failed", {"tool": "list-deploys", "params": {"site_id": site_id, "netlify_site_id": netlify_site_id, "limit": limit, "cursor": cursor, "sort": sort, "status": status, "branch": branch, "is_production": is_production}}, error_message="Missing site identifier")
        return _err("VALIDATION_ERROR", "Either site_id or netlify_site_id must be provided.")
    if site_id is not None:
        if not isinstance(site_id, str) or not re.match(r"^nlt_site_[0-9A-Z]{4,}$", site_id):
            _log_event(account_id, None, "failed", {"tool": "list-deploys", "params": {"site_id": site_id}}, error_message="Malformed site_id")
            return _err("VALIDATION_ERROR", "site_id is malformed.")
    if netlify_site_id is not None:
        if not isinstance(netlify_site_id, str) or not netlify_site_id.strip():
            _log_event(account_id, None, "failed", {"tool": "list-deploys", "params": {"netlify_site_id": netlify_site_id}}, error_message="Malformed netlify_site_id")
            return _err("VALIDATION_ERROR", "netlify_site_id is malformed.")
    if limit is None:
        limit = 20
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _log_event(account_id, None, "failed", {"tool": "list-deploys", "params": {"limit": limit}}, error_message="Invalid limit")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100.")
    if cursor is not None and (not isinstance(cursor, str) or not cursor):
        _log_event(account_id, None, "failed", {"tool": "list-deploys", "params": {"cursor": cursor}}, error_message="Invalid cursor")
        return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided.")
    allowed_sort = {"created_at_desc", "created_at_asc", "started_at_desc", "started_at_asc", "finished_at_desc", "finished_at_asc"}
    if sort is None:
        sort = "created_at_desc"
    if not isinstance(sort, str) or sort not in allowed_sort:
        _log_event(account_id, None, "failed", {"tool": "list-deploys", "params": {"sort": sort}}, error_message="Invalid sort")
        return _err("VALIDATION_ERROR", "sort is invalid.")
    allowed_status = {"queued", "building", "uploading", "ready", "failed", "canceled", "restoring"}
    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        _log_event(account_id, None, "failed", {"tool": "list-deploys", "params": {"status": status}}, error_message="Invalid status")
        return _err("VALIDATION_ERROR", "status is invalid.")
    if branch is not None and not isinstance(branch, str):
        _log_event(account_id, None, "failed", {"tool": "list-deploys", "params": {"branch": branch}}, error_message="Invalid branch")
        return _err("VALIDATION_ERROR", "branch must be a string when provided.")
    if is_production is not None and not isinstance(is_production, bool):
        _log_event(account_id, None, "failed", {"tool": "list-deploys", "params": {"is_production": is_production}}, error_message="Invalid is_production")
        return _err("VALIDATION_ERROR", "is_production must be a boolean when provided.")

    # Resolve site under active account
    site_row = None
    if site_id is not None:
        for s in sites:
            if s.get("id") == site_id and s.get("account_id") == account_id:
                site_row = s
                break
        if site_row is None:
            # reads that match nothing return empty set; but resolving a site identifier to list deploys should be empty page rather than NOT_FOUND
            # However request said: list deploys for a site identified... It doesn't say NOT_FOUND. We'll return empty list with metadata.
            site_row = None
    else:
        for s in sites:
            if s.get("netlify_site_id") == netlify_site_id and s.get("account_id") == account_id:
                site_row = s
                break

    site_id_resolved = site_row.get("id") if site_row else None

    # Filter deploys by resolved site if present; if not resolved, empty
    filtered = []
    if site_row:
        for d in deploys:
            if d.get("site_id") != site_row.get("id"):
                continue
            if status is not None and d.get("status") != status:
                continue
            if branch is not None and d.get("branch") != branch:
                continue
            if is_production is not None and d.get("is_production") is not is_production:
                continue
            filtered.append(d)

    # Sorting
    def _sort_key(d):
        if sort.startswith("created_at"):
            v = _dt(d.get("created_at"))
        elif sort.startswith("started_at"):
            v = _dt(d.get("started_at"))
        else:
            v = _dt(d.get("finished_at"))
        # None sorts last for desc, first for asc; implement by tuple
        return v

    reverse = sort.endswith("_desc")
    # stable sort with None handling
    if reverse:
        filtered.sort(key=lambda d: (_sort_key(d) is None, _sort_key(d)), reverse=True)
    else:
        filtered.sort(key=lambda d: (_sort_key(d) is None, _sort_key(d)))

    total = len(filtered)

    # Cursor pagination: cursor is an integer offset encoded as "offset:<n>"
    offset = 0
    if cursor is not None:
        if not cursor.startswith("offset:"):
            _log_event(account_id, site_id_resolved, "failed", {"tool": "list-deploys", "params": {"cursor": cursor}}, error_message="Invalid cursor format")
            return _err("VALIDATION_ERROR", "cursor is invalid.")
        try:
            offset = int(cursor.split(":", 1)[1])
        except Exception:
            _log_event(account_id, site_id_resolved, "failed", {"tool": "list-deploys", "params": {"cursor": cursor}}, error_message="Invalid cursor value")
            return _err("VALIDATION_ERROR", "cursor is invalid.")
        if offset < 0 or offset > total:
            _log_event(account_id, site_id_resolved, "failed", {"tool": "list-deploys", "params": {"cursor": cursor}}, error_message="Cursor out of range")
            return _err("VALIDATION_ERROR", "cursor is out of range.")

    page = filtered[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = f"offset:{next_offset}" if has_more else None

    latency_ms = int((time.time() - t0) * 1000)
    resp = {
        "deploys": page,
        "site": site_row,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "sort": sort,
            "latency_ms": latency_ms,
        }
    }
    _log_event(account_id, site_id_resolved, "completed", {"tool": "list-deploys", "params": {"site_id": site_id, "netlify_site_id": netlify_site_id, "limit": limit, "cursor": cursor, "sort": sort, "status": status, "branch": branch, "is_production": is_production}}, response_obj={"count": len(page), "total": total, "has_more": has_more})
    return resp

