    active_accounts = [a for a in accounts if a.get("is_active") is True and a.get("status") in ("connected", "error") and isinstance(a.get("access_token_ciphertext"), str) and a.get("access_token_ciphertext")]
    if not active_accounts:
        return _err("UNAUTHORIZED", "No active Netlify account connection available.")
    account = active_accounts[0]
    account_id = account.get("id")

    retry_after = _rate_limited(account_id)
    if retry_after is not None:
        _log_event(account_id, None, None, "failed", {"tool": "cancel-deploy", "params": {"deploy_id": deploy_id, "netlify_deploy_id": netlify_deploy_id}}, error_message="Rate limit exceeded")
        return _err("RATE_LIMIT", "Rate limit exceeded. Try again later.", retry_after=retry_after)

    if deploy_id is None and netlify_deploy_id is None:
        _log_event(account_id, None, None, "failed", {"tool": "cancel-deploy", "params": {"deploy_id": deploy_id, "netlify_deploy_id": netlify_deploy_id}}, error_message="Missing deploy identifier")
        return _err("VALIDATION_ERROR", "Either deploy_id or netlify_deploy_id must be provided.")
    if deploy_id is not None:
        if not isinstance(deploy_id, str) or not re.match(r"^nlt_dpl_[0-9A-Z]{4,}$", deploy_id):
            _log_event(account_id, None, None, "failed", {"tool": "cancel-deploy", "params": {"deploy_id": deploy_id}}, error_message="Malformed deploy_id")
            return _err("VALIDATION_ERROR", "deploy_id is malformed.")
    if netlify_deploy_id is not None:
        if not isinstance(netlify_deploy_id, str) or not netlify_deploy_id.strip():
            _log_event(account_id, None, None, "failed", {"tool": "cancel-deploy", "params": {"netlify_deploy_id": netlify_deploy_id}}, error_message="Malformed netlify_deploy_id")
            return _err("VALIDATION_ERROR", "netlify_deploy_id is malformed.")

    deploy_row = None
    idx = None
    if deploy_id is not None:
        for i, d in enumerate(deploys):
            if d.get("id") == deploy_id:
                deploy_row = d
                idx = i
                break
    else:
        for i, d in enumerate(deploys):
            if d.get("netlify_deploy_id") == netlify_deploy_id:
                deploy_row = d
                idx = i
                break

    if not deploy_row:
        _log_event(account_id, None, None, "failed", {"tool": "cancel-deploy", "params": {"deploy_id": deploy_id, "netlify_deploy_id": netlify_deploy_id}}, error_message="Deploy not found")
        return _err("NOT_FOUND", "Deploy not found.")

    site_row = None
    for s in sites:
        if s.get("id") == deploy_row.get("site_id"):
            site_row = s
            break

    if not site_row or site_row.get("account_id") != account_id:
        _log_event(account_id, site_row.get("id") if site_row else None, deploy_row.get("id"), "failed", {"tool": "cancel-deploy", "params": {"deploy_id": deploy_id, "netlify_deploy_id": netlify_deploy_id}}, error_message="Unauthorized for deploy")
        return _err("UNAUTHORIZED", "You do not have access to this deploy under the active account.")

    current_status = deploy_row.get("status")
    if current_status not in ("queued", "building", "uploading"):
        _log_event(account_id, site_row.get("id"), deploy_row.get("id"), "failed", {"tool": "cancel-deploy", "params": {"deploy_id": deploy_id, "netlify_deploy_id": netlify_deploy_id}}, error_message="Invalid transition to canceled")
        return _err("INVALID_TRANSITION", "Deploy can only be canceled when status is queued, building, or uploading.", from_status=current_status, to_status="canceled")

    if "canceled" not in transitions.get(current_status, []):
        _log_event(account_id, site_row.get("id"), deploy_row.get("id"), "failed", {"tool": "cancel-deploy", "params": {"deploy_id": deploy_id, "netlify_deploy_id": netlify_deploy_id}}, error_message="Transition not allowed by lifecycle")
        return _err("INVALID_TRANSITION", "Cancel transition is not allowed.", from_status=current_status, to_status="canceled")

    # Apply mutation
    deploy_row = dict(deploy_row)
    deploy_row["status"] = "canceled"
    deploy_row["finished_at"] = deploy_row.get("finished_at") or now_iso
    if deploy_row.get("started_at") and deploy_row.get("finished_at"):
        st = _dt(deploy_row.get("started_at"))
        ft = _dt(deploy_row.get("finished_at"))
        if st and ft and ft >= st:
            deploy_row["duration_seconds"] = int((ft - st).total_seconds())
        elif deploy_row.get("duration_seconds") is None:
            deploy_row["duration_seconds"] = 0
    deploy_row["error_message"] = deploy_row.get("error_message") or "Canceled by user"
    deploy_row["updated_at"] = now_iso

    deploys[idx] = deploy_row
    _save("deploys.json", deploys)

    latency_ms = int((time.time() - t0) * 1000)
    resp = {"deploy": deploy_row, "site": site_row, "meta": {"latency_ms": latency_ms}}
    _log_event(account_id, site_row.get("id"), deploy_row.get("id"), "completed", {"tool": "cancel-deploy", "params": {"deploy_id": deploy_id, "netlify_deploy_id": netlify_deploy_id}}, response_obj={"deploy_id": deploy_row.get("id"), "status": deploy_row.get("status")})
    return resp

def restore_deploy(deploy_id=None, netlify_deploy_id=None, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0414000" if __import__("os").path.isdir("./environment_mix/0414000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat()

    accounts = _load("netlify_accounts.json")
    sites = _load("sites.json")
    deploys = _load("deploys.json")
    events = _load("observability_events.json")

    transitions = {
        "queued": ["building", "canceled", "failed"],
        "building": ["uploading", "failed", "canceled"],
        "uploading": ["ready", "failed", "canceled"],
        "ready": ["restoring"],
        "failed": ["restoring"],
        "canceled": ["restoring"],
        "restoring": ["ready", "failed"],
    }

    def _new_id(prefix):
        seed = f"{prefix}:{now_iso}:{len(events)+1}:{os.getpid()}".encode("utf-8")
        h = hashlib.sha256(seed).hexdigest().upper()
        return f"{prefix}_{h[:12]}"

    def _dt(v):
        if v is None:
            return None
        if not isinstance(v, str):
            return None
        try:
            return datetime.datetime.fromisoformat(v.replace("Z", "+00:00"))
        except Exception:
            return None

    def _rate_limited(account_id):
        window_start = now - datetime.timedelta(seconds=60)
        cnt = 0
        for e in events:
            if e.get("account_id") != account_id:
                continue
            if e.get("status") not in ("queued", "running"):
                continue
            ts = _dt(e.get("created_at"))
            if ts and ts >= window_start:
                cnt += 1
        if cnt >= 60:
            oldest = None
            for e in events:
                if e.get("account_id") != account_id:
                    continue
                if e.get("status") not in ("queued", "running"):
                    continue
                ts = _dt(e.get("created_at"))
                if ts and ts >= window_start:
                    if oldest is None or ts < oldest:
                        oldest = ts
            retry_after = 1
            if oldest is not None:
                retry_after = max(1, int(60 - (now - oldest).total_seconds()))
            return retry_after
        return None

    def _log_event(account_id, site_id_for_event, deploy_id_for_event, status_value, request_obj, response_obj=None, error_message=None, started_at=None, ended_at=None):
        ev = {
            "id": _new_id("nlt_evt"),
            "account_id": account_id,
            "site_id": site_id_for_event,
            "deploy_id": deploy_id_for_event,
            "event_type": "api_call_audit",
            "status": status_value,
            "request": request_obj,
            "response": response_obj,
            "http_method": None,
            "http_path": None,
            "http_status_code": None,
            "error_message": error_message,
            "started_at": started_at,
            "ended_at": ended_at,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        events.append(ev)
        _save("observability_events.json", events)
        return ev

    active_accounts = [a for a in accounts if a.get("is_active") is True and a.get("status") in ("connected", "error") and isinstance(a.get("access_token_ciphertext"), str) and a.get("access_token_ciphertext")]
    if not active_accounts:
        return _err("UNAUTHORIZED", "No active Netlify account connection available.")
    account = active_accounts[0]
    account_id = account.get("id")

    retry_after = _rate_limited(account_id)
    if retry_after is not None:
        _log_event(account_id, None, None, "failed", {"tool": "restore-deploy", "params": {"deploy_id": deploy_id, "netlify_deploy_id": netlify_deploy_id}}, error_message="Rate limit exceeded", ended_at=now_iso)
        return _err("RATE_LIMIT", "Rate limit exceeded. Try again later.", retry_after=retry_after)

    if deploy_id is None and netlify_deploy_id is None:
        _log_event(account_id, None, None, "failed", {"tool": "restore-deploy", "params": {"deploy_id": deploy_id, "netlify_deploy_id": netlify_deploy_id}}, error_message="Missing deploy identifier", ended_at=now_iso)
        return _err("VALIDATION_ERROR", "Either deploy_id or netlify_deploy_id must be provided.")
    if deploy_id is not None:
        if not isinstance(deploy_id, str) or not re.match(r"^nlt_dpl_[0-9A-Z]{4,}$", deploy_id):
            _log_event(account_id, None, None, "failed", {"tool": "restore-deploy", "params": {"deploy_id": deploy_id}}, error_message="Malformed deploy_id", ended_at=now_iso)
            return _err("VALIDATION_ERROR", "deploy_id is malformed.")
    if netlify_deploy_id is not None:
        if not isinstance(netlify_deploy_id, str) or not netlify_deploy_id.strip():
            _log_event(account_id, None, None, "failed", {"tool": "restore-deploy", "params": {"netlify_deploy_id": netlify_deploy_id}}, error_message="Malformed netlify_deploy_id", ended_at=now_iso)
            return _err("VALIDATION_ERROR", "netlify_deploy_id is malformed.")

    # Resolve the referenced deploy
    ref_deploy = None
    if deploy_id is not None:
        for d in deploys:
            if d.get("id") == deploy_id:
                ref_deploy = d
                break
    else:
        for d in deploys:
            if d.get("netlify_deploy_id") == netlify_deploy_id:
                ref_deploy = d
                break

    if not ref_deploy:
        _log_event(account_id, None, None, "failed", {"tool": "restore-deploy", "params": {"deploy_id": deploy_id, "netlify_deploy_id": netlify_deploy_id}}, error_message="Deploy not found", ended_at=now_iso)
        return _err("NOT_FOUND", "Deploy not found.")

    site_row = None
    for s in sites:
        if s.get("id") == ref_deploy.get("site_id"):
            site_row = s
            break
    if not site_row or site_row.get("account_id") != account_id:
        _log_event(account_id, site_row.get("id") if site_row else None, ref_deploy.get("id"), "failed", {"tool": "restore-deploy", "params": {"deploy_id": deploy_id, "netlify_deploy_id": netlify_deploy_id}}, error_message="Unauthorized for deploy", ended_at=now_iso)
        return _err("UNAUTHORIZED", "You do not have access to this deploy under the active account.")

    # Restore is allowed only when referenced deploy exists for same site: satisfied by ref_deploy/site_row.
    # Create a new deploy record representing the restore operation, linked to same netlify_deploy_id? In real Netlify, restore triggers a new deploy.
    # We'll create a new local deploy with a derived netlify_deploy_id suffix, keeping uniqueness per site.
    base_netlify_id = ref_deploy.get("netlify_deploy_id")
    if not isinstance(base_netlify_id, str) or not base_netlify_id:
        # still allow; fabricate a stable remote id for audit consistency without inventing secrets
        base_netlify_id = f"restore_of_{ref_deploy.get('id')}"
    restore_netlify_id = f"{base_netlify_id}:restore:{now.strftime('%Y%m%d%H%M%S')}"

    # Ensure uniqueness(site_id, netlify_deploy_id)
    existing = None
    for d in deploys:
        if d.get("site_id") == site_row.get("id") and d.get("netlify_deploy_id") == restore_netlify_id:
            existing = d
            break

    restore_record = None
    if existing:
        restore_record = dict(existing)
        from_status = restore_record.get("status")
        if from_status != "restoring":
            # must move into restoring via valid transition if possible
            if "restoring" not in transitions.get(from_status, []):
                _log_event(account_id, site_row.get("id"), restore_record.get("id"), "failed", {"tool": "restore-deploy", "params": {"deploy_id": deploy_id, "netlify_deploy_id": netlify_deploy_id}}, error_message="Invalid transition to restoring", ended_at=now_iso)
                return _err("INVALID_TRANSITION", "Cannot transition existing restore deploy to restoring.", from_status=from_status, to_status="restoring")
        restore_record["status"] = "restoring"
        restore_record["updated_at"] = now_iso
        # Persist update
        for i, d in enumerate(deploys):
            if d.get("id") == restore_record.get("id"):
                deploys[i] = restore_record
                break
    else:
        restore_record = {
            "id": _new_id("nlt_dpl"),
            "site_id": site_row.get("id"),
            "netlify_deploy_id": restore_netlify_id,
            "triggered_by": "restore_deploy",
            "branch": ref_deploy.get("branch"),
            "commit_ref": ref_deploy.get("commit_ref"),
            "deploy_url": ref_deploy.get("deploy_url"),
            "admin_url": ref_deploy.get("admin_url"),
            "status": "restoring",
            "is_production": True,  # restoring typically affects production
            "started_at": now_iso,
            "finished_at": None,
            "duration_seconds": None,
            "error_message": None,
            "metadata": {"restored_from_deploy_id": ref_deploy.get("id"), "restored_from_netlify_deploy_id": ref_deploy.get("netlify_deploy_id")},
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        deploys.append(restore_record)

    # Simulate completion to ready as a backend write-through (no external Netlify progress available offline).
    # Allowed transition restoring -> ready
    if "ready" not in transitions.get("restoring", []):
        _log_event(account_id, site_row.get("id"), restore_record.get("id"), "failed", {"tool": "restore-deploy", "params": {"deploy_id": deploy_id, "netlify_deploy_id": netlify_deploy_id}}, error_message="Lifecycle disallows restoring->ready", ended_at=now_iso)
        return _err("INVALID_TRANSITION", "Restore completion transition is not allowed.", from_status="restoring", to_status="ready")

    restore_record = dict(restore_record)
    restore_record["status"] = "ready"
    restore_record["finished_at"] = now_iso
    st = _dt(restore_record.get("started_at"))
    ft = _dt(restore_record.get("finished_at"))
    if st and ft and ft >= st:
        restore_record["duration_seconds"] = int((ft - st).total_seconds())
    elif restore_record.get("duration_seconds") is None:
        restore_record["duration_seconds"] = 0
    restore_record["updated_at"] = now_iso

    # Persist deploys
    for i, d in enumerate(deploys):
        if d.get("id") == restore_record.get("id"):
            deploys[i] = restore_record
            break
    _save("deploys.json", deploys)

    latency_ms = int((time.time() - t0) * 1000)
    resp = {
        "restored_from": ref_deploy,
        "deploy": restore_record,
        "site": site_row,
        "meta": {"latency_ms": latency_ms},
    }
    _log_event(account_id, site_row.get("id"), restore_record.get("id"), "completed", {"tool": "restore-deploy", "params": {"deploy_id": deploy_id, "netlify_deploy_id": netlify_deploy_id}}, response_obj={"restore_deploy_id": restore_record.get("id"), "status": restore_record.get("status")}, ended_at=now_iso)
    return resp

def list_functions(site_id=None, netlify_site_id=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, re, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0414000" if __import__("os").path.isdir("./environment_mix/0414000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        # deterministic enough for offline local store uniqueness
        raw = f"{prefix}:{now}:{time.time_ns()}".encode("utf-8")
        h = hashlib.sha256(raw).hexdigest()[:16].upper()
        return f"{prefix}{h}"

    def _sanitize(obj):
        # best-effort to avoid returning/recording secrets; also ensures JSON-serializable
        banned_keys = {"access_token", "access_token_ciphertext", "token", "authorization", "password", "secret"}
        def walk(x):
            if isinstance(x, dict):
                out = {}
                for k, v in x.items():
                    lk = str(k).lower()
                    if lk in banned_keys or "token" in lk and lk != "token_scopes":
                        out[k] = "[REDACTED]"
                    else:
                        out[k] = walk(v)
                return out
            if isinstance(x, list):
                return [walk(v) for v in x]
            if isinstance(x, (str, int, float, bool)) or x is None:
                return x
            return str(x)
        return walk(obj)

    def _record_event(account_id, status, request_obj=None, response_obj=None, site_id_val=None, error_message=None):
        events = _load("observability_events.json")
        ev_id = _new_id("nlt_evt_")
        latency_ms = int((time.time() - t0) * 1000)
        ev = {
            "id": ev_id,
            "account_id": account_id,
            "site_id": site_id_val,
            "deploy_id": None,
            "event_type": "functions_snapshot",
            "status": status,
            "request": _sanitize(request_obj) if request_obj is not None else None,
            "response": _sanitize(response_obj) if response_obj is not None else None,
            "http_method": None,
            "http_path": None,
            "http_status_code": None,
            "error_message": error_message,
            "started_at": None,
            "ended_at": now,
            "created_at": now,
            "updated_at": now,
            "latency_ms": latency_ms
        }
        events.append(ev)
        _save("observability_events.json", events)

    def _active_account():
        accts = _load("netlify_accounts.json")
        active = [a for a in accts if isinstance(a, dict) and a.get("is_active") is True]
        # must be connected or error (token present non-empty for these states by constraint)
        viable = [a for a in active if a.get("status") in ("connected", "error") and isinstance(a.get("access_token_ciphertext"), str) and a.get("access_token_ciphertext")]
        if viable:
            return viable[0]
        # If none active viable, search any account that could serve (per contract)
        any_viable = [a for a in accts if isinstance(a, dict) and a.get("status") in ("connected", "error") and isinstance(a.get("access_token_ciphertext"), str) and a.get("access_token_ciphertext")]
        return any_viable[0] if any_viable else None

    def _check_rate_limit(account_id):
        # per account, at most 60 tool executions per minute may be in status running/queued
        events = _load("observability_events.json")
        window_start = (datetime.datetime.utcnow() - datetime.timedelta(seconds=60)).replace(microsecond=0).isoformat() + "Z"
        cnt = 0
        oldest_ts = None
        for e in events:
            if not isinstance(e, dict):
                continue
            if e.get("account_id") != account_id:
                continue
            if e.get("status") not in ("running", "queued"):
                continue
            ts = e.get("created_at") or e.get("updated_at")
            if isinstance(ts, str) and ts >= window_start:
                cnt += 1
                if oldest_ts is None or ts < oldest_ts:
                    oldest_ts = ts
        if cnt >= 60:
            # retry-after seconds until window moves; approximate by 60s from oldest seen in window
            retry_after = 30
            if oldest_ts:
                try:
                    ot = datetime.datetime.fromisoformat(oldest_ts.replace("Z", ""))
                    delta = (ot + datetime.timedelta(seconds=60)) - datetime.datetime.utcnow()
                    retry_after = max(1, int(delta.total_seconds()))
                except Exception:
                    retry_after = 30
            return _err("RATE_LIMIT", "Rate limit exceeded", retry_after_seconds=retry_after)
        return None

    # Validate inputs
    if site_id is not None and not isinstance(site_id, str):
        return _err("VALIDATION_ERROR", "site_id must be a string")
    if netlify_site_id is not None and not isinstance(netlify_site_id, str):
        return _err("VALIDATION_ERROR", "netlify_site_id must be a string")
    if (site_id is None and netlify_site_id is None) or (site_id is not None and netlify_site_id is not None):
        return _err("VALIDATION_ERROR", "Provide exactly one of site_id or netlify_site_id")
    if site_id is not None and not re.match(r"^nlt_site_[0-9A-Z]{4,}$", site_id):
        return _err("VALIDATION_ERROR", "site_id format is invalid")
    if limit is not None:
        if not isinstance(limit, int):
            return _err("VALIDATION_ERROR", "limit must be an integer")
        if limit < 1 or limit > 200:
            return _err("VALIDATION_ERROR", "limit must be between 1 and 200")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string")

    acct = _active_account()
    if not acct:
        # no account context available
        return _err("UNAUTHORIZED", "No active Netlify account is available to serve this request")

    rl = _check_rate_limit(acct["id"])
    if rl:
        _record_event(acct["id"], "failed", request_obj={"tool": "list-functions", "site_id": site_id, "netlify_site_id": netlify_site_id, "limit": limit, "cursor": cursor}, response_obj=rl, site_id_val=site_id, error_message=rl["error"]["message"])
        return rl

    sites = _load("sites.json")
    target = None
    if site_id is not None:
        for s in sites:
            if isinstance(s, dict) and s.get("id") == site_id and s.get("account_id") == acct["id"]:
                target = s
                break
    else:
        for s in sites:
            if isinstance(s, dict) and s.get("netlify_site_id") == netlify_site_id and s.get("account_id") == acct["id"]:
                target = s
                break

    # must be active for this operation
    if not target:
        _record_event(acct["id"], "failed", request_obj={"tool": "list-functions", "site_id": site_id, "netlify_site_id": netlify_site_id, "limit": limit, "cursor": cursor}, response_obj=_err("NOT_FOUND", "Site not found"), site_id_val=site_id, error_message="Site not found")
        return _err("NOT_FOUND", "Site not found")
    if target.get("status") != "active":
        _record_event(acct["id"], "failed", request_obj={"tool": "list-functions", "site_id": target.get("id"), "netlify_site_id": target.get("netlify_site_id"), "limit": limit, "cursor": cursor}, response_obj=_err("INVALID_TRANSITION", "Site is not active"), site_id_val=target.get("id"), error_message="Site is not active")
        return _err("INVALID_TRANSITION", "Site is not active")

    # Functions inventory is stored via observability_events snapshots; synthesize a list from latest snapshot per site.
    events = _load("observability_events.json")
    latest = None
    for e in events:
        if not isinstance(e, dict):
            continue
        if e.get("account_id") != acct["id"]:
            continue
        if e.get("event_type") != "functions_snapshot":
            continue
        if e.get("site_id") != target.get("id"):
            continue
        if e.get("status") not in ("completed", "running", "queued"):
            continue
        ts = e.get("created_at") or e.get("updated_at")
        if not isinstance(ts, str):
            continue
        if latest is None or ts > (latest.get("created_at") or latest.get("updated_at") or ""):
            latest = e

    functions = []
    if latest and isinstance(latest.get("response"), dict):
        resp = latest["response"]
        # accept several shapes: {"functions":[...]} or {"items":[...]} or {"data":[...]}
        if isinstance(resp.get("functions"), list):
            functions = resp.get("functions") or []
        elif isinstance(resp.get("items"), list):
            functions = resp.get("items") or []
        elif isinstance(resp.get("data"), list):
            functions = resp.get("data") or []
        else:
            functions = []

    # normalize to list of dicts with stable keys where possible
    norm = []
    for f in functions:
        if isinstance(f, dict):
            norm.append(f)
        else:
            norm.append({"name": str(f)})

    # sort by name when present
    norm.sort(key=lambda x: (str(x.get("name", "")).lower(), str(x.get("id", ""))))

    # pagination via cursor as integer offset (opaque string)
    offset = 0
    if cursor:
        if not cursor.startswith("offset:"):
            return _err("VALIDATION_ERROR", "cursor is invalid")
        try:
            offset = int(cursor.split(":", 1)[1])
        except Exception:
            return _err("VALIDATION_ERROR", "cursor is invalid")
        if offset < 0:
            return _err("VALIDATION_ERROR", "cursor is invalid")

    lim = limit if limit is not None else 50
    page = norm[offset:offset + lim]
    next_off = offset + len(page)
    has_more = next_off < len(norm)
    next_cursor = f"offset:{next_off}" if has_more else None

    out = {
        "site": {
            "id": target.get("id"),
            "netlify_site_id": target.get("netlify_site_id"),
            "name": target.get("name")
        },
        "functions": page,
        "pagination": {
            "total": len(norm),
            "limit": lim,
            "cursor": cursor,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }
    _record_event(acct["id"], "completed", request_obj={"tool": "list-functions", "site_id": target.get("id"), "netlify_site_id": target.get("netlify_site_id"), "limit": limit, "cursor": cursor}, response_obj={"count": len(page), "total": len(norm), "has_more": has_more}, site_id_val=target.get("id"))
    return out

def enable_branch_deploy(branch, site_id=None, netlify_site_id=None, **_extra):
    import json, os, datetime, time, re, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0414000" if __import__("os").path.isdir("./environment_mix/0414000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _gen_id(prefix):
        # deterministic-enough offline id, matches pattern for sites; events use separate prefix
        return f"{prefix}{uuid.uuid4().hex.upper()}"

    def _json_safe(obj):
        try:
            json.dumps(obj, ensure_ascii=False)
            return True
        except Exception:
            return False

    def _sanitize(obj):
        # prevent accidental credential exfiltration in audit logs
        if obj is None:
            return None
        if isinstance(obj, (str, int, float, bool)):
            return obj
        if isinstance(obj, list):
            return [_sanitize(x) for x in obj[:2000]]
        if isinstance(obj, dict):
            out = {}
            for k, v in list(obj.items())[:2000]:
                lk = str(k).lower()
                if "access_token" in lk or "token" == lk or "ciphertext" in lk:
                    out[k] = "[REDACTED]"
                else:
                    out[k] = _sanitize(v)
            return out
        return str(obj)

    t0 = time.time()
    accounts = _load("netlify_accounts.json")
    sites = _load("sites.json")
    events = _load("observability_events.json")

    active_acct = None
    for a in accounts:
        if isinstance(a, dict) and a.get("is_active") is True:
            active_acct = a
            break

    # rate limit check: per account, at most 60 executions per minute in queued/running across observability_events
    def _rate_limited(acct_id):
        cutoff = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(minutes=1)
        c = 0
        for e in events:
            if not isinstance(e, dict):
                continue
            if e.get("account_id") != acct_id:
                continue
            if e.get("status") not in ("queued", "running"):
                continue
            ts = e.get("created_at")
            if not ts:
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            except Exception:
                continue
            if dt >= cutoff:
                c += 1
        return c >= 60

    # Prepare base event row and append before returning (all calls must be logged)
    evt_id = _gen_id("nlt_evt_")
    evt = {
        "id": evt_id,
        "account_id": active_acct.get("id") if isinstance(active_acct, dict) else "unknown",
        "site_id": None,
        "deploy_id": None,
        "event_type": "api_call_audit",
        "status": "queued",
        "request": _sanitize({"tool": "enable-branch-deploy", "site_id": site_id, "netlify_site_id": netlify_site_id, "branch": branch}),
        "response": None,
        "http_method": "PATCH",
        "http_path": None,
        "http_status_code": None,
        "error_message": None,
        "started_at": None,
        "ended_at": None,
        "created_at": _now(),
        "updated_at": _now(),
    }

    def _finish_and_return(body, http_status=200, status="completed", error_message=None):
        evt["status"] = status
        evt["http_status_code"] = http_status
        evt["error_message"] = error_message
        evt["ended_at"] = _now()
        evt["updated_at"] = _now()
        evt["response"] = _sanitize(body if body is not None else None)
        # ensure request/response are json-serializable
        if not _json_safe(evt.get("request")):
            evt["request"] = {"note": "request not serializable"}
        if not _json_safe(evt.get("response")):
            evt["response"] = {"note": "response not serializable"}
        events.append(evt)
        _save("observability_events.json", events)
        return body

    # Auth: must have an active account with usable credentials (ciphertext non-empty, not revoked)
    if not isinstance(active_acct, dict) or not active_acct.get("id"):
        return _finish_and_return(_err("UNAUTHORIZED", "No active Netlify account selected."), http_status=401, status="failed", error_message="no_active_account")

    if _rate_limited(active_acct["id"]):
        return _finish_and_return(_err("RATE_LIMIT", "Rate limit exceeded. Try again later.", retry_after_seconds=60), http_status=429, status="failed", error_message="rate_limited")

    if active_acct.get("status") != "connected":
        return _finish_and_return(_err("UNAUTHORIZED", "Active account is not connected."), http_status=401, status="failed", error_message="account_not_connected")
    if not isinstance(active_acct.get("access_token_ciphertext"), str) or not active_acct["access_token_ciphertext"].strip():
        return _finish_and_return(_err("UNAUTHORIZED", "Active account credentials are missing."), http_status=401, status="failed", error_message="missing_credentials")

    # Validation
    if not isinstance(branch, str) or not branch.strip():
        return _finish_and_return(_err("VALIDATION_ERROR", "branch is required and must be a non-empty string.", field="branch"), http_status=400, status="failed", error_message="invalid_branch")

    if (site_id is None and netlify_site_id is None) or (site_id is not None and netlify_site_id is not None):
        return _finish_and_return(_err("VALIDATION_ERROR", "Provide exactly one of site_id or netlify_site_id.", fields=["site_id", "netlify_site_id"]), http_status=400, status="failed", error_message="invalid_identifiers")

    if site_id is not None:
        if not isinstance(site_id, str) or not re.match(r"^nlt_site_[0-9A-Z]{4,}$", site_id):
            return _finish_and_return(_err("VALIDATION_ERROR", "site_id is invalid.", field="site_id"), http_status=400, status="failed", error_message="invalid_site_id")

    if netlify_site_id is not None and (not isinstance(netlify_site_id, str) or not netlify_site_id.strip()):
        return _finish_and_return(_err("VALIDATION_ERROR", "netlify_site_id must be a non-empty string.", field="netlify_site_id"), http_status=400, status="failed", error_message="invalid_netlify_site_id")

    # Resolve site
    site = None
    if site_id is not None:
        for s in sites:
            if isinstance(s, dict) and s.get("id") == site_id:
                site = s
                break
    else:
        for s in sites:
            if isinstance(s, dict) and s.get("netlify_site_id") == netlify_site_id and s.get("account_id") == active_acct["id"]:
                site = s
                break

    if not site:
        return _finish_and_return(_err("NOT_FOUND", "Site not found."), http_status=404, status="failed", error_message="site_not_found")

    evt["site_id"] = site.get("id")
    evt["http_path"] = f"/api/v1/sites/{site.get('netlify_site_id')}/branch_deploys/{branch.strip()}"

    # Enforce business rule: operates only on active sites
    if site.get("status") != "active":
        return _finish_and_return(_err("INVALID_TRANSITION", "Branch deploy configuration can only be changed for active sites.", site_status=site.get("status")), http_status=409, status="failed", error_message="site_not_active")

    # Ensure belongs to active account
    if site.get("account_id") != active_acct["id"]:
        return _finish_and_return(_err("UNAUTHORIZED", "Site does not belong to the active account."), http_status=401, status="failed", error_message="site_wrong_account")

    # Mutate: enable branch deploy for branch
    b = branch.strip()
    if not isinstance(site.get("branch_deploys"), dict):
        site["branch_deploys"] = {}

    prev = site["branch_deploys"].get(b)
    # Idempotent behavior: if already enabled, keep but refresh updated_at
    new_cfg = {}
    if isinstance(prev, dict):
        new_cfg.update(prev)

    new_cfg["enabled"] = True
    if "enabled_at" not in new_cfg or not isinstance(new_cfg.get("enabled_at"), str):
        new_cfg["enabled_at"] = _now()
    new_cfg["updated_at"] = _now()

    site["branch_deploys"][b] = new_cfg
    site["updated_at"] = _now()

    _save("sites.json", sites)

    resp = {
        "site_id": site.get("id"),
        "netlify_site_id": site.get("netlify_site_id"),
        "branch": b,
        "branch_deploy": site["branch_deploys"].get(b),
    }
    return _finish_and_return(resp, http_status=200, status="completed")

