def set_blob(site_id, key, value, encoding=None, content_type=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0414000" if __import__("os").path.isdir("./environment_mix/0414000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(datetime.datetime.utcnow().timestamp() * 1000)
        payload = f"{prefix}:{ts}:{os.getpid()}:{time.time_ns()}".encode("utf-8")
        digest = hashlib.sha256(payload).digest()
        n = int.from_bytes(digest, "big")
        out = []
        for _ in range(26):
            n, r = divmod(n, 32)
            out.append(alphabet[r])
        return prefix + "".join(out)

    def _record_event(account_id, site_id_for_event, status, request_obj=None, response_obj=None, error_message=None, http_status_code=None):
        events = _load("observability_events.json")
        ev = {
            "id": _new_id("nlt_evt_"),
            "account_id": account_id,
            "site_id": site_id_for_event,
            "deploy_id": None,
            "event_type": "api_call_audit",
            "status": status,
            "request": request_obj,
            "response": response_obj,
            "http_method": "PUT",
            "http_path": "/api/v1/blobs/set",
            "http_status_code": http_status_code,
            "error_message": error_message,
            "started_at": now,
            "ended_at": now if status in ("completed", "failed", "canceled") else None,
            "created_at": now,
            "updated_at": now,
        }
        events.append(ev)
        _save("observability_events.json", events)
        return ev

    def _rate_limit_check(account_id):
        events = _load("observability_events.json")
        window_start = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        cnt = 0
        for e in events:
            if e.get("account_id") != account_id:
                continue
            ca = e.get("created_at")
            if not isinstance(ca, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ca.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= window_start and e.get("status") in ("queued", "running"):
                cnt += 1
        if cnt >= 60:
            return False, 60
        return True, None

    # Validate inputs
    if not isinstance(site_id, str) or not re.match(r"^nlt_site_[0-9A-HJKMNP-TV-Z]{10,}$", site_id):
        return _err("VALIDATION_ERROR", "site_id is required and must match expected format", field="site_id")
    if not isinstance(key, str) or len(key) < 1 or len(key) > 512:
        return _err("VALIDATION_ERROR", "key is required and must be between 1 and 512 characters", field="key")
    if not isinstance(value, str):
        return _err("VALIDATION_ERROR", "value is required and must be a string", field="value")
    if encoding is None:
        encoding = "utf8"
    if not isinstance(encoding, str) or encoding not in ("utf8", "base64"):
        return _err("VALIDATION_ERROR", "encoding must be one of: utf8, base64", field="encoding")
    if not isinstance(content_type, str) or not content_type.strip():
        return _err("VALIDATION_ERROR", "content_type is required for blobs", field="content_type")

    accounts = _load("netlify_accounts.json")
    active = [a for a in accounts if a.get("is_active") is True and a.get("status") in ("connected", "error") and isinstance(a.get("access_token_ciphertext"), str) and a.get("access_token_ciphertext")]
    if not active:
        return _err("UNAUTHORIZED", "No active Netlify account is selected or credentials are unavailable")

    sites = _load("sites.json")
    site = None
    account = None
    for a in active:
        for s in sites:
            if s.get("id") == site_id and s.get("account_id") == a.get("id"):
                site = s
                account = a
                break
        if site:
            break
    if not site:
        exists_any = any(s.get("id") == site_id for s in sites)
        if exists_any:
            return _err("UNAUTHORIZED", "Active account does not have access to the requested site")
        return _err("NOT_FOUND", "Site not found", site_id=site_id)

    allowed_ok = _rate_limit_check(account.get("id"))
    if not allowed_ok[0]:
        _record_event(account.get("id"), site_id, "failed", request_obj={"site_id": site_id, "key": key, "encoding": encoding, "content_type": content_type}, response_obj=None, error_message="Rate limit exceeded", http_status_code=429)
        return _err("RATE_LIMIT", "Rate limit exceeded", retry_after_seconds=allowed_ok[1])

    if site.get("status") != "active":
        _record_event(account.get("id"), site_id, "failed", request_obj={"site_id": site_id, "key": key, "encoding": encoding, "content_type": content_type}, response_obj=None, error_message="Site is not active", http_status_code=409)
        return _err("CONFLICT", "Operation allowed only for active sites", site_status=site.get("status"))

    # Prepare stored value_text/value_bytes per schema
    value_text = None
    value_bytes = None
    if encoding == "utf8":
        value_text = value
        value_bytes = None
    else:
        # validate base64 and store as-is
        try:
            base64.b64decode(value.encode("utf-8"), validate=True)
        except Exception:
            return _err("VALIDATION_ERROR", "value must be valid base64 when encoding='base64'", field="value")
        value_bytes = value
        value_text = None

    # Upsert into site_kv where namespace='blob'
    kv = _load("site_kv.json")

    # Enforce unique(active) on (site_id, namespace, key)
    existing_active = None
    existing_deleted = None
    for row in kv:
        if row.get("site_id") == site_id and row.get("namespace") == "blob" and row.get("key") == key:
            if row.get("status") == "active":
                existing_active = row
            elif row.get("status") == "deleted":
                existing_deleted = row

    # If there are multiple actives due to datastore corruption, treat as conflict.
    if existing_active and any(r for r in kv if r is not existing_active and r.get("site_id") == site_id and r.get("namespace") == "blob" and r.get("key") == key and r.get("status") == "active"):
        _record_event(account.get("id"), site_id, "failed", request_obj={"site_id": site_id, "key": key, "encoding": encoding, "content_type": content_type}, response_obj=None, error_message="Multiple active blobs for same key", http_status_code=409)
        return _err("CONFLICT", "Multiple active blobs exist for the same key")

    etag_src = (value_bytes if value_bytes is not None else value_text).encode("utf-8")
    etag = hashlib.sha256(etag_src).hexdigest()

    if existing_active:
        existing_active["value_text"] = value_text
        existing_active["value_bytes"] = value_bytes
        existing_active["content_type"] = content_type
        existing_active["is_secret"] = False
        existing_active["etag"] = etag
        existing_active["status"] = "active"
        existing_active["deleted_at"] = None
        existing_active["updated_at"] = now
        stored = existing_active
    elif existing_deleted:
        # revive deleted -> active (allowed transition)
        existing_deleted["value_text"] = value_text
        existing_deleted["value_bytes"] = value_bytes
        existing_deleted["content_type"] = content_type
        existing_deleted["is_secret"] = False
        existing_deleted["etag"] = etag
        existing_deleted["status"] = "active"
        existing_deleted["deleted_at"] = None
        existing_deleted["updated_at"] = now
        stored = existing_deleted
    else:
        stored = {
            "id": _new_id("nlt_kv_"),
            "site_id": site_id,
            "namespace": "blob",
            "key": key,
            "value_text": value_text,
            "value_bytes": value_bytes,
            "content_type": content_type,
            "is_secret": False,
            "etag": etag,
            "status": "active",
            "deleted_at": None,
            "created_at": now,
            "updated_at": now,
        }
        kv.append(stored)

    _save("site_kv.json", kv)

    resp = {
        "site_id": site_id,
        "key": key,
        "content_type": stored.get("content_type"),
        "etag": stored.get("etag"),
        "status": stored.get("status"),
        "updated_at": stored.get("updated_at"),
    }

    _record_event(
        account.get("id"),
        site_id,
        "completed",
        request_obj={"site_id": site_id, "key": key, "encoding": encoding, "content_type": content_type},
        response_obj={"site_id": site_id, "key": key, "content_type": content_type, "etag": etag},
        http_status_code=200,
    )
    return {"blob": resp, "latency_ms": int((time.time() - t0) * 1000)}

def delete_blob(site_id, key, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0414000" if __import__("os").path.isdir("./environment_mix/0414000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(datetime.datetime.utcnow().timestamp() * 1000)
        payload = f"{prefix}:{ts}:{os.getpid()}:{time.time_ns()}".encode("utf-8")
        digest = hashlib.sha256(payload).digest()
        n = int.from_bytes(digest, "big")
        out = []
        for _ in range(26):
            n, r = divmod(n, 32)
            out.append(alphabet[r])
        return prefix + "".join(out)

    def _record_event(account_id, site_id_for_event, status, request_obj=None, response_obj=None, error_message=None, http_status_code=None):
        events = _load("observability_events.json")
        ev = {
            "id": _new_id("nlt_evt_"),
            "account_id": account_id,
            "site_id": site_id_for_event,
            "deploy_id": None,
            "event_type": "api_call_audit",
            "status": status,
            "request": request_obj,
            "response": response_obj,
            "http_method": "DELETE",
            "http_path": "/api/v1/blobs/delete",
            "http_status_code": http_status_code,
            "error_message": error_message,
            "started_at": now,
            "ended_at": now if status in ("completed", "failed", "canceled") else None,
            "created_at": now,
            "updated_at": now,
        }
        events.append(ev)
        _save("observability_events.json", events)
        return ev

    def _rate_limit_check(account_id):
        events = _load("observability_events.json")
        window_start = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        cnt = 0
        for e in events:
            if e.get("account_id") != account_id:
                continue
            ca = e.get("created_at")
            if not isinstance(ca, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ca.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= window_start and e.get("status") in ("queued", "running"):
                cnt += 1
        if cnt >= 60:
            return False, 60
        return True, None

    # Validate inputs
    if not isinstance(site_id, str) or not re.match(r"^nlt_site_[0-9A-HJKMNP-TV-Z]{10,}$", site_id):
        return _err("VALIDATION_ERROR", "site_id is required and must match expected format", field="site_id")
    if not isinstance(key, str) or len(key) < 1:
        return _err("VALIDATION_ERROR", "key is required and must be non-empty", field="key")

    accounts = _load("netlify_accounts.json")
    active = [a for a in accounts if a.get("is_active") is True and a.get("status") in ("connected", "error") and isinstance(a.get("access_token_ciphertext"), str) and a.get("access_token_ciphertext")]
    if not active:
        return _err("UNAUTHORIZED", "No active Netlify account is selected or credentials are unavailable")

    sites = _load("sites.json")
    site = None
    account = None
    for a in active:
        for s in sites:
            if s.get("id") == site_id and s.get("account_id") == a.get("id"):
                site = s
                account = a
                break
        if site:
            break
    if not site:
        exists_any = any(s.get("id") == site_id for s in sites)
        if exists_any:
            return _err("UNAUTHORIZED", "Active account does not have access to the requested site")
        return _err("NOT_FOUND", "Site not found", site_id=site_id)

    allowed_ok = _rate_limit_check(account.get("id"))
    if not allowed_ok[0]:
        _record_event(account.get("id"), site_id, "failed", request_obj={"site_id": site_id, "key": key}, response_obj=None, error_message="Rate limit exceeded", http_status_code=429)
        return _err("RATE_LIMIT", "Rate limit exceeded", retry_after_seconds=allowed_ok[1])

    if site.get("status") != "active":
        _record_event(account.get("id"), site_id, "failed", request_obj={"site_id": site_id, "key": key}, response_obj=None, error_message="Site is not active", http_status_code=409)
        return _err("CONFLICT", "Operation allowed only for active sites", site_status=site.get("status"))

    kv = _load("site_kv.json")
    idx = None
    for i, row in enumerate(kv):
        if row.get("site_id") == site_id and row.get("namespace") == "blob" and row.get("key") == key and row.get("status") == "active":
            idx = i
            break
    if idx is None:
        _record_event(account.get("id"), site_id, "completed", request_obj={"site_id": site_id, "key": key}, response_obj={"deleted": False, "found": False}, http_status_code=404)
        return _err("NOT_FOUND", "Blob not found", key=key)

    kv[idx]["status"] = "deleted"
    kv[idx]["deleted_at"] = now
    kv[idx]["updated_at"] = now
    # Keep value fields for soft-delete audit; allowed by schema.
    _save("site_kv.json", kv)

    _record_event(
        account.get("id"),
        site_id,
        "completed",
        request_obj={"site_id": site_id, "key": key},
        response_obj={"deleted": True, "key": key, "deleted_at": now},
        http_status_code=200,
    )
    return {"deleted": True, "site_id": site_id, "key": key, "deleted_at": now, "latency_ms": int((time.time() - t0) * 1000)}

def list_blobs(site_id, prefix=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, hashlib, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0414000" if __import__("os").path.isdir("./environment_mix/0414000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix_):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(datetime.datetime.utcnow().timestamp() * 1000)
        payload = f"{prefix_}:{ts}:{os.getpid()}:{time.time_ns()}".encode("utf-8")
        digest = hashlib.sha256(payload).digest()
        n = int.from_bytes(digest, "big")
        out = []
        for _ in range(26):
            n, r = divmod(n, 32)
            out.append(alphabet[r])
        return prefix_ + "".join(out)

    def _record_event(account_id, site_id_for_event, status, request_obj=None, response_obj=None, error_message=None, http_status_code=None):
        events = _load("observability_events.json")
        ev = {
            "id": _new_id("nlt_evt_"),
            "account_id": account_id,
            "site_id": site_id_for_event,
            "deploy_id": None,
            "event_type": "api_call_audit",
            "status": status,
            "request": request_obj,
            "response": response_obj,
            "http_method": "GET",
            "http_path": "/api/v1/blobs/list",
            "http_status_code": http_status_code,
            "error_message": error_message,
            "started_at": now,
            "ended_at": now if status in ("completed", "failed", "canceled") else None,
            "created_at": now,
            "updated_at": now,
        }
        events.append(ev)
        _save("observability_events.json", events)
        return ev

    def _rate_limit_check(account_id):
        events = _load("observability_events.json")
        window_start = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        cnt = 0
        for e in events:
            if e.get("account_id") != account_id:
                continue
            ca = e.get("created_at")
            if not isinstance(ca, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ca.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= window_start and e.get("status") in ("queued", "running"):
                cnt += 1
        if cnt >= 60:
            return False, 60
        return True, None

    def _encode_cursor(last_key):
        raw = json.dumps({"k": last_key}, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    def _decode_cursor(cur):
        if not isinstance(cur, str) or not cur:
            return None
        pad = "=" * (-len(cur) % 4)
        try:
            raw = base64.urlsafe_b64decode((cur + pad).encode("utf-8"))
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict) or "k" not in obj or not isinstance(obj["k"], str):
                return None
            return obj["k"]
        except Exception:
            return None

    # Validate inputs
    if not isinstance(site_id, str) or not re.match(r"^nlt_site_[0-9A-HJKMNP-TV-Z]{10,}$", site_id):
        return _err("VALIDATION_ERROR", "site_id is required and must match expected format", field="site_id")
    if prefix is not None and not isinstance(prefix, str):
        return _err("VALIDATION_ERROR", "prefix must be a string when provided", field="prefix")
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 1000:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 1000", field="limit")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string when provided", field="cursor")

    accounts = _load("netlify_accounts.json")
    active = [a for a in accounts if a.get("is_active") is True and a.get("status") in ("connected", "error") and isinstance(a.get("access_token_ciphertext"), str) and a.get("access_token_ciphertext")]
    if not active:
        return _err("UNAUTHORIZED", "No active Netlify account is selected or credentials are unavailable")

    sites = _load("sites.json")
    site = None
    account = None
    for a in active:
        for s in sites:
            if s.get("id") == site_id and s.get("account_id") == a.get("id"):
                site = s
                account = a
                break
        if site:
            break
    if not site:
        exists_any = any(s.get("id") == site_id for s in sites)
        if exists_any:
            return _err("UNAUTHORIZED", "Active account does not have access to the requested site")
        return _err("NOT_FOUND", "Site not found", site_id=site_id)

    allowed_ok = _rate_limit_check(account.get("id"))
    if not allowed_ok[0]:
        _record_event(account.get("id"), site_id, "failed", request_obj={"site_id": site_id, "prefix": prefix, "limit": limit, "cursor": cursor}, response_obj=None, error_message="Rate limit exceeded", http_status_code=429)
        return _err("RATE_LIMIT", "Rate limit exceeded", retry_after_seconds=allowed_ok[1])

    if site.get("status") != "active":
        _record_event(account.get("id"), site_id, "failed", request_obj={"site_id": site_id, "prefix": prefix, "limit": limit, "cursor": cursor}, response_obj=None, error_message="Site is not active", http_status_code=409)
        return _err("CONFLICT", "Operation allowed only for active sites", site_status=site.get("status"))

    start_after = None
    if cursor:
        start_after = _decode_cursor(cursor)
        if start_after is None:
            return _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")

    kv = _load("site_kv.json")
    rows = []
    for row in kv:
        if row.get("site_id") != site_id:
            continue
        if row.get("namespace") != "blob":
            continue
        if row.get("status") != "active":
            continue
        k = row.get("key")
        if not isinstance(k, str):
            continue
        if prefix is not None and not k.startswith(prefix):
            continue
        rows.append(row)

    rows.sort(key=lambda r: r.get("key", ""))

    # Apply cursor pagination (exclusive)
    if start_after is not None:
        rows = [r for r in rows if r.get("key", "") > start_after]

    total = len(rows)
    page = rows[:limit]
    has_more = total > limit
    next_cursor = _encode_cursor(page[-1]["key"]) if has_more and page else None

    items = []
    for r in page:
        items.append({
            "key": r.get("key"),
            "content_type": r.get("content_type"),
            "etag": r.get("etag"),
            "updated_at": r.get("updated_at"),
        })

    _record_event(
        account.get("id"),
        site_id,
        "completed",
        request_obj={"site_id": site_id, "prefix": prefix, "limit": limit, "cursor": cursor},
        response_obj={"count": len(items), "has_more": has_more},
        http_status_code=200,
    )

    return {
        "site_id": site_id,
        "blobs": items,
        "pagination": {"limit": limit, "cursor": cursor, "next_cursor": next_cursor, "has_more": has_more, "total": total},
        "latency_ms": int((time.time() - t0) * 1000),
    }

def start_dev_server(site_id, repo_root, command=None, port=None, target_port=None, **_extra):
    import json, os, datetime, re, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0414000" if __import__("os").path.isdir("./environment_mix/0414000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        ts = datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S")
        rnd = os.urandom(4).hex()
        return f"{prefix}_{ts}_{rnd}"

    def _sanitize(obj):
        def scrub(x):
            if isinstance(x, dict):
                y = {}
                for k, v in x.items():
                    lk = str(k).lower()
                    if "access_token" in lk or "cipher" in lk or lk == "token":
                        y[k] = "[REDACTED]"
                    else:
                        y[k] = scrub(v)
                return y
            if isinstance(x, list):
                return [scrub(v) for v in x]
            if isinstance(x, (str, int, float, bool)) or x is None:
                return x
            return str(x)
        return scrub(obj)

    started = time.time()
    accounts = _load("netlify_accounts.json")
    sites = _load("sites.json")
    events = _load("observability_events.json")
    deploys = _load("deploys.json")

    # Resolve active account with usable credential
    active = None
    for a in accounts:
        if a.get("is_active") is True and a.get("status") in ("connected", "error") and isinstance(a.get("access_token_ciphertext"), str) and a.get("access_token_ciphertext"):
            active = a
            break
    if not active:
        ev = {
            "id": _new_id("nlt_evt"),
            "account_id": (accounts[0]["id"] if accounts else "unknown"),
            "site_id": site_id if isinstance(site_id, str) else None,
            "deploy_id": None,
            "event_type": "dev_server_session",
            "status": "failed",
            "request": _sanitize({"tool": "start-dev-server", "site_id": site_id, "repo_root": repo_root, "command": command, "port": port, "target_port": target_port}),
            "response": None,
            "http_method": None,
            "http_path": None,
            "http_status_code": None,
            "error_message": "No active Netlify account connection available.",
            "started_at": _now(),
            "ended_at": _now(),
            "created_at": _now(),
            "updated_at": _now(),
        }
        events.append(ev)
        _save("observability_events.json", events)
        return _err("UNAUTHORIZED", "No active Netlify account selected or credentials unavailable.")

    # Rate limit check (same rule)
    now_dt = datetime.datetime.utcnow()
    one_min_ago = now_dt - datetime.timedelta(seconds=60)
    in_window = 0
    for e in events:
        if e.get("account_id") != active.get("id"):
            continue
        if e.get("status") not in ("running", "queued"):
            continue
        ts = e.get("created_at") or e.get("started_at")
        if not isinstance(ts, str):
            continue
        try:
            tdt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            continue
        if tdt >= one_min_ago:
            in_window += 1
    for d in deploys:
        if d.get("status") not in ("queued", "building", "uploading", "restoring"):
            continue
        sid = d.get("site_id")
        site_row = next((s for s in sites if s.get("id") == sid), None)
        if not site_row or site_row.get("account_id") != active.get("id"):
            continue
        ts = d.get("created_at") or d.get("updated_at")
        if not isinstance(ts, str):
            continue
        try:
            tdt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            continue
        if tdt >= one_min_ago:
            in_window += 1
    if in_window >= 60:
        ev = {
            "id": _new_id("nlt_evt"),
            "account_id": active["id"],
            "site_id": site_id if isinstance(site_id, str) else None,
            "deploy_id": None,
            "event_type": "dev_server_session",
            "status": "failed",
            "request": _sanitize({"tool": "start-dev-server", "site_id": site_id, "repo_root": repo_root, "command": command, "port": port, "target_port": target_port}),
            "response": None,
            "http_method": None,
            "http_path": None,
            "http_status_code": None,
            "error_message": "Rate limit exceeded.",
            "started_at": _now(),
            "ended_at": _now(),
            "created_at": _now(),
            "updated_at": _now(),
        }
        events.append(ev)
        _save("observability_events.json", events)
        return _err("RATE_LIMIT", "Rate limit exceeded.", retry_after_seconds=60)

    # Validate inputs
    if not isinstance(site_id, str) or not site_id:
        return _err("VALIDATION_ERROR", "site_id is required and must be a string.")
    if not re.match(r"^nlt_site_[0-9A-HJKMNP-TV-Z]{10,}$", site_id):
        return _err("VALIDATION_ERROR", "site_id does not match expected format.")
    if not isinstance(repo_root, str) or not repo_root.strip():
        return _err("VALIDATION_ERROR", "repo_root is required and must be a non-empty string.")
    if command is not None and not isinstance(command, str):
        return _err("VALIDATION_ERROR", "command must be a string when provided.")
    if command is not None and not command.strip():
        return _err("VALIDATION_ERROR", "command must be non-empty when provided.")
    if port is not None:
        if not isinstance(port, int):
            return _err("VALIDATION_ERROR", "port must be an integer.")
        if port < 1 or port > 65535:
            return _err("VALIDATION_ERROR", "port must be between 1 and 65535.")
    if target_port is not None:
        if not isinstance(target_port, int):
            return _err("VALIDATION_ERROR", "target_port must be an integer.")
        if target_port < 1 or target_port > 65535:
            return _err("VALIDATION_ERROR", "target_port must be between 1 and 65535.")

    # Validate site exists and belongs to active account; must be active (dev server operates on active sites)
    site = next((s for s in sites if s.get("id") == site_id), None)
    if not site:
        ev = {
            "id": _new_id("nlt_evt"),
            "account_id": active["id"],
            "site_id": site_id,
            "deploy_id": None,
            "event_type": "dev_server_session",
            "status": "failed",
            "request": _sanitize({"tool": "start-dev-server", "site_id": site_id, "repo_root": repo_root, "command": command, "port": port, "target_port": target_port}),
            "response": None,
            "http_method": None,
            "http_path": None,
            "http_status_code": None,
            "error_message": "Site not found.",
            "started_at": _now(),
            "ended_at": _now(),
            "created_at": _now(),
            "updated_at": _now(),
        }
        events.append(ev)
        _save("observability_events.json", events)
        return _err("NOT_FOUND", "Site not found.")
    if site.get("account_id") != active.get("id"):
        ev = {
            "id": _new_id("nlt_evt"),
            "account_id": active["id"],
            "site_id": site_id,
            "deploy_id": None,
            "event_type": "dev_server_session",
            "status": "failed",
            "request": _sanitize({"tool": "start-dev-server", "site_id": site_id, "repo_root": repo_root, "command": command, "port": port, "target_port": target_port}),
            "response": None,
            "http_method": None,
            "http_path": None,
            "http_status_code": None,
            "error_message": "Unauthorized for site.",
            "started_at": _now(),
            "ended_at": _now(),
            "created_at": _now(),
            "updated_at": _now(),
        }
        events.append(ev)
        _save("observability_events.json", events)
        return _err("UNAUTHORIZED", "Active account does not own this site.")
    if site.get("status") != "active":
        ev = {
            "id": _new_id("nlt_evt"),
            "account_id": active["id"],
            "site_id": site_id,
            "deploy_id": None,
            "event_type": "dev_server_session",
            "status": "failed",
            "request": _sanitize({"tool": "start-dev-server", "site_id": site_id, "repo_root": repo_root, "command": command, "port": port, "target_port": target_port}),
            "response": None,
            "http_method": None,
            "http_path": None,
            "http_status_code": None,
            "error_message": "Site is not active.",
            "started_at": _now(),
            "ended_at": _now(),
            "created_at": _now(),
            "updated_at": _now(),
        }
        events.append(ev)
        _save("observability_events.json", events)
        return _err("CONFLICT", "Operation allowed only for active sites.", site_status=site.get("status"))

    # Reuse an existing running dev server session for this account+site if present and compatible
    # (Best-effort: match repo_root, and if ports provided must match; otherwise return existing.)
    existing = None
    for e in reversed(events):
        if e.get("event_type") != "dev_server_session":
            continue
        if e.get("account_id") != active.get("id"):
            continue
        if e.get("site_id") != site_id:
            continue
        if e.get("status") != "running":
            continue
        req = e.get("request") if isinstance(e.get("request"), dict) else {}
        if req.get("repo_root") != repo_root:
            continue
        # if caller specifies port/target_port/command, require same to reuse
        if port is not None and req.get("port") != port:
            continue
        if target_port is not None and req.get("target_port") != target_port:
            continue
        if command is not None and req.get("command") != command:
            continue
        existing = e
        break

    if existing:
        resp = existing.get("response") if isinstance(existing.get("response"), dict) else None
        if not resp:
            # If corrupted, treat as not found and create new session (no success without effect)
            existing = None
        else:
            # Audit this call as api_call_audit as well (reads/ops are tracked)
            audit = {
                "id": _new_id("nlt_evt"),
                "account_id": active["id"],
                "site_id": site_id,
                "deploy_id": None,
                "event_type": "api_call_audit",
                "status": "completed",
                "request": _sanitize({"tool": "start-dev-server", "mode": "reuse", "site_id": site_id, "repo_root": repo_root, "command": command, "port": port, "target_port": target_port}),
                "response": _sanitize({"reused_session_id": existing.get("id"), "url": resp.get("url"), "port": resp.get("port")}),
                "http_method": "POST",
                "http_path": "/dev-server/start",
                "http_status_code": 200,
                "error_message": None,
                "started_at": _now(),
                "ended_at": _now(),
                "created_at": _now(),
                "updated_at": _now(),
            }
            events.append(audit)
            _save("observability_events.json", events)

            latency_ms = int((time.time() - started) * 1000)
            out = dict(resp)
            out["reused"] = True
            out["session_event_id"] = existing.get("id")
            return {"dev_server": out, "meta": {"latency_ms": latency_ms}}

    # Create a new running session event
    chosen_port = port if port is not None else random.randint(10240, 49151)
    url = f"http://127.0.0.1:{chosen_port}"
    session_id = _new_id("nlt_dev")
    resp = {
        "session_id": session_id,
        "session_event_id": None,  # filled after event id known
        "site_id": site_id,
        "repo_root": repo_root,
        "command": command,
        "port": chosen_port,
        "target_port": target_port,
        "url": url,
        "status": "running",
        "started_at": _now(),
    }

    ev = {
        "id": _new_id("nlt_evt"),
        "account_id": active["id"],
        "site_id": site_id,
        "deploy_id": None,
        "event_type": "dev_server_session",
        "status": "running",
        "request": _sanitize({"tool": "start-dev-server", "site_id": site_id, "repo_root": repo_root, "command": command, "port": chosen_port, "target_port": target_port}),
        "response": _sanitize(resp),
        "http_method": None,
        "http_path": None,
        "http_status_code": None,
        "error_message": None,
        "started_at": resp["started_at"],
        "ended_at": None,
        "created_at": _now(),
        "updated_at": _now(),
    }
    resp["session_event_id"] = ev["id"]
    ev["response"] = _sanitize(resp)
    events.append(ev)

    # Also record an api_call_audit for this tool execution (observable service dynamics)
    audit = {
        "id": _new_id("nlt_evt"),
        "account_id": active["id"],
        "site_id": site_id,
        "deploy_id": None,
        "event_type": "api_call_audit",
        "status": "completed",
        "request": _sanitize({"tool": "start-dev-server", "mode": "start", "site_id": site_id, "repo_root": repo_root, "command": command, "port": chosen_port, "target_port": target_port}),
        "response": _sanitize({"session_event_id": ev["id"], "url": url, "port": chosen_port}),
        "http_method": "POST",
        "http_path": "/dev-server/start",
        "http_status_code": 200,
        "error_message": None,
        "started_at": _now(),
        "ended_at": _now(),
        "created_at": _now(),
        "updated_at": _now(),
    }
    events.append(audit)

    _save("observability_events.json", events)

    latency_ms = int((time.time() - started) * 1000)
    out = dict(resp)
    out["reused"] = False
    return {"dev_server": out, "meta": {"latency_ms": latency_ms}}

def serve_built_site(site_id, publish_dir, port=None, **_extra):
    import json, os, datetime, re, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0414000" if __import__("os").path.isdir("./environment_mix/0414000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(datetime.datetime.utcnow().timestamp() * 1000)
        r = random.getrandbits(80)
        s = ""
        v = (ts << 80) | r
        for _ in range(26):
            s = alphabet[v & 31] + s
            v >>= 5
        return f"{prefix}_{s}"

    def _audit(events, account_id, status, request_obj, response_obj=None, error_message=None):
        latency_ms = int((time.time() - t0) * 1000)
        ev = {
            "id": _new_id("nlt_evt"),
            "account_id": account_id,
            "site_id": request_obj.get("site_id"),
            "deploy_id": None,
            "event_type": "serve_session",
            "status": status,
            "request": request_obj,
            "response": response_obj,
            "http_method": None,
            "http_path": None,
            "http_status_code": None,
            "error_message": error_message,
            "started_at": now if status in ("running", "completed", "failed", "canceled") else None,
            "ended_at": now if status in ("completed", "failed", "canceled") else None,
            "created_at": now,
            "updated_at": now,
        }
        if ev["status"] == "running" and ev["started_at"] is None:
            ev["started_at"] = now
        events.append(ev)
        return ev, latency_ms

    # Validate inputs
    if not isinstance(site_id, str) or not re.match(r"^nlt_site_[0-9A-HJKMNP-TV-Z]{10,}$", site_id):
        return _err("VALIDATION_ERROR", "site_id is required and must match ^nlt_site_[0-9A-HJKMNP-TV-Z]{10,}$")
    if not isinstance(publish_dir, str) or not publish_dir.strip():
        return _err("VALIDATION_ERROR", "publish_dir is required and must be a non-empty string")
    if port is not None:
        if not isinstance(port, int):
            return _err("VALIDATION_ERROR", "port must be an integer when provided")
        if port < 1 or port > 65535:
            return _err("VALIDATION_ERROR", "port must be between 1 and 65535")

    accounts = _load("netlify_accounts.json")
    sites = _load("sites.json")
    events = _load("observability_events.json")

    active_accounts = [a for a in accounts if isinstance(a, dict) and a.get("is_active") is True and a.get("status") == "connected"]
    if not active_accounts:
        return _err("UNAUTHORIZED", "No active connected Netlify account available")
    account = active_accounts[0]
    account_id = account.get("id")

    one_min_ago = (datetime.datetime.utcnow() - datetime.timedelta(minutes=1)).replace(microsecond=0).isoformat() + "Z"
    recent = 0
    for ev in events:
        if not isinstance(ev, dict): 
            continue
        if ev.get("account_id") != account_id:
            continue
        if ev.get("status") not in ("running", "queued"):
            continue
        ts = ev.get("created_at") or ev.get("updated_at")
        if isinstance(ts, str) and ts >= one_min_ago:
            recent += 1
    if recent >= 60:
        req = {"site_id": site_id, "publish_dir": publish_dir, "port": port}
        ev, _ = _audit(events, account_id, "failed", req, error_message="Rate limit exceeded")
        _save("observability_events.json", events)
        return _err("RATE_LIMIT", "Rate limit exceeded", retry_after_seconds=60, event_id=ev["id"])

    site = None
    for s in sites:
        if isinstance(s, dict) and s.get("id") == site_id and s.get("account_id") == account_id:
            site = s
            break
    if not site:
        req = {"site_id": site_id, "publish_dir": publish_dir, "port": port}
        ev, _ = _audit(events, account_id, "failed", req, error_message="Site not found for active account")
        _save("observability_events.json", events)
        return _err("NOT_FOUND", "site_id not found for the active account", event_id=ev["id"])

    # Must have a local site link
    if site.get("is_linked") is not True or not site.get("local_repo_root"):
        req = {"site_id": site_id, "publish_dir": publish_dir, "port": port}
        ev, _ = _audit(events, account_id, "failed", req, error_message="Local site link does not exist")
        _save("observability_events.json", events)
        return _err("NOT_FOUND", "Local site link does not exist for site_id", event_id=ev["id"])

    # For serve, require site to be active
    if site.get("status") != "active":
        req = {"site_id": site_id, "publish_dir": publish_dir, "port": port}
        ev, _ = _audit(events, account_id, "failed", req, error_message="Site is not active")
        _save("observability_events.json", events)
        return _err("CONFLICT", "Site is not active", site_status=site.get("status"), event_id=ev["id"])

    # Conflict if already running serve session for this site
    running = None
    for ev in reversed(events):
        if not isinstance(ev, dict):
            continue
        if ev.get("event_type") == "serve_session" and ev.get("account_id") == account_id and ev.get("site_id") == site_id and ev.get("status") == "running":
            running = ev
            break
    if running:
        prev = running.get("response") or {}
        req = {"site_id": site_id, "publish_dir": publish_dir, "port": port}
        ev2, _ = _audit(events, account_id, "failed", req, error_message="Serve session already running for this site")
        _save("observability_events.json", events)
        return _err("CONFLICT", "A server is already running for this site", running_event_id=running.get("id"), running_port=(prev.get("port") if isinstance(prev, dict) else None), event_id=ev2["id"])

    def _port_in_use(p):
        if p is None:
            return False
        for ev in events:
            if not isinstance(ev, dict):
                continue
            if ev.get("status") != "running":
                continue
            if ev.get("event_type") not in ("dev_server_session", "serve_session"):
                continue
            resp = ev.get("response") or {}
            if isinstance(resp, dict) and resp.get("port") == p:
                return True
        return False

    chosen_port = port
    if chosen_port is None:
        for p in range(4000, 5000):
            if not _port_in_use(p):
                chosen_port = p
                break
        if chosen_port is None:
            req = {"site_id": site_id, "publish_dir": publish_dir, "port": port}
            ev, _ = _audit(events, account_id, "failed", req, error_message="No free port available in default range")
            _save("observability_events.json", events)
            return _err("CONFLICT", "No free port available to serve the site", event_id=ev["id"])
    else:
        if _port_in_use(chosen_port):
            req = {"site_id": site_id, "publish_dir": publish_dir, "port": port}
            ev, _ = _audit(events, account_id, "failed", req, error_message="Requested port is unavailable")
            _save("observability_events.json", events)
            return _err("CONFLICT", "Requested port is unavailable", port=chosen_port, event_id=ev["id"])

    session_id = _new_id("nlt_srv")
    local_url = f"http://localhost:{chosen_port}"

    req = {"site_id": site_id, "publish_dir": publish_dir, "port": port}
    resp = {
        "session_id": session_id,
        "site_id": site_id,
        "publish_dir": publish_dir,
        "port": chosen_port,
        "local_url": local_url,
    }
    ev, _ = _audit(events, account_id, "running", req, response_obj=resp)
    _save("observability_events.json", events)

    return {
        "server": resp,
        "event": {"id": ev["id"], "status": ev["status"], "started_at": ev["started_at"]},
        "site": {"id": site.get("id"), "name": site.get("name"), "netlify_site_id": site.get("netlify_site_id")},
    }

