        "http_status_code": None,
        "error_message": None,
        "started_at": now,
        "ended_at": None,
        "created_at": now,
        "updated_at": now,
    }
    events.append(run_event)
    _save("observability_events.json", events)

    actions = []
    outputs = {}

    def _finish(status, response_obj=None, error_message=None):
        # Update the run_event in-place
        for ev in events:
            if isinstance(ev, dict) and ev.get("id") == run_event["id"]:
                ev["status"] = status
                ev["response"] = response_obj
                ev["error_message"] = error_message
                ev["ended_at"] = now
                ev["updated_at"] = now
                break
        _save("observability_events.json", events)
        if status == "failed":
            return _err("CONFLICT" if error_message and "conflict" in error_message.lower() else "VALIDATION_ERROR", error_message or "Recipe run failed", event_id=run_event["id"])
        return {
            "run": {
                "event_id": run_event["id"],
                "recipe_id": recipe_id,
                "status": status,
                "started_at": run_event["started_at"],
                "ended_at": now,
                "actions": actions,
                "outputs": outputs,
            }
        }

    # Execute recipe behaviors (offline, via datastore mutations)
    inputs = inputs or {}

    if recipe_id == "recipe.site.open":
        if not site:
            return _finish("failed", None, "conflict: recipe.site.open requires site_id")
        url = None
        if site.get("netlify_site_id"):
            url = f"https://app.netlify.com/sites/{site.get('name') or site.get('netlify_site_id')}"
        else:
            url = "https://app.netlify.com/"
        actions.append({"type": "open_site_action", "site_id": site_id, "url": url})
        outputs["url"] = url
        return _finish("completed", {"actions": actions, "outputs": outputs}, None)

    if recipe_id == "recipe.env.sync":
        if not site:
            return _finish("failed", None, "conflict: recipe.env.sync requires site_id")
        if site.get("status") != "active":
            return _finish("failed", None, "conflict: site is not active")
        # Simulate sync by ensuring a marker env var exists
        key = "NETLIFY_ENV_SYNCED"
        val = now
        # find existing active env var
        existing = None
        for kv in site_kv:
            if isinstance(kv, dict) and kv.get("site_id") == site_id and kv.get("namespace") == "env" and kv.get("key") == key and kv.get("status") == "active":
                existing = kv
                break
        if existing:
            existing["value_text"] = val
            existing["value_bytes"] = None
            existing["is_secret"] = False
            existing["updated_at"] = now
            actions.append({"type": "env_upsert", "key": key, "updated": True})
        else:
            kv_id = _new_id("nlt_kv")
            site_kv.append({
                "id": kv_id,
                "site_id": site_id,
                "namespace": "env",
                "key": key,
                "value_text": val,
                "value_bytes": None,
                "content_type": None,
                "is_secret": False,
                "etag": None,
                "status": "active",
                "deleted_at": None,
                "created_at": now,
                "updated_at": now,
            })
            actions.append({"type": "env_upsert", "key": key, "created": True})
        _save("site_kv.json", site_kv)
        outputs["synced"] = True
        outputs["marker_key"] = key
        return _finish("completed", {"actions": actions, "outputs": outputs}, None)

    if recipe_id == "recipe.deploy.trigger":
        if not site:
            return _finish("failed", None, "conflict: recipe.deploy.trigger requires site_id")
        if site.get("status") != "active":
            return _finish("failed", None, "conflict: site is not active")
        # create deploy record (queued)
        deploy_id = _new_id("nlt_deploy")
        netlify_deploy_id = _new_id("nf_deploy")
        deploy_row = {
            "id": deploy_id,
            "site_id": site_id,
            "netlify_deploy_id": netlify_deploy_id,
            "triggered_by": "recipe_run",
            "branch": inputs.get("branch") if isinstance(inputs.get("branch"), str) else None,
            "commit_ref": None,
            "deploy_url": None,
            "admin_url": None,
            "status": "queued",
            "is_production": bool(inputs.get("is_production")) if "is_production" in inputs else True,
            "started_at": None,
            "finished_at": None,
            "duration_seconds": None,
            "error_message": None,
            "metadata": {"recipe": recipe_id},
            "created_at": now,
            "updated_at": now,
        }
        # Ensure no new deploys on deleted/deleting
        if site.get("status") in ("deleted", "deleting"):
            return _finish("failed", None, "conflict: cannot create deploy for deleted/deleting site")
        deploys.append(deploy_row)
        _save("deploys.json", deploys)
        actions.append({"type": "deploy_create", "deploy_id": deploy_id, "status": "queued"})
        outputs["deploy_id"] = deploy_id
        return _finish("completed", {"actions": actions, "outputs": outputs}, None)

    if recipe_id in ("recipe.branch_deploy.enable", "recipe.branch_deploy.disable"):
        if not site:
            return _finish("failed", None, f"conflict: {recipe_id} requires site_id")
        if site.get("status") != "active":
            return _finish("failed", None, "conflict: site is not active")
        branch = inputs.get("branch")
        if not isinstance(branch, str) or not branch.strip():
            return _finish("failed", None, "branch input is required and must be a non-empty string")
        branch = branch.strip()
        bd = site.get("branch_deploys")
        if not isinstance(bd, dict):
            bd = {}
            site["branch_deploys"] = bd
        enabled = (recipe_id == "recipe.branch_deploy.enable")
        prev = bd.get(branch) if isinstance(bd.get(branch), dict) else {}
        bd[branch] = {
            "enabled": enabled,
            "updated_at": now,
            "source": "recipe_run",
            "previous": prev.get("enabled") if isinstance(prev, dict) else None,
        }
        site["updated_at"] = now
        _save("sites.json", sites)
        actions.append({"type": "branch_deploy_set", "branch": branch, "enabled": enabled})
        outputs["branch"] = branch
        outputs["enabled"] = enabled
        return _finish("completed", {"actions": actions, "outputs": outputs}, None)

    # Should never reach here due to registry check
    return _finish("failed", None, "Recipe not implemented")

def invoke_function_advanced(site_id, function_name, method=None, path=None, query=None, headers=None, body_text=None, body_base64=None, content_type=None, timeout_ms=None, record_event=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0414000" if __import__("os").path.isdir("./environment_mix/0414000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    _B32_ALPH = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"

    def _new_id(prefix):
        import random
        ts = int(time.time() * 1000)
        buf = []
        for _ in range(10):
            buf.append(_B32_ALPH[ts & 31])
            ts >>= 5
        rnd = random.getrandbits(80)
        for _ in range(16):
            buf.append(_B32_ALPH[rnd & 31])
            rnd >>= 5
        return prefix + "".join(reversed(buf))

    def _sanitize(obj):
        try:
            s = json.dumps(obj)
            o = json.loads(s)
        except Exception:
            return {"_sanitized": True, "note": "non-serializable payload omitted"}
        def _walk(x):
            if isinstance(x, dict):
                y = {}
                for k, v in x.items():
                    lk = str(k).lower()
                    if "token" in lk or "authorization" in lk or "cipher" in lk or "secret" in lk:
                        y[k] = "[REDACTED]"
                    else:
                        y[k] = _walk(v)
                return y
            if isinstance(x, list):
                return [_walk(v) for v in x]
            return x
        return _walk(o)

    t0 = time.time()
    accounts = _load("netlify_accounts.json")
    sites = _load("sites.json")
    events = _load("observability_events.json")

    active_accounts = [a for a in accounts if isinstance(a, dict) and a.get("is_active") is True and a.get("status") in ("connected", "error")]
    if not active_accounts:
        # optionally record failed event if requested (but no account_id exists); always refuse
        if record_event:
            evt = {
                "id": _new_id("nlt_evt_"),
                "account_id": "unknown",
                "site_id": site_id if isinstance(site_id, str) else None,
                "deploy_id": None,
                "event_type": "function_invoke",
                "status": "failed",
                "request": _sanitize({"site_id": site_id, "function_name": function_name, "method": method, "path": path, "query": query, "headers": headers, "timeout_ms": timeout_ms}),
                "response": None,
                "http_method": None,
                "http_path": None,
                "http_status_code": None,
                "error_message": "No active Netlify account connection.",
                "started_at": _now(),
                "ended_at": _now(),
                "created_at": _now(),
                "updated_at": _now(),
            }
            events.append(evt)
            _save("observability_events.json", events)
        return _err("UNAUTHORIZED", "No active Netlify account connection.")

    account = active_accounts[0]

    # Rate limit check (same as other tools)
    now_dt = datetime.datetime.utcnow()
    window_start = now_dt - datetime.timedelta(seconds=60)
    active_count = 0
    for e in events:
        if not isinstance(e, dict):
            continue
        if e.get("account_id") != account.get("id"):
            continue
        if e.get("status") not in ("queued", "running"):
            continue
        ts = e.get("created_at") or e.get("started_at")
        if isinstance(ts, str):
            try:
                ts2 = ts.replace("Z", "+00:00")
                dt = datetime.datetime.fromisoformat(ts2).astimezone(datetime.timezone.utc).replace(tzinfo=None)
            except Exception:
                dt = None
            if dt and dt >= window_start:
                active_count += 1
    if active_count >= 60:
        if record_event:
            evt = {
                "id": _new_id("nlt_evt_"),
                "account_id": account.get("id"),
                "site_id": site_id if isinstance(site_id, str) else None,
                "deploy_id": None,
                "event_type": "function_invoke",
                "status": "failed",
                "request": _sanitize({"site_id": site_id, "function_name": function_name, "method": method, "path": path, "query": query, "headers": headers, "timeout_ms": timeout_ms}),
                "response": None,
                "http_method": None,
                "http_path": None,
                "http_status_code": 429,
                "error_message": "Rate limit exceeded.",
                "started_at": _now(),
                "ended_at": _now(),
                "created_at": _now(),
                "updated_at": _now(),
            }
            events.append(evt)
            _save("observability_events.json", events)
        return _err("RATE_LIMIT", "Rate limit exceeded.", retry_after=60)

    # Validate inputs
    if not isinstance(site_id, str) or not re.match(r"^nlt_site_[0-9A-HJKMNP-TV-Z]{10,}$", site_id):
        return _err("VALIDATION_ERROR", "site_id is missing or invalid.", field="site_id")

    if not isinstance(function_name, str) or not function_name.strip():
        return _err("VALIDATION_ERROR", "function_name is missing or invalid.", field="function_name")

    if method is not None and method not in ("GET", "POST", "PUT", "PATCH", "DELETE"):
        return _err("VALIDATION_ERROR", "Invalid method.", field="method", allowed=["GET", "POST", "PUT", "PATCH", "DELETE"])

    if timeout_ms is not None:
        if not isinstance(timeout_ms, int) or timeout_ms < 1:
            return _err("VALIDATION_ERROR", "timeout_ms must be an integer >= 1.", field="timeout_ms")

    if body_text is not None and body_base64 is not None:
        return _err("VALIDATION_ERROR", "Provide only one of body_text or body_base64.", fields=["body_text", "body_base64"])

    if path is not None and not isinstance(path, str):
        return _err("VALIDATION_ERROR", "path must be a string.", field="path")

    if content_type is not None and not isinstance(content_type, str):
        return _err("VALIDATION_ERROR", "content_type must be a string.", field="content_type")

    if record_event is not None and not isinstance(record_event, bool):
        return _err("VALIDATION_ERROR", "record_event must be a boolean.", field="record_event")

    if query is not None:
        if not isinstance(query, dict):
            return _err("VALIDATION_ERROR", "query must be an object of string values.", field="query")
        for k, v in query.items():
            if not isinstance(k, str) or not isinstance(v, str):
                return _err("VALIDATION_ERROR", "query must be an object of string values.", field="query")

    if headers is not None:
        if not isinstance(headers, dict):
            return _err("VALIDATION_ERROR", "headers must be an object of string values.", field="headers")
        for k, v in headers.items():
            if not isinstance(k, str) or not isinstance(v, str):
                return _err("VALIDATION_ERROR", "headers must be an object of string values.", field="headers")

    # Resolve site under active account; must be active for invocation
    site = next((s for s in sites if isinstance(s, dict) and s.get("id") == site_id and s.get("account_id") == account.get("id")), None)
    if not site:
        return _err("NOT_FOUND", "site_id does not exist.", field="site_id")

    if site.get("status") != "active":
        return _err("CONFLICT", "Site must be active to invoke functions.", site_status=site.get("status"))

    if not site.get("is_linked") or not site.get("local_repo_root"):
        return _err("CONFLICT", "Site must be linked locally (local_repo_root) to invoke functions.", field="site_id")

    # Prepare request for event record
    req_for_event = {
        "site_id": site_id,
        "function_name": function_name.strip(),
        "method": method or "GET",
        "path": path or "",
        "query": query or {},
        "headers": headers or {},
        "has_body": body_text is not None or body_base64 is not None,
        "content_type": content_type,
        "timeout_ms": timeout_ms,
    }

    evt_id = None
    if record_event:
        started = _now()
        evt_id = _new_id("nlt_evt_")
        evt = {
            "id": evt_id,
            "account_id": account.get("id"),
            "site_id": site_id,
            "deploy_id": None,
            "event_type": "function_invoke",
            "status": "running",
            "request": _sanitize(req_for_event),
            "response": None,
            "http_method": None,
            "http_path": None,
            "http_status_code": None,
            "error_message": None,
            "started_at": started,
            "ended_at": None,
            "created_at": started,
            "updated_at": started,
        }
        events.append(evt)
        _save("observability_events.json", events)

    # Offline invocation simulation: deterministic response based on request
    used_method = method or "GET"
    used_path = path or ""
    q = query or {}
    hdrs = headers or {}

    # decode body if base64
    raw_body = b""
    body_repr = None
    if body_text is not None:
        if not isinstance(body_text, str):
            if record_event:
                ended = _now()
                for e in events:
                    if isinstance(e, dict) and e.get("id") == evt_id:
                        e["status"] = "failed"
                        e["error_message"] = "body_text must be a string."
                        e["ended_at"] = ended
                        e["updated_at"] = ended
                        break
                _save("observability_events.json", events)
            return _err("VALIDATION_ERROR", "body_text must be a string.", field="body_text")
        raw_body = body_text.encode("utf-8", "ignore")
        body_repr = body_text
    elif body_base64 is not None:
        if not isinstance(body_base64, str):
            if record_event:
                ended = _now()
                for e in events:
                    if isinstance(e, dict) and e.get("id") == evt_id:
                        e["status"] = "failed"
                        e["error_message"] = "body_base64 must be a string."
                        e["ended_at"] = ended
                        e["updated_at"] = ended
                        break
                _save("observability_events.json", events)
            return _err("VALIDATION_ERROR", "body_base64 must be a string.", field="body_base64")
        try:
            raw_body = base64.b64decode(body_base64.encode("ascii"), validate=True)
        except Exception:
            if record_event:
                ended = _now()
                for e in events:
                    if isinstance(e, dict) and e.get("id") == evt_id:
                        e["status"] = "failed"
                        e["error_message"] = "body_base64 is not valid base64."
                        e["ended_at"] = ended
                        e["updated_at"] = ended
                        break
                _save("observability_events.json", events)
            return _err("VALIDATION_ERROR", "body_base64 is not valid base64.", field="body_base64")
        body_repr = f"[base64:{len(raw_body)} bytes]"

    # Deterministic status: 500 on certain hashes to mimic runtime errors
    seed = json.dumps(
        {
            "site_id": site_id,
            "fn": function_name.strip(),
            "m": used_method,
            "p": used_path,
            "q": q,
            "h": {k.lower(): v for k, v in hdrs.items()},
            "b": hashlib.sha256(raw_body).hexdigest() if raw_body else "",
        },
        sort_keys=True,
    ).encode("utf-8")
    hx = hashlib.sha256(seed).hexdigest()
    fail = (int(hx[-2:], 16) % 29 == 0)

    resp_headers = {
        "content-type": "application/json; charset=utf-8",
        "x-netlify-mcp-simulated": "true",
        "x-function-name": function_name.strip(),
    }
    status_code = 500 if fail else 200

    # Produce JSON body; include echo and derived info, avoid secrets
    body_obj = {
        "function": function_name.strip(),
        "site": {"id": site_id, "name": site.get("name")},
        "request": {
            "method": used_method,
            "path": used_path,
            "query": q,
            "content_type": content_type,
            "body": body_repr if body_repr is not None else None,
        },
        "result": "error" if fail else "ok",
    }
    body_json = json.dumps(body_obj, ensure_ascii=False)

    result = {
        "site_id": site_id,
        "function_name": function_name.strip(),
        "event_id": evt_id,
        "response": {
            "status": status_code,
            "headers": resp_headers,
            "body_text": body_json,
            "body_base64": None,
        },
        "latency_ms": int((time.time() - t0) * 1000),
    }

    if record_event:
        ended = _now()
        for e in events:
            if isinstance(e, dict) and e.get("id") == evt_id:
                if fail:
                    e["status"] = "failed"
                    e["error_message"] = "Function invocation failed."
                else:
                    e["status"] = "completed"
                e["response"] = _sanitize(
                    {
                        "http_status": status_code,
                        "headers": resp_headers,
                        "body_preview": body_json[:4096],
                    }
                )
                e["ended_at"] = ended
                e["updated_at"] = ended
                break
        _save("observability_events.json", events)

    return {"invocation": result}

def init_site(account_id, name, repo_url=None, repo_branch=None, build_command=None, publish_dir=None, custom_domain=None, local_repo_root=None, branch_deploys=None, env=None, env_secrets=None, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0414000" if __import__("os").path.isdir("./environment_mix/0414000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _is_jsonable(v):
        try:
            json.dumps(v, ensure_ascii=False)
            return True
        except TypeError:
            return False

    _B32 = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _ulid_like(prefix):
        # Not a real ULID; stable enough for local datastore uniqueness.
        ts = int(time.time() * 1000)
        def _enc(n, l):
            s = ""
            for _ in range(l):
                s = _B32[n % 32] + s
                n //= 32
            return s
        rnd = uuid.uuid4().int >> 2
        return f"{prefix}{_enc(ts, 10)}{_enc(rnd, 16)}"

    def _record_event(events, account_row_id, status, request_obj=None, response_obj=None, site_id=None, error_message=None):
        now = _now()
        ev = {
            "id": _ulid_like("nlt_evt_"),
            "account_id": account_row_id,
            "site_id": site_id,
            "deploy_id": None,
            "event_type": "api_call_audit",
            "status": status,
            "request": request_obj if request_obj is None or _is_jsonable(request_obj) else {"_nonserializable": True},
            "response": response_obj if response_obj is None or _is_jsonable(response_obj) else {"_nonserializable": True},
            "http_method": "POST",
            "http_path": "/mcp/init-site",
            "http_status_code": 200 if status == "completed" else 400,
            "error_message": error_message,
            "started_at": None,
            "ended_at": now if status in ("completed", "failed", "canceled") else None,
            "created_at": now,
            "updated_at": now,
        }
        events.append(ev)
        return ev["id"]

    def _active_account_for_request(requested_account_id):
        accounts = _load("netlify_accounts.json")
        # Must be explicitly under specified local account_id and must be connected.
        acct = next((a for a in accounts if a.get("id") == requested_account_id), None)
        if not acct:
            return None, accounts
        if acct.get("status") != "connected":
            return "not_connected", accounts
        return acct, accounts

    def _rate_limit_check(events, account_row_id):
        # At most 60 tool executions per minute in status running/queued across observability_events and deploy creation.
        # This tool creates no deploys; enforce by counting queued/running in last 60s plus this attempt.
        now = datetime.datetime.utcnow()
        window_start = now - datetime.timedelta(seconds=60)

        def _parse(ts):
            if not ts:
                return None
            try:
                if ts.endswith("Z"):
                    ts = ts[:-1]
                return datetime.datetime.fromisoformat(ts)
            except Exception:
                return None

        cnt = 0
        for e in events:
            if e.get("account_id") != account_row_id:
                continue
            if e.get("status") not in ("queued", "running"):
                continue
            t = _parse(e.get("created_at")) or _parse(e.get("updated_at"))
            if t and t >= window_start:
                cnt += 1
        if cnt >= 60:
            retry_after = 60
            return _err("RATE_LIMIT", "Rate limit exceeded (60 requests/minute).", retry_after=retry_after)
        return None

    # ---- Validate inputs (do not mutate yet) ----
    if not isinstance(account_id, str) or not re.match(r"^nlt_acct_[0-9A-HJKMNP-TV-Z]{10,}$", account_id):
        return _err("VALIDATION_ERROR", "account_id is invalid.", field="account_id")
    if not isinstance(name, str) or not name.strip():
        return _err("VALIDATION_ERROR", "name is invalid.", field="name")
    for fld, val in (("repo_url", repo_url), ("repo_branch", repo_branch), ("build_command", build_command),
                     ("publish_dir", publish_dir), ("custom_domain", custom_domain), ("local_repo_root", local_repo_root)):
        if val is not None and not isinstance(val, str):
            return _err("VALIDATION_ERROR", f"{fld} must be a string.", field=fld)
    if branch_deploys is not None and not isinstance(branch_deploys, dict):
        return _err("VALIDATION_ERROR", "branch_deploys must be an object.", field="branch_deploys")

    if env is not None:
        if not isinstance(env, dict):
            return _err("VALIDATION_ERROR", "env must be an object mapping strings to strings.", field="env")
        for k, v in env.items():
            if not isinstance(k, str) or not isinstance(v, str):
                return _err("VALIDATION_ERROR", "env must be a string map.", field="env")
    if env_secrets is not None:
        if not isinstance(env_secrets, list) or any(not isinstance(x, str) for x in env_secrets):
            return _err("VALIDATION_ERROR", "env_secrets must be an array of strings.", field="env_secrets")
        if env is None:
            return _err("VALIDATION_ERROR", "env_secrets provided but env is missing.", field="env_secrets")
        missing = [k for k in env_secrets if k not in env]
        if missing:
            return _err("VALIDATION_ERROR", "env_secrets contains keys not present in env.", missing_keys=missing, field="env_secrets")

    # ---- Auth context (ambient, but tool requires specified account_id to be usable) ----
    acct, accounts = _active_account_for_request(account_id)
    if acct is None:
        # As per contract: UNAUTHORIZED only if no combination can serve call. Here user explicitly requests account.
        return _err("NOT_FOUND", "Account not found.", account_id=account_id)
    if acct == "not_connected":
        return _err("UNAUTHORIZED", "Account is not connected/authorized for this operation.", account_id=account_id)

    # Ensure global invariant at_most_one(is_active=true) remains true: init-site does not change it, but request must run
    # under exactly one active account row. If the store is inconsistent, choose the requested account only if it's active,
    # otherwise refuse with UNAUTHORIZED.
    active_accounts = [a for a in accounts if a.get("is_active") is True and a.get("status") == "connected"]
    if len(active_accounts) != 1 or active_accounts[0].get("id") != account_id:
        # Try to find a working combination that satisfies "execute under exactly one active row" *and* requested account_id.
        # Only possible if requested account is the single active connected account.
        return _err("UNAUTHORIZED", "No active authenticated account context matches requested account_id.", account_id=account_id)

    # ---- Load other collections ----
    events = _load("observability_events.json")
    rate_err = _rate_limit_check(events, account_id)
    if rate_err:
        # Record failed event due to rate limit
        _record_event(events, account_id, "failed", request_obj={"account_id": account_id, "name": name}, response_obj=None, error_message=rate_err["error"]["message"])
        _save("observability_events.json", events)
        return rate_err

    sites = _load("sites.json")
    kv = _load("site_kv.json")

    # Unique constraints for sites: unique(account_id, name) and unique(account_id, netlify_site_id)
    for s in sites:
        if s.get("account_id") == account_id and s.get("name") == name and s.get("status") != "deleted":
            _record_event(events, account_id, "failed", request_obj={"account_id": account_id, "name": name}, response_obj=None, error_message="Site name already exists for this account.")
            _save("observability_events.json", events)
            return _err("CONFLICT", "A site with this name already exists for the account.", field="name")

    # link-site constraint: local_repo_root unique when not null
    if local_repo_root is not None:
        for s in sites:
            if s.get("local_repo_root") and s.get("local_repo_root") == local_repo_root and s.get("status") != "deleted":
                _record_event(events, account_id, "failed", request_obj={"account_id": account_id, "name": name, "local_repo_root": local_repo_root}, response_obj=None, error_message="local_repo_root already linked to another site.")
                _save("observability_events.json", events)
                return _err("CONFLICT", "local_repo_root is already linked to another site.", field="local_repo_root")

    # ---- Create site row (active + linked) ----
    now = _now()
    site_id = _ulid_like("nlt_site_")
    netlify_site_id = _ulid_like("netlify_site_")  # local placeholder for Netlify-side id

    # Derive default domain (best-effort)
    slug = name.strip()
    default_domain = f"{slug}.netlify.app" if slug else None

    bd = branch_deploys if branch_deploys is not None else {}
    if not isinstance(bd, dict):
        bd = {}

    site_row = {
        "id": site_id,
        "account_id": account_id,
        "netlify_site_id": netlify_site_id,
        "name": slug,
        "custom_domain": custom_domain,
        "default_domain": default_domain,
        "repo_url": repo_url,
        "repo_branch": repo_branch,
        "build_command": build_command,
        "publish_dir": publish_dir,
        "local_repo_root": local_repo_root,
        "is_linked": True if local_repo_root is not None else False,
        "branch_deploys": bd,
        "status": "active",
        "deleted_at": None,
        "created_at": now,
        "updated_at": now,
    }

    # Constraint: is_linked = true implies local_repo_root not null
    if site_row["is_linked"] and not site_row["local_repo_root"]:
        _record_event(events, account_id, "failed", request_obj={"account_id": account_id, "name": name}, response_obj=None, error_message="is_linked implies local_repo_root.")
        _save("observability_events.json", events)
        return _err("VALIDATION_ERROR", "local_repo_root is required to link the site.", field="local_repo_root")

    # Persist site
    sites.append(site_row)

    # ---- Upsert env vars in site_kv (namespace='env') ----
    created_kv_ids = []
    if env:
        secret_set = set(env_secrets or [])
        env_key_re = re.compile(r"^[A-Z_][A-Z0-9_]*$")

        for k, v in env.items():
            if not env_key_re.match(k):
                _record_event(events, account_id, "failed", request_obj={"site_id": site_id, "env_key": k}, response_obj=None, error_message="Invalid env var key format.")
                _save("observability_events.json", events)
                return _err("VALIDATION_ERROR", "Invalid env var key format.", field="env", key=k)
            if len(k) < 1 or len(k) > 512:
                _record_event(events, account_id, "failed", request_obj={"site_id": site_id, "env_key": k}, response_obj=None, error_message="Env var key length out of bounds.")
                _save("observability_events.json", events)
                return _err("VALIDATION_ERROR", "Env var key length must be between 1 and 512.", field="env", key=k)
            if v is not None and not isinstance(v, str):
                _record_event(events, account_id, "failed", request_obj={"site_id": site_id, "env_key": k}, response_obj=None, error_message="Env var value must be string.")
                _save("observability_events.json", events)
                return _err("VALIDATION_ERROR", "Env var value must be a string.", field="env", key=k)
            if v is not None and len(v) > 65535:
                _record_event(events, account_id, "failed", request_obj={"site_id": site_id, "env_key": k}, response_obj=None, error_message="Env var value too large.")
                _save("observability_events.json", events)
                return _err("VALIDATION_ERROR", "Env var value too large (max 65535 chars).", field="env", key=k)

            # Find active existing env var for this site/key
            existing = None
            for row in kv:
                if row.get("site_id") == site_id and row.get("namespace") == "env" and row.get("key") == k and row.get("status") == "active":
                    existing = row
                    break

            if existing:
                existing["value_text"] = v
                existing["value_bytes"] = None
                existing["content_type"] = None
                existing["is_secret"] = True if k in secret_set else False
                existing["etag"] = None
                existing["updated_at"] = now
                # Ensure deleted_at cleared if it was inconsistent
                existing["deleted_at"] = None
                created_kv_ids.append(existing["id"])
            else:
                # Enforce unique(site_id, namespace, key) where status='active'
                # (site is new, so safe)
                kv_row = {
                    "id": _ulid_like("nlt_kv_"),
                    "site_id": site_id,
                    "namespace": "env",
                    "key": k,
                    "value_text": v,
                    "value_bytes": None,
                    "content_type": None,
                    "is_secret": True if k in secret_set else False,
                    "etag": None,
                    "status": "active",
                    "deleted_at": None,
                    "created_at": now,
                    "updated_at": now,
                }
                kv.append(kv_row)
                created_kv_ids.append(kv_row["id"])

    # ---- Record observability event and persist all ----
    req_obj = {
        "account_id": account_id,
        "name": name,
        "repo_url": repo_url,
        "repo_branch": repo_branch,
        "build_command": build_command,
        "publish_dir": publish_dir,
        "custom_domain": custom_domain,
        "local_repo_root": local_repo_root,
        "branch_deploys": branch_deploys if branch_deploys is not None else {},
        "env_keys": list(env.keys()) if isinstance(env, dict) else None,
        "env_secrets": env_secrets,
    }
    # Sanitized response: never include env values
    resp_obj = {
        "site_id": site_id,
        "netlify_site_id": netlify_site_id,
        "env_var_count": len(env) if isinstance(env, dict) else 0,
        "env_secret_keys": list(env_secrets or []),
    }
    _record_event(events, account_id, "completed", request_obj=req_obj, response_obj=resp_obj, site_id=site_id)

    _save("sites.json", sites)
    _save("site_kv.json", kv)
    _save("observability_events.json", events)

    return {
        "site": site_row,
        "env": {
            "set": [{"key": k, "is_secret": (k in set(env_secrets or []))} for k in (env.keys() if isinstance(env, dict) else [])],
            "note": "Values for secret env vars are redacted in read APIs.",
        },
    }

def open_site(site_id, target=None, deploy_id=None, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0414000" if __import__("os").path.isdir("./environment_mix/0414000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _is_jsonable(v):
        try:
            json.dumps(v, ensure_ascii=False)
            return True
        except TypeError:
            return False

    _B32 = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _ulid_like(prefix):
        ts = int(time.time() * 1000)
        def _enc(n, l):
            s = ""
            for _ in range(l):
                s = _B32[n % 32] + s
                n //= 32
            return s
        rnd = uuid.uuid4().int >> 2
        return f"{prefix}{_enc(ts, 10)}{_enc(rnd, 16)}"

    def _record_event(events, account_row_id, status, request_obj=None, response_obj=None, site_id_row=None, deploy_id_row=None, error_message=None, http_status_code=None):
        now = _now()
        ev = {
            "id": _ulid_like("nlt_evt_"),
            "account_id": account_row_id,
            "site_id": site_id_row,
            "deploy_id": deploy_id_row,
            "event_type": "open_site_action",
            "status": status,
            "request": request_obj if request_obj is None or _is_jsonable(request_obj) else {"_nonserializable": True},
            "response": response_obj if response_obj is None or _is_jsonable(response_obj) else {"_nonserializable": True},
            "http_method": None,
            "http_path": None,
            "http_status_code": http_status_code,
            "error_message": error_message,
            "started_at": _now() if status in ("running", "completed", "failed", "canceled") else None,
            "ended_at": _now() if status in ("completed", "failed", "canceled") else None,
            "created_at": now,
            "updated_at": now,
        }
        events.append(ev)
        return ev["id"]

    def _active_account(accounts):
        # Execute under exactly one active connected account
        active = [a for a in accounts if a.get("is_active") is True and a.get("status") == "connected"]
        if len(active) == 1:
            return active[0]
        return None

    def _rate_limit_check(events, account_row_id):
        now = datetime.datetime.utcnow()
        window_start = now - datetime.timedelta(seconds=60)

        def _parse(ts):
            if not ts:
                return None
            try:
                if ts.endswith("Z"):
                    ts = ts[:-1]
                return datetime.datetime.fromisoformat(ts)
            except Exception:
                return None

        cnt = 0
        for e in events:
            if e.get("account_id") != account_row_id:
                continue
            if e.get("status") not in ("queued", "running"):
                continue
            t = _parse(e.get("created_at")) or _parse(e.get("updated_at"))
            if t and t >= window_start:
                cnt += 1
        if cnt >= 60:
            return _err("RATE_LIMIT", "Rate limit exceeded (60 requests/minute).", retry_after=60)
        return None

    # ---- Validate inputs ----
    if not isinstance(site_id, str) or not re.match(r"^nlt_site_[0-9A-HJKMNP-TV-Z]{10,}$", site_id):
        return _err("VALIDATION_ERROR", "site_id is invalid.", field="site_id")
    if target is None:
        target = "default"
    if not isinstance(target, str) or target not in ("default", "admin", "deploy"):
        return _err("VALIDATION_ERROR", "target must be one of: default, admin, deploy.", field="target")

    if target == "deploy":
        if deploy_id is None:
            return _err("VALIDATION_ERROR", "deploy_id is required when target='deploy'.", field="deploy_id")
        if not isinstance(deploy_id, str) or not re.match(r"^nlt_dpl_[0-9A-HJKMNP-TV-Z]{10,}$", deploy_id):
            return _err("VALIDATION_ERROR", "deploy_id is invalid.", field="deploy_id")
    else:
        if deploy_id is not None and not isinstance(deploy_id, str):
            return _err("VALIDATION_ERROR", "deploy_id must be a string.", field="deploy_id")

    # ---- Resolve auth context (ambient) ----
    accounts = _load("netlify_accounts.json")
    acct = _active_account(accounts)
    if not acct:
        return _err("UNAUTHORIZED", "No active authenticated Netlify account is available.")

    events = _load("observability_events.json")
    rate_err = _rate_limit_check(events, acct["id"])
    if rate_err:
        _record_event(
            events,
            acct["id"],
            "failed",
            request_obj={"site_id": site_id, "target": target, "deploy_id": deploy_id},
            response_obj=None,
            site_id_row=site_id,
            deploy_id_row=deploy_id if target == "deploy" else None,
            error_message=rate_err["error"]["message"],
        )
        _save("observability_events.json", events)
        return rate_err

    sites = _load("sites.json")
    deploys = _load("deploys.json")

    site = next((s for s in sites if s.get("id") == site_id), None)
    if not site:
        _record_event(
            events,
            acct["id"],
            "failed",
            request_obj={"site_id": site_id, "target": target, "deploy_id": deploy_id},
            response_obj=None,
            site_id_row=site_id,
            deploy_id_row=deploy_id if target == "deploy" else None,
            error_message="Site not found.",
        )
        _save("observability_events.json", events)
        return _err("NOT_FOUND", "Site not found.", site_id=site_id)

    if site.get("account_id") != acct["id"]:
        _record_event(
            events,
            acct["id"],
            "failed",
            request_obj={"site_id": site_id, "target": target, "deploy_id": deploy_id},
            response_obj=None,
            site_id_row=site_id,
            deploy_id_row=deploy_id if target == "deploy" else None,
            error_message="Site does not belong to active account.",
        )
        _save("observability_events.json", events)
        return _err("UNAUTHORIZED", "Site does not belong to the active account.", site_id=site_id)

    if not site.get("is_linked"):
        _record_event(
            events,
            acct["id"],
            "failed",
            request_obj={"site_id": site_id, "target": target, "deploy_id": deploy_id},
            response_obj=None,
            site_id_row=site_id,
            deploy_id_row=deploy_id if target == "deploy" else None,
            error_message="Site is not linked.",
        )
        _save("observability_events.json", events)
        return _err("CONFLICT", "Site is not linked; cannot resolve open-site target URL.", site_id=site_id)

    # ---- Resolve URL ----
    resolved_url = None
    if target == "default":
        # Prefer custom_domain then default_domain
        if site.get("custom_domain"):
            resolved_url = "https://" + site["custom_domain"].lstrip()
        elif site.get("default_domain"):
            resolved_url = "https://" + site["default_domain"].lstrip()
        else:
            resolved_url = None
            _record_event(
                events,
                acct["id"],
                "failed",
                request_obj={"site_id": site_id, "target": target},
                response_obj=None,
                site_id_row=site_id,
                error_message="No default domain available for site.",
            )
            _save("observability_events.json", events)
            return _err("CONFLICT", "Site has no resolvable default URL.", site_id=site_id)

    elif target == "admin":
        # Best-effort admin URL based on netlify_site_id
        nsid = site.get("netlify_site_id")
        if not nsid:
            _record_event(
                events,
                acct["id"],
                "failed",
                request_obj={"site_id": site_id, "target": target},
                response_obj=None,
                site_id_row=site_id,
                error_message="Missing netlify_site_id.",
            )
            _save("observability_events.json", events)
            return _err("CONFLICT", "Site has no netlify_site_id to construct admin URL.", site_id=site_id)
        resolved_url = f"https://app.netlify.com/sites/{nsid}"

    else:  # deploy
        dpl = next((d for d in deploys if d.get("id") == deploy_id), None)
        if not dpl or dpl.get("site_id") != site_id:
            _record_event(
                events,
                acct["id"],
                "failed",
                request_obj={"site_id": site_id, "target": target, "deploy_id": deploy_id},
                response_obj=None,
                site_id_row=site_id,
                deploy_id_row=deploy_id,
                error_message="Deploy not found for site.",
            )
            _save("observability_events.json", events)
            return _err("NOT_FOUND", "Deploy not found for site.", site_id=site_id, deploy_id=deploy_id)

        # Prefer deploy_url, fall back to admin_url, finally derive from site default/custom
        if dpl.get("deploy_url"):
            resolved_url = dpl["deploy_url"]
        elif dpl.get("admin_url"):
            resolved_url = dpl["admin_url"]
        else:
            if site.get("custom_domain"):
                resolved_url = "https://" + site["custom_domain"].lstrip()
            elif site.get("default_domain"):
                resolved_url = "https://" + site["default_domain"].lstrip()
            else:
                resolved_url = None

        if not resolved_url:
            _record_event(
                events,
                acct["id"],
                "failed",
                request_obj={"site_id": site_id, "target": target, "deploy_id": deploy_id},
                response_obj=None,
                site_id_row=site_id,
                deploy_id_row=deploy_id,
                error_message="No URL available for deploy.",
            )
            _save("observability_events.json", events)
            return _err("CONFLICT", "Deploy has no resolvable URL.", site_id=site_id, deploy_id=deploy_id)

    # Record completed open action (we can't actually open a browser in offline server)
    _record_event(
        events,
        acct["id"],
        "completed",
        request_obj={"site_id": site_id, "target": target, "deploy_id": deploy_id},
        response_obj={"resolved_url": resolved_url},
        site_id_row=site_id,
        deploy_id_row=deploy_id if target == "deploy" else None,
    )
    _save("observability_events.json", events)

    return {
        "site_id": site_id,
        "target": target,
        "deploy_id": deploy_id if target == "deploy" else None,
        "resolved_url": resolved_url,
        "opened": True
    }

_DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0414000" if __import__("os").path.isdir("./environment_mix/0414000") else "/app/database")
def call_netlify_api(**_extra):
    import json, os
    _ds_path = os.path.join(_DB, "dataset.json")
    try:
        _ds = json.load(open(_ds_path, encoding="utf-8"))
    except Exception:
        _ds = {"records": []}
    _records = _ds.get("records", [])
    _verb = 'action'
    _kwargs = {k: v for k, v in locals().items() if k not in ("json", "os", "_ds_path", "_ds", "_records", "_verb", "_kwargs") and not k.startswith("_")}
    try:
        _kwargs.update({k: v for k, v in _extra.items() if v is not None})
    except Exception:
        pass
    _id_param = None
    _query_param = None
    if _verb in ("search", "list"):
        _out = list(_records)
        if _query_param and _kwargs.get(_query_param):
            _qq = str(_kwargs[_query_param]).lower()
            _f = [r for r in _records if _qq in json.dumps(r, default=str).lower()]
            _out = _f if _f else _records
        _limit = None
        for _lk in ("limit", "count", "numResults", "num_results", "page_size", "max_results", "top_k", "n", "k"):
            if _lk in _kwargs and isinstance(_kwargs.get(_lk), (int, float)):
                _limit = int(_kwargs[_lk]); break
        if _limit:
            _out = _out[:_limit]
        return {"results": _out, "count": len(_out), "query": _kwargs.get(_query_param) if _query_param else None}
    if _verb == "get":
        if _id_param and _kwargs.get(_id_param) is not None:
            _key = str(_kwargs[_id_param])
            for r in _records:
                if str(r.get("id")) == _key or _key in [str(v) for v in r.values()]:
                    return r
        return _records[0] if _records else {"error": "not found", "args": _kwargs}
    if _verb == "create":
        _new = {"id": "call_n_new_" + str(len(_records) + 1)}
        _new.update({k: v for k, v in _kwargs.items() if v is not None})
        return {"created": True, "record": _new}
    if _verb == "update":
        _base = dict(_records[0]) if _records else {}
        _base.update({k: v for k, v in _kwargs.items() if v is not None})
        return {"updated": True, "record": _base}
    if _verb == "delete":
        return {"deleted": True, "args": {k: v for k, v in _kwargs.items() if v is not None}}
    # generic action: acknowledge with a representative record
    return {"ok": True, "tool": 'call_netlify_api', "args": {k: v for k, v in _kwargs.items() if v is not None},
            "sample": _records[0] if _records else None}

def stream_logs(site_id, source, function_name=None, deploy_id=None, since=None, include_existing=None, max_duration_seconds=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0414000" if __import__("os").path.isdir("./environment_mix/0414000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now = now_dt.isoformat()

    _ULID_CHARS = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _new_id(prefix):
        import os as _os
        ms = int(time.time() * 1000)
        ts = ms
        out = []
        for _ in range(10):
            out.append(_ULID_CHARS[ts % 32])
            ts //= 32
        out = list(reversed(out))
        r = int.from_bytes(_os.urandom(10), "big")
        for _ in range(16):
            out.append(_ULID_CHARS[r % 32])
            r //= 32
        return f"{prefix}_{''.join(out)}"

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    def _pick_usable_account(accts):
        active = [a for a in accts if a.get("is_active") is True]
        candidates = active if active else accts
        for a in candidates:
            if a.get("status") in ("connected", "error") and isinstance(a.get("access_token_ciphertext"), str) and a.get("access_token_ciphertext").strip():
                return a
        return None

    def _rate_limit_check(events, acct_id):
        cutoff = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(seconds=60)
        cnt = 0
        for e in events:
            if e.get("account_id") != acct_id:
                continue
            if e.get("status") not in ("queued", "running"):
                continue
            ts = _parse_rfc3339(e.get("created_at") or "")
            if ts and ts >= cutoff:
                cnt += 1
        if cnt >= 60:
            return False, 10
        return True, None

    # validate inputs
    if not isinstance(site_id, str) or not re.match(r"^nlt_site_[0-9A-HJKMNP-TV-Z]{10,}$", site_id):
        return _err("VALIDATION_ERROR", "site_id must match ^nlt_site_[0-9A-HJKMNP-TV-Z]{10,}$.")
    if source not in ("site", "function"):
        return _err("VALIDATION_ERROR", "source must be 'site' or 'function'.")
    if source == "function":
        if function_name is None or not isinstance(function_name, str) or not function_name.strip():
            return _err("VALIDATION_ERROR", "function_name is required when source='function'.")
    if deploy_id is not None:
        if not isinstance(deploy_id, str) or not re.match(r"^nlt_dpl_[0-9A-HJKMNP-TV-Z]{10,}$", deploy_id):
            return _err("VALIDATION_ERROR", "deploy_id must match ^nlt_dpl_[0-9A-HJKMNP-TV-Z]{10,}$.")
    if since is not None:
        if _parse_rfc3339(since) is None:
            return _err("VALIDATION_ERROR", "since must be an ISO 8601/RFC3339 date-time string.")
    if include_existing is not None and not isinstance(include_existing, bool):
        return _err("VALIDATION_ERROR", "include_existing must be a boolean when provided.")
    if include_existing is None:
        include_existing = False
    if max_duration_seconds is None:
        max_duration_seconds = 30
    if not isinstance(max_duration_seconds, int) or max_duration_seconds < 1:
        return _err("VALIDATION_ERROR", "max_duration_seconds must be an integer >= 1.")

    accts = _load("netlify_accounts.json")
    sites = _load("sites.json")
    deploys = _load("deploys.json")
    events = _load("observability_events.json")

    acct = _pick_usable_account(accts)
    if acct is None:
        return _err("UNAUTHORIZED", "No active/usable account/session available.")

    # site must be active for log streaming and must be linked
    site = None
    for s in sites:
        if s.get("id") == site_id:
            site = s
            break
    if site is None:
        return _err("NOT_FOUND", "Site not found.")
    if site.get("account_id") != acct.get("id"):
        return _err("UNAUTHORIZED", "Site does not belong to the active account.")
    if site.get("status") != "active":
        return _err("INVALID_TRANSITION", "Logs can be streamed only for active sites.")
    if site.get("is_linked") is not True:
        return _err("VALIDATION_ERROR", "Site must be linked (is_linked=true) to stream logs.")

    if deploy_id is not None:
        dep = None
        for d in deploys:
            if d.get("id") == deploy_id:
                dep = d
                break
        if dep is None:
            return _err("NOT_FOUND", "deploy_id not found.")
        if dep.get("site_id") != site_id:
            return _err("VALIDATION_ERROR", "deploy_id does not belong to the given site_id.")

    ok_rl, retry_after = _rate_limit_check(events, acct.get("id"))
    if not ok_rl:
        return _err("RATE_LIMIT", "Too many requests for this account.", retry_after_seconds=retry_after)

    # create session event (running), then immediately complete with buffered lines (offline)
    evt_id = _new_id("nlt_evt")
    session = {
        "id": evt_id,
        "account_id": acct.get("id"),
        "site_id": site_id,
        "deploy_id": deploy_id,
        "event_type": "log_stream_session",
        "status": "running",
        "request": {
            "site_id": site_id,
            "source": source,
            "function_name": function_name if source == "function" else None,
            "deploy_id": deploy_id,
            "since": since,
            "include_existing": include_existing,
            "max_duration_seconds": max_duration_seconds,
        },
        "response": None,
        "http_method": None,
        "http_path": None,
        "http_status_code": None,
        "error_message": None,
        "started_at": now,
        "ended_at": None,
        "created_at": now,
        "updated_at": now,
    }
    events.append(session)
    _save("observability_events.json", events)

    # offline "stream": generate a short list of log lines (buffer + end marker)
    base_ts = _parse_rfc3339(since) if since else (now_dt - datetime.timedelta(seconds=5))
    if base_ts.tzinfo is None:
        base_ts = base_ts.replace(tzinfo=datetime.timezone.utc)

    lines = []
    if include_existing:
        for i in range(5):
            t = (base_ts + datetime.timedelta(milliseconds=250 * i)).isoformat()
            msg = f"[{site.get('name')}] buffered log line {i+1}"
            if source == "function":
                msg = f"[{site.get('name')}] function/{function_name}: buffered log line {i+1}"
            lines.append({"timestamp": t, "message": msg, "level": "info", "source": source})

    # simulated live lines
    for i in range(3):
        t = (now_dt + datetime.timedelta(milliseconds=200 * i)).isoformat()
        msg = f"[{site.get('name')}] live log line {i+1}"
        if source == "function":
            msg = f"[{site.get('name')}] function/{function_name}: live log line {i+1}"
        lines.append({"timestamp": t, "message": msg, "level": "info", "source": source})

    ended = datetime.datetime.now(datetime.timezone.utc).isoformat()
    # update session to completed
    for e in events:
        if e.get("id") == evt_id:
            e["status"] = "completed"
            e["ended_at"] = ended
            e["updated_at"] = ended
            e["response"] = {"lines": lines, "truncated": True, "note": "Offline simulation; no persistent streaming."}
            break
    _save("observability_events.json", events)

    latency_ms = int((time.time() - start) * 1000)
    return {
        "session_id": evt_id,
        "site_id": site_id,
        "account_id": acct.get("id"),
        "source": source,
        "function_name": function_name if source == "function" else None,
        "deploy_id": deploy_id,
        "lines": lines,
        "ended": True,
        "latency_ms": latency_ms,
    }

def switch_account(account_id, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0414000" if __import__("os").path.isdir("./environment_mix/0414000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()

    _ULID_CHARS = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _new_id(prefix):
        import os as _os
        ms = int(time.time() * 1000)
        ts = ms
        out = []
        for _ in range(10):
            out.append(_ULID_CHARS[ts % 32])
            ts //= 32
        out = list(reversed(out))
        r = int.from_bytes(_os.urandom(10), "big")
        for _ in range(16):
            out.append(_ULID_CHARS[r % 32])
            r //= 32
        return f"{prefix}_{''.join(out)}"

    def _parse_rfc3339(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    def _rate_limit_check(events, acct_id):
        cutoff = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(seconds=60)
        cnt = 0
        for e in events:
            if e.get("account_id") != acct_id:
                continue
            if e.get("status") not in ("queued", "running"):
                continue
            ts = _parse_rfc3339(e.get("created_at") or "")
            if ts and ts >= cutoff:
                cnt += 1
        if cnt >= 60:
            return False, 10
        return True, None

    # validate
    if not isinstance(account_id, str) or not re.match(r"^nlt_acct_[0-9A-HJKMNP-TV-Z]{10,}$", account_id):
        return _err("VALIDATION_ERROR", "account_id must match ^nlt_acct_[0-9A-HJKMNP-TV-Z]{10,}$.")

    accts = _load("netlify_accounts.json")
    events = _load("observability_events.json")

    target = None
    for a in accts:
        if a.get("id") == account_id:
            target = a
            break
    if target is None:
        return _err("NOT_FOUND", "Account not found.")

    # must have usable authentication configured
    if target.get("status") not in ("connected", "error") or not isinstance(target.get("access_token_ciphertext"), str) or not target.get("access_token_ciphertext").strip():
        return _err("UNAUTHORIZED", "Account exists but does not have usable authentication configured.")

    ok_rl, retry_after = _rate_limit_check(events, target.get("id"))
    if not ok_rl:
        return _err("RATE_LIMIT", "Too many requests for this account.", retry_after_seconds=retry_after)

    # atomic-ish: update all rows then save once
    changed = False
    for a in accts:
        if a.get("id") == account_id:
            if a.get("is_active") is not True:
                a["is_active"] = True
                a["updated_at"] = now
                changed = True
        else:
            if a.get("is_active") is True:
                a["is_active"] = False
                a["updated_at"] = now
                changed = True

    if not changed:
        # already active; still record event and return
        pass

    _save("netlify_accounts.json", accts)

    # record snapshot event (get_status_snapshot-style not requested; use api_call_audit? no; create an api_methods_snapshot? no)
    # We'll record an action audit as api_call_audit is specific; use get_status_snapshot? Not appropriate.
    # Use api_call_audit is invalid due to constraints. So record a generic open_site_action? also not.
    # Best fit: api_call_audit requires http_method/path. We'll instead record a get_status_snapshot event with request.
    evt = {
        "id": _new_id("nlt_evt"),
        "account_id": account_id,
        "site_id": None,
        "deploy_id": None,
        "event_type": "get_status_snapshot",
        "status": "completed",
        "request": {"action": "switch_account", "account_id": account_id},
        "response": {"active_account_id": account_id},
        "http_method": None,
        "http_path": None,
        "http_status_code": None,
        "error_message": None,
        "started_at": now,
        "ended_at": now,
        "created_at": now,
        "updated_at": now,
    }
    events.append(evt)
    _save("observability_events.json", events)

    latency_ms = int((time.time() - start) * 1000)
    # return updated selection
    active = None
    for a in accts:
        if a.get("is_active") is True:
            active = a
            break
    return {
        "active_account": {
            "id": active.get("id"),
            "netlify_account_id": active.get("netlify_account_id"),
            "display_name": active.get("display_name"),
            "auth_type": active.get("auth_type"),
            "token_scopes": active.get("token_scopes"),
            "status": active.get("status"),
            "last_verified_at": active.get("last_verified_at"),
            "created_at": active.get("created_at"),
            "updated_at": active.get("updated_at"),
        } if active else None,
        "event_id": evt["id"],
        "latency_ms": latency_ms,
    }

def watch_deploy(deploy_id=None, netlify_deploy_id=None, site_id=None, poll_interval_seconds=None, until_status=None, include_logs=None, since=None, timeout_seconds=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0414000" if __import__("os").path.isdir("./environment_mix/0414000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0)

    def _now_iso():
        return _now().isoformat() + "Z"

    def _new_id(prefix):
        ts = int(time.time() * 1000)
        rnd = os.urandom(10)
        b = ts.to_bytes(6, "big") + rnd
        s = base64.b32encode(b).decode("ascii").rstrip("=")
        s = s.replace("O", "8").replace("I", "9").replace("L", "7")
        return f"{prefix}_{s}"

    # Load stores
    accounts = _load("netlify_accounts.json")
    sites = _load("sites.json")
    deploys = _load("deploys.json")
    events = _load("observability_events.json")

    # Resolve ambient account (must be active and usable)
    acct = None
    for a in accounts:
        if a.get("is_active") and a.get("status") in ("connected", "error") and isinstance(a.get("access_token_ciphertext"), str) and a.get("access_token_ciphertext"):
            acct = a
            break
    if acct is None:
        for a in accounts:
            if a.get("status") in ("connected", "error") and isinstance(a.get("access_token_ciphertext"), str) and a.get("access_token_ciphertext"):
                acct = a
                break
    if acct is None:
        return _err("UNAUTHORIZED", "No active authorized Netlify account is available.")
    acct_id = acct.get("id")

    # Rate limit: 60/min queued/running events per account
    cutoff = (_now() - datetime.timedelta(seconds=60)).isoformat() + "Z"
    active_count = 0
    for e in events:
        if e.get("account_id") != acct_id:
            continue
        if e.get("status") not in ("queued", "running"):
            continue
        sa = e.get("started_at") or e.get("created_at")
        if isinstance(sa, str) and sa >= cutoff:
            active_count += 1
    if active_count >= 60:
        return _err("RATE_LIMIT", "Rate limit exceeded.", retry_after_seconds=60)

    # Validate params
    if deploy_id is None and netlify_deploy_id is None:
        return _err("VALIDATION_ERROR", "Either deploy_id or netlify_deploy_id is required.")
    if deploy_id is not None:
        if not isinstance(deploy_id, str) or not re.match(r"^nlt_dpl_[0-9A-Z]{10,}$", deploy_id):
            return _err("VALIDATION_ERROR", "deploy_id is invalid.", field="deploy_id")
    if netlify_deploy_id is not None:
        if not isinstance(netlify_deploy_id, str) or not netlify_deploy_id.strip():
            return _err("VALIDATION_ERROR", "netlify_deploy_id must be a non-empty string.", field="netlify_deploy_id")
    if site_id is not None:
        if not isinstance(site_id, str) or not re.match(r"^nlt_site_[0-9A-Z]{10,}$", site_id):
            return _err("VALIDATION_ERROR", "site_id is invalid.", field="site_id")

    if poll_interval_seconds is None:
        poll_interval_seconds = 2
    if not isinstance(poll_interval_seconds, int) or poll_interval_seconds < 1 or poll_interval_seconds > 60:
        return _err("VALIDATION_ERROR", "poll_interval_seconds must be an integer between 1 and 60.", field="poll_interval_seconds")

    if timeout_seconds is None:
        timeout_seconds = 60
    if not isinstance(timeout_seconds, int) or timeout_seconds < 1:
        return _err("VALIDATION_ERROR", "timeout_seconds must be an integer >= 1.", field="timeout_seconds")

    if until_status is None:
        until_status = ["ready", "failed", "canceled"]
    if not isinstance(until_status, list) or len(until_status) < 1 or any(s not in ("ready", "failed", "canceled") for s in until_status):
        return _err("VALIDATION_ERROR", "until_status must be a non-empty array of allowed terminal statuses.", field="until_status")

    if include_logs is not None and not isinstance(include_logs, bool):
        return _err("VALIDATION_ERROR", "include_logs must be boolean.", field="include_logs")
    include_logs = bool(include_logs)

    since_dt = None
    if since is not None:
        if not isinstance(since, str):
            return _err("VALIDATION_ERROR", "since must be an RFC3339 date-time string.", field="since")
        try:
            s = since
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            since_dt = datetime.datetime.fromisoformat(s)
        except Exception:
            return _err("VALIDATION_ERROR", "since must be an RFC3339 date-time string.", field="since")

    # Resolve deploy
    drow = None
    if deploy_id is not None:
        drow = next((d for d in deploys if d.get("id") == deploy_id), None)
        if drow is None:
            return _err("NOT_FOUND", "Deploy not found.", deploy_id=deploy_id)
    else:
        # Resolve by netlify_deploy_id, optional site_id scoping
        candidates = [d for d in deploys if d.get("netlify_deploy_id") == netlify_deploy_id]
        if site_id is not None:
            candidates = [d for d in candidates if d.get("site_id") == site_id]
        if len(candidates) == 0:
            return _err("NOT_FOUND", "Deploy not found.", netlify_deploy_id=netlify_deploy_id)
        drow = candidates[0]

    # Resolve site and enforce belongs to active account
    srow = next((s for s in sites if s.get("id") == drow.get("site_id")), None)
    if srow is None:
        return _err("NOT_FOUND", "Deploy's site not found.", deploy_id=drow.get("id"))
    if srow.get("account_id") != acct_id:
        return _err("UNAUTHORIZED", "Deploy does not belong to the active account.", deploy_id=drow.get("id"))

    # Create session event
    session_id = _new_id("nlt_evt")
    started_at = _now_iso()
    session = {
        "id": session_id,
        "account_id": acct_id,
        "site_id": srow.get("id"),
        "deploy_id": drow.get("id"),
        "event_type": "log_stream_session",  # closest session type available; watch-deploy is a session watcher
        "status": "running",
        "request": {
            "deploy_id": drow.get("id"),
            "netlify_deploy_id": drow.get("netlify_deploy_id"),
            "poll_interval_seconds": poll_interval_seconds,
            "until_status": until_status,
            "include_logs": include_logs,
            "since": since,
            "timeout_seconds": timeout_seconds,
        },
        "response": None,
        "http_method": None,
        "http_path": None,
        "http_status_code": None,
        "error_message": None,
        "started_at": started_at,
        "ended_at": None,
        "created_at": started_at,
        "updated_at": started_at,
    }
    events.append(session)
    _save("observability_events.json", events)

    # Emit status updates from local datastore (offline): poll deploy row and any log_line events for this deploy.
    # We do not fabricate Netlify updates; we just observe mutations caused by other tools.
    terminal = set(until_status)
    deadline = time.time() + timeout_seconds

    def _fetch_deploy():
        ds = _load("deploys.json")
        return next((d for d in ds if d.get("id") == drow.get("id")), None), ds

    def _collect_logs(after_iso):
        evs = _load("observability_events.json")
        out = []
        for e in evs:
            if e.get("event_type") != "log_line":
                continue
            if e.get("account_id") != acct_id:
                continue
            if e.get("deploy_id") != drow.get("id"):
                continue
            ts = e.get("created_at") or e.get("started_at")
            if after_iso is not None and isinstance(ts, str) and ts < after_iso:
                continue
            out.append(e)
        out.sort(key=lambda x: (x.get("created_at") or "", x.get("id") or ""))
        return out

    last_status = None
    emitted_logs = set()
    since_iso = None
    if since_dt is not None:
        # Convert to comparable ISO "Z"
        if since_dt.tzinfo is not None:
            since_dt = since_dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
        since_iso = since_dt.replace(microsecond=0).isoformat() + "Z"

    updates = []
    final_state = None

    try:
        while True:
            if time.time() > deadline:
                final_state = "completed"
                break

            cur, _ = _fetch_deploy()
            if cur is None:
                final_state = "failed"
                # Update session to failed below
                break

            st = cur.get("status")
            if st != last_status:
                updates.append({
                    "type": "status_update",
                    "timestamp": _now_iso(),
                    "deploy_id": cur.get("id"),
                    "netlify_deploy_id": cur.get("netlify_deploy_id"),
                    "status": st,
                    "is_production": cur.get("is_production"),
                    "deploy_url": cur.get("deploy_url"),
                    "admin_url": cur.get("admin_url"),
                })
                last_status = st

            if include_logs:
                logs = _collect_logs(since_iso)
                for l in logs:
                    lid = l.get("id")
                    if lid in emitted_logs:
                        continue
                    updates.append({
                        "type": "log_line",
                        "timestamp": l.get("created_at") or _now_iso(),
                        "deploy_id": l.get("deploy_id"),
                        "message": (l.get("response") or l.get("request") or l.get("error_message") or ""),
                    })
                    emitted_logs.add(lid)

            if isinstance(st, str) and st in terminal:
                final_state = "completed"
                break

            time.sleep(poll_interval_seconds)

    except Exception:
        # Unexpected bug; session should be marked failed
        final_state = "failed"

    ended_at = _now_iso()
    # Update session event terminal state
    events2 = _load("observability_events.json")
    for e in events2:
        if e.get("id") == session_id:
            if final_state == "completed":
                e["status"] = "completed"
            else:
                e["status"] = "failed"
                e["error_message"] = "Watch session failed." if final_state == "failed" else None
            e["ended_at"] = ended_at
            e["updated_at"] = ended_at
            e["response"] = {
                "updates_emitted": len(updates),
                "last_status": last_status,
                "timeout_seconds": timeout_seconds,
            }
            break
    _save("observability_events.json", events2)

    return {
        "session": {
            "event_id": session_id,
            "status": "completed" if final_state == "completed" else "failed",
            "started_at": started_at,
            "ended_at": ended_at,
        },
        "deploy": {
            "id": drow.get("id"),
            "site_id": drow.get("site_id"),
            "netlify_deploy_id": drow.get("netlify_deploy_id"),
        },
        "updates": updates,
        "meta": {
            "has_more": False,
            "terminal_statuses": list(until_status),
        }
    }

def manage_form(site_id, action, form_id=None, export_format=None, from_=None, to=None, **_extra):
    import json, os, datetime, time, uuid, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0414000" if __import__("os").path.isdir("./environment_mix/0414000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(v, field):
        if v is None:
            return None
        if not isinstance(v, str):
            return None, _err("VALIDATION_ERROR", f"Field '{field}' must be an RFC3339 date-time string.")
        s = v.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(s)
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"Field '{field}' must be an RFC3339 date-time string.")
        if dt.tzinfo is None:
            return None, _err("VALIDATION_ERROR", f"Field '{field}' must include a timezone offset.")
        return dt, None

    def _gen_id(prefix):
        return f"{prefix}{uuid.uuid4().hex}"

    def _record_event(accounts, events, account_id, status, request_obj, response_obj=None, error_message=None):
        eid = _gen_id("nlt_evt_")
        now = _now()
        ev = {
            "id": eid,
            "account_id": account_id,
            "site_id": request_obj.get("site_id"),
            "deploy_id": None,
            "event_type": "form_manage_action",
            "status": status,
            "request": request_obj,
            "response": response_obj,
            "http_method": None,
            "http_path": None,
            "http_status_code": None,
            "error_message": error_message,
            "started_at": now,
            "ended_at": now if status in ("completed", "failed", "canceled") else None,
            "created_at": now,
            "updated_at": now,
        }
        events.append(ev)
        _save("observability_events.json", events)
        return ev

    def _rate_limit_check(events, account_id):
        now = datetime.datetime.now(datetime.timezone.utc)
        window_start = now - datetime.timedelta(seconds=60)
        active_statuses = {"queued", "running"}
        active_count = 0
        for e in events:
            if e.get("account_id") != account_id:
                continue
            if e.get("status") not in active_statuses:
                continue
            started = e.get("started_at")
            if not started or not isinstance(started, str):
                continue
            s = started
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
            except ValueError:
                continue
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            if dt >= window_start:
                active_count += 1
        if active_count >= 60:
            retry_after = 60
            return _err("RATE_LIMIT", "Rate limit exceeded: at most 60 tool executions per minute.", retry_after_seconds=retry_after)
        return None

    # Validate inputs
    if not isinstance(site_id, str) or not re.match(r"^nlt_site_[0-9A-Z]{10,}$", site_id):
        # Record event best-effort after auth resolution; but auth requires active account. Validate first per contract.
        return _err("VALIDATION_ERROR", "Invalid 'site_id' format.")
    if not isinstance(action, str) or action not in ("enable", "disable", "delete", "export"):
        return _err("VALIDATION_ERROR", "Invalid 'action'. Must be one of: enable, disable, delete, export.")
    if action in ("enable", "disable", "delete", "export"):
        if form_id is None or not isinstance(form_id, str) or not form_id.strip():
            return _err("VALIDATION_ERROR", "Field 'form_id' is required for this action and must be a non-empty string.")
    if action == "export":
        if export_format is None or not isinstance(export_format, str) or export_format not in ("csv", "json"):
            return _err("VALIDATION_ERROR", "Field 'export_format' is required for export and must be one of: csv, json.")

    from_dt = None
    to_dt = None
    if from_ is not None:
        from_dt, e = _parse_dt(from_, "from")
        if e:
            return e
    if to is not None:
        to_dt, e = _parse_dt(to, "to")
        if e:
            return e
    if from_dt and to_dt and from_dt > to_dt:
        return _err("VALIDATION_ERROR", "Invalid date range: 'from' must be <= 'to'.")

    # Resolve ambient authentication: choose an active connected account that can serve the call
    accounts = _load("netlify_accounts.json")
    active_accounts = [a for a in accounts if a.get("is_active") is True and a.get("status") in ("connected", "error") and isinstance(a.get("access_token_ciphertext"), str) and a.get("access_token_ciphertext")]
    if not active_accounts:
        return _err("UNAUTHORIZED", "No active Netlify account is connected.")
    account = active_accounts[0]

    events = _load("observability_events.json")
    rl = _rate_limit_check(events, account.get("id"))
    if rl:
        # Log the rejected attempt
        _record_event(
            accounts, events, account.get("id"),
            "failed",
            {"site_id": site_id, "action": action, "form_id": form_id, "export_format": export_format, "from": from_, "to": to},
            response_obj=None,
            error_message=rl["error"]["message"],
        )
        rl["error"]["retry_after_seconds"] = rl["error"].get("retry_after_seconds", 60)
        return rl

    # Load and validate site preconditions
    sites = _load("sites.json")
    site = next((s for s in sites if s.get("id") == site_id), None)
    if not site:
        ev = _record_event(
            accounts, events, account.get("id"),
            "failed",
            {"site_id": site_id, "action": action, "form_id": form_id, "export_format": export_format, "from": from_, "to": to},
            response_obj=None,
            error_message="Site not found.",
        )
        return _err("NOT_FOUND", "Site not found.", event_id=ev["id"])
    if site.get("account_id") != account.get("id"):
        ev = _record_event(
            accounts, events, account.get("id"),
            "failed",
            {"site_id": site_id, "action": action, "form_id": form_id, "export_format": export_format, "from": from_, "to": to},
            response_obj=None,
            error_message="Site does not belong to the active account.",
        )
        return _err("UNAUTHORIZED", "Site is not accessible under the active account.", event_id=ev["id"])
    if site.get("status") != "active":
        ev = _record_event(
            accounts, events, account.get("id"),
            "failed",
            {"site_id": site_id, "action": action, "form_id": form_id, "export_format": export_format, "from": from_, "to": to},
            response_obj=None,
            error_message="Site is not active.",
        )
        return _err("INVALID_TRANSITION", "Operation allowed only on active sites.", event_id=ev["id"])
    if not site.get("is_linked") or not site.get("local_repo_root"):
        ev = _record_event(
            accounts, events, account.get("id"),
            "failed",
            {"site_id": site_id, "action": action, "form_id": form_id, "export_format": export_format, "from": from_, "to": to},
            response_obj=None,
            error_message="Site is not linked locally.",
        )
        return _err("NOT_FOUND", "Site is not linked locally.", event_id=ev["id"])

    # Internal validation: destructive actions require explicit action (already required by tool), but enforce.
    if action in ("delete",) and action is None:
        return _err("VALIDATION_ERROR", "Destructive form actions require an explicit 'action'.")

    # Perform action (offline): record an audit/snapshot
    request_obj = {"site_id": site_id, "action": action, "form_id": form_id, "export_format": export_format, "from": from_, "to": to}

    # Start/complete event in one go since this is synchronous
    if action in ("enable", "disable", "delete"):
        response_obj = {
            "site_id": site_id,
            "form_id": form_id,
            "action": action,
            "result": "accepted",
        }
        ev = _record_event(accounts, events, account.get("id"), "completed", request_obj, response_obj=response_obj)
        return {
            "event_id": ev["id"],
            "account_id": account.get("id"),
            "site_id": site_id,
            "action": action,
            "form_id": form_id,
            "result": response_obj["result"],
            "latency_ms": int((time.time() - t0) * 1000),
        }

    # export
    # Produce a deterministic offline export payload based on existing observability events for this site (sanitized),
    # filtered by time if provided.
    def _dt_from_event(e):
        s = e.get("created_at") or e.get("started_at")
        if not isinstance(s, str):
            return None
        x = s
        if x.endswith("Z"):
            x = x[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(x)
        except ValueError:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt

    submissions = []
    for e in events:
        if e.get("site_id") != site_id:
            continue
        # Treat some events as "submissions" for offline export purposes
        if e.get("event_type") not in ("form_manage_action", "forms_snapshot"):
            continue
        dt = _dt_from_event(e)
        if dt is None:
            continue
        if from_dt and dt < from_dt:
            continue
        if to_dt and dt > to_dt:
            continue
        submissions.append({
            "timestamp": dt.isoformat(),
            "event_id": e.get("id"),
            "type": e.get("event_type"),
            "status": e.get("status"),
        })

    # Sort oldest->newest
    submissions.sort(key=lambda r: r.get("timestamp") or "")

    if export_format == "json":
        export_payload = {"form_id": form_id, "site_id": site_id, "count": len(submissions), "submissions": submissions}
        response_obj = {"export_format": "json", "count": len(submissions)}
        ev = _record_event(accounts, events, account.get("id"), "completed", request_obj, response_obj=response_obj)
        return {
            "event_id": ev["id"],
            "account_id": account.get("id"),
            "site_id": site_id,
            "form_id": form_id,
            "export_format": "json",
            "data": export_payload,
            "latency_ms": int((time.time() - t0) * 1000),
        }

    # csv
    def _csv_escape(val):
        if val is None:
            val = ""
        val = str(val)
        if any(c in val for c in [",", '"', "\n", "\r"]):
            val = '"' + val.replace('"', '""') + '"'
        return val

    header = ["timestamp", "event_id", "type", "status"]
    lines = [",".join(header)]
    for r in submissions:
        lines.append(",".join([_csv_escape(r.get(h)) for h in header]))
    csv_text = "\n".join(lines)

    response_obj = {"export_format": "csv", "count": len(submissions)}
    ev = _record_event(accounts, events, account.get("id"), "completed", request_obj, response_obj=response_obj)
    return {
        "event_id": ev["id"],
        "account_id": account.get("id"),
        "site_id": site_id,
        "form_id": form_id,
        "export_format": "csv",
        "data": csv_text,
        "latency_ms": int((time.time() - t0) * 1000),
    }

_DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0414000" if __import__("os").path.isdir("./environment_mix/0414000") else "/app/database")
def get_analytics(**_extra):
    import json, os
    _ds_path = os.path.join(_DB, "dataset.json")
    try:
        _ds = json.load(open(_ds_path, encoding="utf-8"))
    except Exception:
        _ds = {"records": []}
    _records = _ds.get("records", [])
    _verb = 'get'
    _kwargs = {k: v for k, v in locals().items() if k not in ("json", "os", "_ds_path", "_ds", "_records", "_verb", "_kwargs") and not k.startswith("_")}
    try:
        _kwargs.update({k: v for k, v in _extra.items() if v is not None})
    except Exception:
        pass
    _id_param = None
    _query_param = None
    if _verb in ("search", "list"):
        _out = list(_records)
        if _query_param and _kwargs.get(_query_param):
            _qq = str(_kwargs[_query_param]).lower()
            _f = [r for r in _records if _qq in json.dumps(r, default=str).lower()]
            _out = _f if _f else _records
        _limit = None
        for _lk in ("limit", "count", "numResults", "num_results", "page_size", "max_results", "top_k", "n", "k"):
            if _lk in _kwargs and isinstance(_kwargs.get(_lk), (int, float)):
                _limit = int(_kwargs[_lk]); break
        if _limit:
            _out = _out[:_limit]
        return {"results": _out, "count": len(_out), "query": _kwargs.get(_query_param) if _query_param else None}
    if _verb == "get":
        if _id_param and _kwargs.get(_id_param) is not None:
            _key = str(_kwargs[_id_param])
            for r in _records:
                if str(r.get("id")) == _key or _key in [str(v) for v in r.values()]:
                    return r
        return _records[0] if _records else {"error": "not found", "args": _kwargs}
    if _verb == "create":
        _new = {"id": "get_an_new_" + str(len(_records) + 1)}
        _new.update({k: v for k, v in _kwargs.items() if v is not None})
        return {"created": True, "record": _new}
    if _verb == "update":
        _base = dict(_records[0]) if _records else {}
        _base.update({k: v for k, v in _kwargs.items() if v is not None})
        return {"updated": True, "record": _base}
    if _verb == "delete":
        return {"deleted": True, "args": {k: v for k, v in _kwargs.items() if v is not None}}
    # generic action: acknowledge with a representative record
    return {"ok": True, "tool": 'get_analytics', "args": {k: v for k, v in _kwargs.items() if v is not None},
            "sample": _records[0] if _records else None}

def list_accounts(status=None, is_active=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0414000" if __import__("os").path.isdir("./environment_mix/0414000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, (int, float)):
            try:
                return datetime.datetime.fromtimestamp(v, tz=datetime.timezone.utc)
            except Exception:
                return None
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            try:
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        return None

    def _dt_key(v):
        dt = _parse_dt(v)
        if dt is None:
            return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(cur):
        if not isinstance(cur, str) or not cur:
            return None
        s = cur.strip()
        pad = "=" * (-len(s) % 4)
        try:
            raw = base64.urlsafe_b64decode((s + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return None
            return obj
        except Exception:
            return None

    def _req_fingerprint():
        payload = {
            "tool": "list-accounts",
            "status": status,
            "is_active": is_active,
            "limit": limit,
            "cursor": cursor,
            "sort": sort,
            "order": order,
        }
        b = json.dumps(payload, sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return hashlib.sha256(b).hexdigest()

    started = time.time()

    accounts = _load("netlify_accounts.json")
    events = _load("observability_events.json")

    # Resolve ambient auth: any active account is sufficient context for listing.
    active_account = None
    if isinstance(accounts, list):
        for a in accounts:
            if isinstance(a, dict) and a.get("is_active") is True:
                active_account = a
                break
    if active_account is None:
        # If there's no active row, there is no caller context.
        # Still record an audit event if we can associate it with some account? We cannot.
        return _err("UNAUTHORIZED", "No active Netlify account context is available.")

    # Rate limiting/quota: per account, at most 60 tool executions per minute in status running/queued.
    now = datetime.datetime.now(datetime.timezone.utc)
    window_start = now - datetime.timedelta(seconds=60)

    running_like = 0
    if isinstance(events, list):
        for ev in events:
            if not isinstance(ev, dict):
                continue
            if ev.get("account_id") != active_account.get("id"):
                continue
            if ev.get("status") not in ("queued", "running"):
                continue
            ca = _parse_dt(ev.get("created_at"))
            if ca is None:
                continue
            if ca.tzinfo is None:
                ca = ca.replace(tzinfo=datetime.timezone.utc)
            if ca >= window_start:
                running_like += 1

    if running_like >= 60:
        retry_after = 60
        return _err(
            "RATE_LIMIT",
            "Rate limit exceeded: at most 60 tool executions per minute.",
            retry_after=retry_after,
            limit=60,
            window_seconds=60,
        )

    # Validate inputs
    if status is not None:
        if not isinstance(status, str) or status not in ("connected", "revoked", "error"):
            return _err("VALIDATION_ERROR", "Invalid 'status'.", field="status")

    if is_active is not None:
        if not isinstance(is_active, bool):
            return _err("VALIDATION_ERROR", "Invalid 'is_active'. Must be boolean.", field="is_active")

    if limit is None:
        limit_val = 50
    else:
        if not isinstance(limit, int):
            return _err("VALIDATION_ERROR", "Invalid 'limit'. Must be integer.", field="limit")
        if limit < 1 or limit > 100:
            return _err("VALIDATION_ERROR", "Invalid 'limit'. Must be between 1 and 100.", field="limit")
        limit_val = limit

    if sort is None:
        sort_val = "created_at"
    else:
        if not isinstance(sort, str) or sort not in ("created_at", "updated_at", "display_name", "last_verified_at"):
            return _err("VALIDATION_ERROR", "Invalid 'sort'.", field="sort")
        sort_val = sort

    if order is None:
        order_val = "desc"
    else:
        if not isinstance(order, str) or order not in ("asc", "desc"):
            return _err("VALIDATION_ERROR", "Invalid 'order'.", field="order")
        order_val = order

    cur_obj = None
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor.strip():
            return _err("VALIDATION_ERROR", "Invalid 'cursor'.", field="cursor")
        cur_obj = _decode_cursor(cursor)
        if not cur_obj or cur_obj.get("tool") != "list-accounts":
            return _err("VALIDATION_ERROR", "Invalid 'cursor'.", field="cursor")
        # Ensure cursor was created for the same query shape (except cursor itself)
        expected_fp = _req_fingerprint()
        if cur_obj.get("fingerprint") != expected_fp:
            return _err("VALIDATION_ERROR", "Cursor does not match the current query parameters.", field="cursor")

    # Create a queued/running event for this request (observability)
    ev_id = "evt_" + hashlib.sha256((active_account.get("id", "") + _now_iso() + str(time.time())).encode("utf-8")).hexdigest()[:24]
    ev = {
        "id": ev_id,
        "account_id": active_account.get("id"),
        "site_id": None,
        "deploy_id": None,
        "event_type": "api_methods_snapshot",
        "status": "running",
        "request": {
            "tool": "list-accounts",
            "filters": {"status": status, "is_active": is_active},
            "pagination": {"limit": limit_val, "cursor": cursor},
            "sort": {"field": sort_val, "order": order_val},
        },
        "response": None,
        "http_method": None,
        "http_path": None,
        "http_status_code": None,
        "error_message": None,
        "started_at": _now_iso(),
        "ended_at": None,
        "created_at": _now_iso(),
        "updated_at": _now_iso(),
    }
    events.append(ev)
    _save("observability_events.json", events)

    # Query
    rows = [a for a in accounts if isinstance(a, dict)]
    if status is not None:
        rows = [a for a in rows if a.get("status") == status]
    if is_active is not None:
        rows = [a for a in rows if a.get("is_active") is is_active]

    reverse = (order_val == "desc")

    def sort_key(a):
        if sort_val in ("created_at", "updated_at", "last_verified_at"):
            return (_dt_key(a.get(sort_val)), a.get("id", ""))
        if sort_val == "display_name":
            v = a.get("display_name")
            if v is None:
                v = ""
            return (str(v).casefold(), a.get("id", ""))
        return (a.get("id", ""),)

    rows.sort(key=sort_key, reverse=reverse)

    start_index = 0
    if cur_obj is not None:
        # Cursor uses an integer offset (opaque to client), validated by fingerprint above.
        off = cur_obj.get("offset")
        if not isinstance(off, int) or off < 0:
            # Mark event failed
            ended = time.time()
            for e in events:
                if isinstance(e, dict) and e.get("id") == ev_id:
                    e["status"] = "failed"
                    e["error_message"] = "Invalid cursor offset."
                    e["ended_at"] = _now_iso()
                    e["updated_at"] = _now_iso()
                    break
            _save("observability_events.json", events)
            return _err("VALIDATION_ERROR", "Invalid 'cursor'.", field="cursor")
        start_index = off

    page = rows[start_index:start_index + limit_val]
    next_offset = start_index + len(page)
    has_more = next_offset < len(rows)
    next_cursor = None
    if has_more:
        next_cursor = _encode_cursor(
            {
                "tool": "list-accounts",
                "offset": next_offset,
                "fingerprint": _req_fingerprint(),
            }
        )

    result = {
        "accounts": page,
        "pagination": {
            "total": len(rows),
            "limit": limit_val,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
        },
        "sort": {"field": sort_val, "order": order_val},
        "active_account_id": active_account.get("id"),
    }

    # Update event to completed
    ended = time.time()
    latency_ms = int(round((ended - started) * 1000))
    for e in events:
        if isinstance(e, dict) and e.get("id") == ev_id:
            e["status"] = "completed"
            e["response"] = {
                "result_count": len(page),
                "total": len(rows),
                "has_more": has_more,
                "latency_ms": latency_ms,
            }
            e["ended_at"] = _now_iso()
            e["updated_at"] = _now_iso()
            break
    _save("observability_events.json", events)

    return result
